//! Alias support: `stgit.alias.*` config entries plus built-in defaults.

use std::ffi::OsString;

use anyhow::{anyhow, Result};
use indexmap::IndexMap;

use crate::config::Config;

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum AliasKind {
    Shell,
    StGit,
}

#[derive(Debug, Clone)]
pub struct Alias {
    pub name: String,
    pub kind: AliasKind,
    pub command: String,
}

impl Alias {
    pub fn new(name: &str, value: &str) -> Alias {
        if let Some(cmd) = value.strip_prefix('!') {
            Alias {
                name: name.to_string(),
                kind: AliasKind::Shell,
                command: cmd.to_string(),
            }
        } else {
            Alias {
                name: name.to_string(),
                kind: AliasKind::StGit,
                command: value.to_string(),
            }
        }
    }

    pub fn about(&self) -> String {
        match self.kind {
            AliasKind::Shell => format!("Alias for shell command `{}`", self.command),
            AliasKind::StGit => format!("Alias for `stg {}`", self.command),
        }
    }

    pub fn make_command(&self) -> clap::Command {
        clap::Command::new(self.name.clone())
            .about(self.about())
            .arg(
                clap::Arg::new("args")
                    .help("Extra arguments to aliased command")
                    .num_args(0..)
                    .allow_hyphen_values(true)
                    .trailing_var_arg(true)
                    .value_parser(clap::value_parser!(OsString)),
            )
            .arg(crate::argset::color_arg())
    }

    /// Split the alias's command string into words (shell-like splitting)
    pub fn split(&self) -> Result<Vec<String>> {
        split_words(&self.command).ok_or_else(|| anyhow!("bad alias for `{}`: unterminated quote", self.name))
    }
}

/// Split a string into words, honoring single quotes, double quotes and
/// backslash escapes, similar to how git splits aliases.
pub fn split_words(s: &str) -> Option<Vec<String>> {
    let mut words = Vec::new();
    let mut cur = String::new();
    let mut in_word = false;
    let mut chars = s.chars().peekable();
    while let Some(c) = chars.next() {
        match c {
            '\'' => {
                in_word = true;
                loop {
                    match chars.next() {
                        Some('\'') => break,
                        Some(ch) => cur.push(ch),
                        None => return None,
                    }
                }
            }
            '"' => {
                in_word = true;
                loop {
                    match chars.next() {
                        Some('"') => break,
                        Some('\\') => match chars.next() {
                            Some(ch) => cur.push(ch),
                            None => return None,
                        },
                        Some(ch) => cur.push(ch),
                        None => return None,
                    }
                }
            }
            '\\' => {
                in_word = true;
                match chars.next() {
                    Some(ch) => cur.push(ch),
                    None => return None,
                }
            }
            c if c.is_whitespace() => {
                if in_word {
                    words.push(std::mem::take(&mut cur));
                    in_word = false;
                }
            }
            c => {
                in_word = true;
                cur.push(c);
            }
        }
    }
    if in_word {
        words.push(cur);
    }
    Some(words)
}

pub fn default_aliases() -> IndexMap<String, Alias> {
    let mut map = IndexMap::new();
    for (name, value) in [
        ("add", "!git -C \"$GIT_PREFIX\" add"),
        ("mv", "!git -C \"$GIT_PREFIX\" mv"),
        ("resolved", "!git -C \"$GIT_PREFIX\" add"),
        ("rm", "!git -C \"$GIT_PREFIX\" rm"),
        ("status", "!git status -s"),
    ] {
        map.insert(name.to_string(), Alias::new(name, value));
    }
    map
}

/// Get aliases from config, excluding any names that collide with builtin commands.
pub fn get_aliases(config: Option<&Config>, is_builtin: impl Fn(&str) -> bool) -> IndexMap<String, Alias> {
    let mut aliases = default_aliases();
    if let Some(config) = config {
        for (key, value) in config.entries_with_prefix("stgit.alias.") {
            let name = &key["stgit.alias.".len()..];
            if name.is_empty() {
                continue;
            }
            match value {
                Some(value) => {
                    aliases.insert(name.to_string(), Alias::new(name, value));
                }
                None => {
                    aliases.shift_remove(name);
                }
            }
        }
    }
    aliases.retain(|name, _| !is_builtin(name));
    aliases.sort_keys();
    aliases
}
EOF
echo done"}

