{"command":"cat > /workspace/src/config.rs <<'EOF'
//! Git configuration access (via `git config --list`).

use std::path::Path;
use std::process::Command;

use anyhow::Result;

#[derive(Debug, Clone, Default)]
pub struct Config {
    /// Entries in order of appearance. Later entries override earlier ones.
    entries: Vec<(String, Option<String>)>,
}

impl Config {
    pub fn load(dir: Option<&Path>) -> Result<Config> {
        let mut cmd = Command::new("git");
        if let Some(dir) = dir {
            cmd.current_dir(dir);
        }
        cmd.args(["config", "--list", "-z"]);
        cmd.stdin(std::process::Stdio::null());
        cmd.stderr(std::process::Stdio::null());
        let output = cmd.output()?;
        let mut entries = Vec::new();
        for item in output.stdout.split(|b| *b == 0) {
            if item.is_empty() {
                continue;
            }
            let item = String::from_utf8_lossy(item).into_owned();
            match item.split_once('\n') {
                Some((k, v)) => entries.push((k.to_string(), Some(v.to_string()))),
                None => entries.push((item, None)),
            }
        }
        Ok(Config { entries })
    }

    pub fn empty() -> Config {
        Config::default()
    }

    /// Get the last value for the given key. The key's section and name
    /// components are compared case-insensitively.
    pub fn get(&self, key: &str) -> Option<&str> {
        let key = normalize_key(key);
        let mut found: Option<&Option<String>> = None;
        for (k, v) in &self.entries {
            if *k == key {
                found = Some(v);
            }
        }
        match found {
            Some(Some(v)) => Some(v.as_str()),
            Some(None) => Some(""),
            None => None,
        }
    }

    pub fn get_all(&self, key: &str) -> Vec<&str> {
        let key = normalize_key(key);
        self.entries
            .iter()
            .filter(|(k, _)| *k == key)
            .map(|(_, v)| v.as_deref().unwrap_or(""))
            .collect()
    }

    pub fn get_bool(&self, key: &str) -> Option<bool> {
        let v = self.get(key)?;
        parse_bool(v)
    }

    pub fn get_i64(&self, key: &str) -> Option<i64> {
        let v = self.get(key)?;
        parse_int(v)
    }

    /// Return entries whose keys begin with `prefix` (compared as-is), in order.
    pub fn entries_with_prefix<'a>(&'a self, prefix: &'a str) -> impl Iterator<Item = (&'a str, Option<&'a str>)> + 'a {
        self.entries
            .iter()
            .filter(move |(k, _)| k.starts_with(prefix))
            .map(|(k, v)| (k.as_str(), v.as_deref()))
    }

    pub fn is_empty(&self) -> bool {
        self.entries.is_empty()
    }
}

fn normalize_key(key: &str) -> String {
    // section and variable name are case insensitive; subsection is not.
    let parts: Vec<&str> = key.splitn(2, '.').collect();
    if parts.len() < 2 {
        return key.to_lowercase();
    }
    let section = parts[0].to_lowercase();
    let rest = parts[1];
    match rest.rsplit_once('.') {
        Some((subsection, name)) => format!("{section}.{subsection}.{}", name.to_lowercase()),
        None => format!("{section}.{}", rest.to_lowercase()),
    }
}

pub fn parse_bool(v: &str) -> Option<bool> {
    match v.to_lowercase().as_str() {
        "" | "true" | "yes" | "on" | "1" => Some(true),
        "false" | "no" | "off" | "0" => Some(false),
        _ => None,
    }
}

pub fn parse_int(v: &str) -> Option<i64> {
    let v = v.trim();
    let (num, mult) = if let Some(n) = v.strip_suffix(['k', 'K']) {
        (n, 1024)
    } else if let Some(n) = v.strip_suffix(['m', 'M']) {
        (n, 1024 * 1024)
    } else if let Some(n) = v.strip_suffix(['g', 'G']) {
        (n, 1024 * 1024 * 1024)
    } else {
        (v, 1)
    };
    num.parse::<i64>().ok().map(|n| n * mult)
}
EOF
echo ok"}

