//! Stacked Git (stg) -- a reimplementation.

mod alias;
mod argset;
mod color;
mod cmd;
mod config;
mod error;
mod git;
mod patch;
mod signature;
mod stack;
mod stupid;
mod util;
mod wrap;

use std::ffi::OsString;
use std::io::Write;
use std::path::PathBuf;

use anyhow::{anyhow, Result};
use clap::{Arg, ArgAction, ArgMatches, Command};

use crate::alias::{Alias, AliasKind};
use crate::color::ColorChoice;

pub(crate) const STG_VERSION: &str = "2.5.5";

fn main() {
    let code = run();
    std::process::exit(code);
}

fn version_arg() -> Arg {
    Arg::new("version")
        .long("version")
        .help("Print version information")
        .action(ArgAction::SetTrue)
}

fn change_dir_arg() -> Arg {
    Arg::new("change_dir")
        .short('C')
        .help("Run as if started in <path>")
        .long_help(
            "Run as if stg was started in '<path>' instead of the current working \
             directory. When multiple `-C` options are given, each subsequent non-absolute \
             `-C <path>` is interpreted relative to the preceding `-C <path>`.\n\
             \n\
             This option affects arguments that expect path names or path specs in that \
             their interpretations of the path names would be made relative to the working \
             directory caused by the `-C` option.",
        )
        .action(ArgAction::Append)
        .value_name("path")
        .value_parser(clap::value_parser!(PathBuf))
        .value_hint(clap::ValueHint::DirPath),
}

fn base_command() -> Command {
    Command::new("stg")
        .about("Maintain a stack of patches on top of a Git branch.")
        .override_usage(
            "stg [OPTIONS] <command> [...]\n       \
             stg [OPTIONS] <-h|--help>\n       \
             stg --version",
        )
        .max_term_width(88)
        .disable_version_flag(true)
        .arg(version_arg())
        .arg(change_dir_arg())
        .arg(argset::color_arg())
}

/// Command used for the initial pass over the command line.
fn pre_command() -> Command {
    base_command()
        .disable_help_flag(true)
        .allow_external_subcommands(true)
        .disable_help_subcommand(true)
        .arg(
            Arg::new("help")
                .short('h')
                .long("help")
                .action(ArgAction::SetTrue)
                .hide(true),
        )
}

fn full_command(aliases: &indexmap::IndexMap<String, Alias>) -> Command {
    let mut command = base_command()
        .arg_required_else_help(true)
        .help_template(make_help_template(aliases));
    for stgcmd in cmd::STGIT_COMMANDS {
        command = command.subcommand((stgcmd.make)());
    }
    for alias in aliases.values() {
        command = command.subcommand(alias.make_command());
    }
    command
}

fn make_help_template(aliases: &indexmap::IndexMap<String, Alias>) -> clap::builder::StyledStr {
    use clap::builder::styling::{AnsiColor, Effects, Style};
    let header = Style::new().bold().underline();
    let literal = Style::new().bold();
    let _ = (AnsiColor::Red, Effects::BOLD);

    let mut s = String::new();
    s.push_str("{about-with-newline}\n{usage-heading} {usage}\n\n");

    for category in cmd::CATEGORIES {
        let cmds: Vec<&cmd::StGitCommand> = cmd::STGIT_COMMANDS
            .iter()
            .filter(|c| c.category == *category)
            .collect();
        if cmds.is_empty() {
            continue;
        }
        let width = cmds.iter().map(|c| c.name.len()).max().unwrap_or(0);
        s.push_str(&format!("{header}{}:{header:#}\n", category.title()));
        for c in cmds {
            s.push_str(&format!(
                "  {literal}{}{literal:#}{}  {}\n",
                c.name,
                " ".repeat(width - c.name.len()),
                c.about
            ));
        }
        s.push('\n');
    }

    if !aliases.is_empty() {
        let width = aliases.keys().map(|k| k.len()).max().unwrap_or(0);
        s.push_str(&format!("{header}Aliases:{header:#}\n"));
        for alias in aliases.values() {
            s.push_str(&format!(
                "  {literal}{}{literal:#}{}  {}\n",
                alias.name,
                " ".repeat(width - alias.name.len()),
                alias.about()
            ));
        }
        s.push('\n');
    }

    s.push_str(&format!(
        "{header}Help:{header:#}\n  {literal}help{literal:#}  Print this message or the help of the given subcommand(s)\n\n"
    ));
    s.push_str(&format!("{header}Options:{header:#}\n{{options}}"));
    clap::builder::StyledStr::from(s)
}

fn run() -> i32 {
    let argv: Vec<OsString> = std::env::args_os().collect();

    // Initial pass: find -C, --color, --version.
    let pre_matches = match pre_command().try_get_matches_from(&argv) {
        Ok(m) => m,
        Err(e) => return print_clap_error(e),
    };

    if pre_matches.get_flag("version") {
        cmd::version::print_version(false);
        return 0;
    }

    let color_choice = get_color_choice(&pre_matches);

    if let Some(paths) = pre_matches.get_many::<PathBuf>("change_dir") {
        for path in paths {
            if path.as_os_str().is_empty() {
                continue;
            }
            if let Err(e) = std::env::set_current_dir(path) {
                return print_error(
                    &anyhow!("cannot change to `{}`: {}", path.display(), e),
                    color_choice,
                );
            }
        }
    }

    // Load config (works in and out of repositories) for aliases.
    let config = config::Config::load(None).unwrap_or_default();
    let aliases = alias::get_aliases(Some(&config), |name| cmd::find_command(name).is_some());

    let matches = match full_command(&aliases).try_get_matches_from(&argv) {
        Ok(m) => m,
        Err(e) => return print_clap_error(e),
    };

    let color_choice = get_color_choice(&matches);

    let (subname, submatches) = match matches.subcommand() {
        Some(sc) => sc,
        None => {
            // Should not happen given arg_required_else_help.
            return 1;
        }
    };

    if let Some(stgcmd) = cmd::find_command(subname) {
        let color_choice = submatches
            .get_one::<String>("color")
            .and_then(|s| ColorChoice::from_str(s))
            .unwrap_or(color_choice);
        match (stgcmd.run)(submatches, color_choice) {
            Ok(()) => 0,
            Err(e) => print_error(&e, color_choice),
        }
    } else if let Some(alias) = aliases.get(subname) {
        let color_choice = submatches
            .get_one::<String>("color")
            .and_then(|s| ColorChoice::from_str(s))
            .unwrap_or(color_choice);
        match execute_alias(alias, submatches, &aliases, color_choice) {
            Ok(code) => code,
            Err(e) => print_error(&e, color_choice),
        }
    } else {
        1
    }
}

fn get_color_choice(matches: &ArgMatches) -> ColorChoice {
    matches
        .get_one::<String>("color")
        .and_then(|s| ColorChoice::from_str(s))
        .unwrap_or(ColorChoice::Auto)
}

fn execute_alias(
    alias: &Alias,
    matches: &ArgMatches,
    aliases: &indexmap::IndexMap<String, Alias>,
    color_choice: ColorChoice,
) -> Result<i32> {
    let user_args: Vec<OsString> = matches
        .get_many::<OsString>("args")
        .map(|v| v.cloned().collect())
        .unwrap_or_default();

    match alias.kind {
        AliasKind::Shell => {
            let repo = git::Repository::open().ok();
            let mut command = std::process::Command::new("sh");
            command.arg("-c");
            let mut script = alias.command.clone();
            script.push_str(" \"$@\"");
            command.arg(script);
            command.arg(&alias.command);
            command.args(&user_args);
            if let Some(repo) = repo.as_ref() {
                if let Some(workdir) = repo.workdir() {
                    let cwd = std::env::current_dir()?;
                    let prefix = match cwd.strip_prefix(workdir) {
