//! Git object parsing.

use anyhow::{anyhow, Result};
use bstr::{BStr, BString, ByteSlice};

use super::Oid;
use crate::signature::Signature;

#[derive(Debug, Clone)]
pub struct Commit {
    pub id: Oid,
    pub tree_id: Oid,
    pub parent_ids: Vec<Oid>,
    pub author: Signature,
    pub committer: Signature,
    pub encoding: Option<String>,
    pub extra_headers: Vec<(String, BString)>,
    pub message: BString,
}

impl Commit {
    pub fn parse(id: Oid, data: &[u8]) -> Result<Commit> {
        let mut tree_id = None;
        let mut parent_ids = Vec::new();
        let mut author = None;
        let mut committer = None;
        let mut encoding = None;
        let mut extra_headers = Vec::new();
        let mut rest = data;
        loop {
            let (line, remaining) = match rest.find_byte(b'\n') {
                Some(pos) => (&rest[..pos], &rest[pos + 1..]),
                None => (rest, &rest[rest.len()..]),
            };
            rest = remaining;
            if line.is_empty() {
                break;
            }
            // handle continuation lines for multi-line headers (e.g. gpgsig)
            let (key, value) = match line.find_byte(b' ') {
                Some(pos) => (&line[..pos], &line[pos + 1..]),
                None => (line, &line[line.len()..]),
            };
            let mut value = BString::from(value);
            while rest.first() == Some(&b' ') {
                let (cont, remaining) = match rest.find_byte(b'\n') {
                    Some(pos) => (&rest[..pos], &rest[pos + 1..]),
                    None => (rest, &rest[rest.len()..]),
                };
                rest = remaining;
                value.push(b'\n');
                value.extend_from_slice(&cont[1..]);
            }
            match key {
                b"tree" => tree_id = Oid::from_hex(value.to_str_lossy().as_ref()),
                b"parent" => {
                    if let Some(oid) = Oid::from_hex(value.to_str_lossy().as_ref()) {
                        parent_ids.push(oid);
                    }
                }
                b"author" => author = Some(Signature::parse(value.as_bstr())?),
                b"committer" => committer = Some(Signature::parse(value.as_bstr())?),
                b"encoding" => encoding = Some(value.to_str_lossy().into_owned()),
                _ => extra_headers.push((key.to_str_lossy().into_owned(), value)),
            }
        }
        Ok(Commit {
            id,
            tree_id: tree_id.ok_or_else(|| anyhow!("commit `{id}` has no tree"))?,
            parent_ids,
            author: author.ok_or_else(|| anyhow!("commit `{id}` has no author"))?,
            committer: committer.ok_or_else(|| anyhow!("commit `{id}` has no committer"))?,
            encoding,
            extra_headers,
            message: BString::from(rest),
        })
    }

    pub fn message_str(&self) -> std::borrow::Cow<'_, str> {
        self.message.to_str_lossy()
    }

    /// First line of the commit message (summary).
    pub fn summary(&self) -> BString {
        let msg = self.message.as_bstr();
        let msg = msg.trim_start();
        let line = match msg.find_byte(b'\n') {
            Some(pos) => &msg[..pos],
            None => msg,
        };
        BString::from(line.trim_end())
    }

    pub fn summary_str(&self) -> String {
        self.summary().to_str_lossy().into_owned()
    }

    /// Serialize commit to raw object format.
    pub fn serialize(
        tree_id: &Oid,
        parent_ids: &[Oid],
        author: &Signature,
        committer: &Signature,
        encoding: Option<&str>,
        extra_headers: &[(String, BString)],
        message: &BStr,
    ) -> Vec<u8> {
        let mut out = Vec::new();
        out.extend_from_slice(format!("tree {tree_id}\n").as_bytes());
        for p in parent_ids {
            out.extend_from_slice(format!("parent {p}\n").as_bytes());
        }
        out.extend_from_slice(b"author ");
        out.extend_from_slice(&author.to_raw());
        out.push(b'\n');
        out.extend_from_slice(b"committer ");
        out.extend_from_slice(&committer.to_raw());
        out.push(b'\n');
        if let Some(enc) = encoding {
            out.extend_from_slice(format!("encoding {enc}\n").as_bytes());
        }
        for (k, v) in extra_headers {
            out.extend_from_slice(k.as_bytes());
            out.push(b' ');
            // continuation lines need a leading space
            let v = v.replace(b"\n", b"\n ");
            out.extend_from_slice(&v);
            out.push(b'\n');
        }
        out.push(b'\n');
        out.extend_from_slice(message);
        out
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct TreeEntry {
    pub mode: u32,
    pub name: BString,
    pub id: Oid,
}

impl TreeEntry {
    pub fn is_tree(&self) -> bool {
        self.mode & 0o170000 == 0o040000
    }
    pub fn is_commit(&self) -> bool {
        self.mode & 0o170000 == 0o160000
    }
    pub fn mode_str(&self) -> String {
        format!("{:06o}", self.mode)
    }
    pub fn kind(&self) -> &'static str {
        if self.is_tree() {
            "tree"
        } else if self.is_commit() {
            "commit"
        } else {
            "blob"
        }
    }
}

#[derive(Debug, Clone, Default)]
pub struct Tree {
    pub entries: Vec<TreeEntry>,
}

impl Tree {
    pub fn parse(data: &[u8]) -> Result<Tree> {
        let mut entries = Vec::new();
        let mut rest = data;
        while !rest.is_empty() {
            let sp = rest
                .find_byte(b' ')
                .ok_or_else(|| anyhow!("malformed tree object"))?;
            let mode = std::str::from_utf8(&rest[..sp])
                .ok()
                .and_then(|s| u32::from_str_radix(s, 8).ok())
                .ok_or_else(|| anyhow!("malformed tree mode"))?;
            rest = &rest[sp + 1..];
            let nul = rest
                .find_byte(0)
                .ok_or_else(|| anyhow!("malformed tree object"))?;
            let name = BString::from(&rest[..nul]);
            rest = &rest[nul + 1..];
            if rest.len() < 20 {
                return Err(anyhow!("malformed tree object"));
            }
            let id = Oid::from_bytes(&rest[..20]).unwrap();
            rest = &rest[20..];
            entries.push(TreeEntry { mode, name, id });
        }
        Ok(Tree { entries })
    }

    pub fn get(&self, name: &[u8]) -> Option<&TreeEntry> {
        self.entries.iter().find(|e| e.name.as_slice() == name)
    }

    /// Serialize in the format expected by `git mktree -z`.
    pub fn to_mktree_input(&self) -> Vec<u8> {
        let mut out = Vec::new();
        for e in &self.entries {
            out.extend_from_slice(format!("{} {} {}\t", e.mode_str(), e.kind(), e.id).as_bytes());
            out.extend_from_slice(&e.name);
            out.push(0);
        }
        out
    }
}
