//! Author/committer signatures and time handling.

use anyhow::{anyhow, Result};
use bstr::{BStr, BString, ByteSlice};

use crate::config::Config;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Time {
    pub seconds: i64,
    /// Offset from UTC in seconds.
    pub offset: i32,
}

impl Time {
    pub fn new(seconds: i64, offset: i32) -> Time {
        Time { seconds, offset }
    }

    pub fn now() -> Time {
        let seconds = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .map(|d| d.as_secs() as i64)
            .unwrap_or(0);
        Time {
            seconds,
            offset: local_offset(seconds),
        }
    }

    pub fn offset_str(&self) -> String {
        let sign = if self.offset < 0 { '-' } else { '+' };
        let abs = self.offset.abs();
        format!("{sign}{:02}{:02}", abs / 3600, (abs % 3600) / 60)
    }

    /// Raw git format: "<seconds> <+/-HHMM>"
    pub fn to_raw(&self) -> String {
        format!("{} {}", self.seconds, self.offset_str())
    }

    fn civil(&self) -> (i64, u32, u32, u32, u32, u32, u32) {
        // returns (year, month, day, hour, minute, second, weekday[0=Sunday])
        let local = self.seconds + self.offset as i64;
        let days = local.div_euclid(86400);
        let rem = local.rem_euclid(86400);
        let (y, m, d) = civil_from_days(days);
        let wd = ((days % 7 + 11) % 7) as u32; // 1970-01-01 was Thursday (4)
        (
            y,
            m,
            d,
            (rem / 3600) as u32,
            ((rem % 3600) / 60) as u32,
            (rem % 60) as u32,
            wd,
        )
    }

    /// "YYYY-MM-DD HH:MM:SS +ZZZZ"
    pub fn to_iso(&self) -> String {
        let (y, m, d, hh, mm, ss, _) = self.civil();
        format!("{y:04}-{m:02}-{d:02} {hh:02}:{mm:02}:{ss:02} {}", self.offset_str())
    }

    /// "Thu Apr 7 15:13:13 2005 -0700" (git default format)
    pub fn to_default(&self) -> String {
        let (y, m, d, hh, mm, ss, wd) = self.civil();
        format!(
            "{} {} {} {hh:02}:{mm:02}:{ss:02} {y} {}",
            WEEKDAYS[wd as usize],
            MONTHS[(m - 1) as usize],
            d,
            self.offset_str()
        )
    }

    /// "Thu, 7 Apr 2005 15:13:13 -0700" (RFC 2822)
    pub fn to_rfc2822(&self) -> String {
        let (y, m, d, hh, mm, ss, wd) = self.civil();
        format!(
            "{}, {} {} {y} {hh:02}:{mm:02}:{ss:02} {}",
            WEEKDAYS[wd as usize],
            d,
            MONTHS[(m - 1) as usize],
            self.offset_str()
        )
    }

    /// Parse a date string using the formats understood by StGit.
    pub fn parse(s: &str) -> Result<Time> {
        parse_time(s).ok_or_else(|| anyhow!("invalid date `{s}`"))
    }
}

const WEEKDAYS: [&str; 7] = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];
const MONTHS: [&str; 12] = [
    "Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec",
];

fn local_offset(seconds: i64) -> i32 {
    unsafe {
        let t: libc::time_t = seconds as libc::time_t;
        let mut tm: libc::tm = std::mem::zeroed();
        libc::tzset();
        if libc::localtime_r(&t, &mut tm).is_null() {
            0
        } else {
            tm.tm_gmtoff as i32
        }
    }
}

fn civil_from_days(z: i64) -> (i64, u32, u32) {
    let z = z + 719468;
    let era = z.div_euclid(146097);
    let doe = z.rem_euclid(146097);
    let yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;
    let y = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = (doy - (153 * mp + 2) / 5 + 1) as u32;
    let m = if mp < 10 { mp + 3 } else { mp - 9 } as u32;
    (if m <= 2 { y + 1 } else { y }, m, d)
}

pub fn days_from_civil(y: i64, m: u32, d: u32) -> i64 {
    let y = if m <= 2 { y - 1 } else { y };
    let era = y.div_euclid(400);
    let yoe = y.rem_euclid(400);
    let mp = if m > 2 { m - 3 } else { m + 9 } as i64;
    let doy = (153 * mp + 2) / 5 + d as i64 - 1;
    let doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;
    era * 146097 + doe - 719468
}

fn parse_offset(s: &str) -> Option<i32> {
    let s = s.trim();
    let (sign, rest) = if let Some(r) = s.strip_prefix('+') {
        (1, r)
    } else if let Some(r) = s.strip_prefix('-') {
        (-1, r)
    } else {
        return None;
    };
    let (h, m) = if rest.len() == 4 && rest.chars().all(|c| c.is_ascii_digit()) {
        (rest[..2].parse::<i32>().ok()?, rest[2..].parse::<i32>().ok()?)
    } else if rest.len() == 5 && &rest[2..3] == ":" {
        (rest[..2].parse::<i32>().ok()?, rest[3..].parse::<i32>().ok()?)
    } else {
        return None;
    };
    if m >= 60 {
        return None;
    }
    Some(sign * (h * 3600 + m * 60))
}

fn month_from_name(s: &str) -> Option<u32> {
    MONTHS
        .iter()
        .position(|m| m.eq_ignore_ascii_case(s))
        .map(|p| p as u32 + 1)
}

fn parse_hms(s: &str) -> Option<(u32, u32, u32)> {
    let parts: Vec<&str> = s.split(':').collect();
    if parts.len() != 3 {
        return None;
    }
    let h = parts[0].parse::<u32>().ok()?;
    let m = parts[1].parse::<u32>().ok()?;
    let sec = parts[2].parse::<u32>().ok()?;
    if h > 23 || m > 59 || sec > 60 {
        return None;
    }
    Some((h, m, sec))
}

fn parse_ymd(s: &str) -> Option<(i64, u32, u32)> {
    let parts: Vec<&str> = s.split('-').collect();
    if parts.len() != 3 || parts[0].len() != 4 || parts[1].len() != 2 || parts[2].len() != 2 {
        return None;
    }
    let y = parts[0].parse::<i64>().ok()?;
    let m = parts[1].parse::<u32>().ok()?;
    let d = parts[2].parse::<u32>().ok()?;
    if !(1..=12).contains(&m) || !(1..=31).contains(&d) {
        return None;
    }
    Some((y, m, d))
}

fn make_time(y: i64, m: u32, d: u32, hh: u32, mm: u32, ss: u32, offset: i32) -> Time {
    let days = days_from_civil(y, m, d);
    let local = days * 86400 + hh as i64 * 3600 + mm as i64 * 60 + ss as i64;
    Time {
        seconds: local - offset as i64,
        offset,
    }
}

pub fn parse_time(s: &str) -> Option<Time> {
    let s = s.trim();
    if s.is_empty() {
        return None;
    }
    // raw: "<seconds> <offset>" or "<seconds>"
    {
        let mut it = s.split_whitespace();
        let first = it.next()?;
        if first.chars().all(|c| c.is_ascii_digit()) {
            let seconds = first.parse::<i64>().ok()?;
            match it.next() {
                None => return Some(Time::new(seconds, 0)),
                Some(off) => {
                    if it.next().is_none() {
                        if let Some(offset) = parse_offset(off) {
                            return Some(Time::new(seconds, offset));
                        }
                    }
                    return None;
                }
            }
        }
    }
    // RFC 2822: "Thu, 01 Jan 2015 10:00:00 +0200" or "Thu, 1 Jan 2015 10:00:00 +0200"
    if let Some((_wd, rest)) = s.split_once(',') {
        let parts: Vec<&str> = rest.split_whitespace().collect();
        if parts.len() == 5 {
            let d = parts[0].parse::<u32>().ok()?;
            let m = month_from_name(parts[1])?;
            let y = parts[2].parse::<i64>().ok()?;
            let (hh, mm, ss) = parse_hms(parts[3])?;
            let offset = parse_offset(parts[4])?;
            return Some(make_time(y, m, d, hh, mm, ss, offset));
        }
        return None;
    }
    // git default: "Thu Jan 1 10:00:00 2015 +0200"
    {
        let parts: Vec<&str> = s.split_whitespace().collect();
        if parts.len() == 6 && month_from_name(parts[1]).is_some() {
            let m = month_from_name(parts[1])?;
            let d = parts[2].parse::<u32>().ok()?;
            let (hh, mm, ss) = parse_hms(parts[3])?;
            let y = parts[4].parse::<i64>().ok()?;
            let offset = parse_offset(parts[5])?;
            return Some(make_time(y, m, d, hh, mm, ss, offset));
        }
        // ISO-ish: "2015-01-01 10:00:00 +0200"
        if parts.len() == 3 {
            let (y, m, d) = parse_ymd(parts[0])?;
            let (hh, mm, ss) = parse_hms(parts[1])?;
            let off = parts[2];
            if off.len() != 5 {
                return None;
            }
            let offset = parse_offset(off)?;
            return Some(make_time(y, m, d, hh, mm, ss, offset));
        }
        // RFC 3339: "2015-01-01T10:00:00+02:00"
        if parts.len() == 1 {
            if let Some((date, rest)) = s.split_once('T') {
                let (y, m, d) = parse_ymd(date)?;
                let pos = rest.find(['+', '-'])?;
                let (hms, off) = rest.split_at(pos);
                let (hh, mm, ss) = parse_hms(hms)?;
                if off.len() != 6 {
                    return None;
                }
                let offset = parse_offset(off)?;
                return Some(make_time(y, m, d, hh, mm, ss, offset));
            }
            // date only "2015-01-01"
            let (y, m, d) = parse_ymd(s)?;
            return Some(make_time(y, m, d, 0, 0, 0, 0));
        }
    }
    None
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Signature {
    pub name: BString,
    pub email: BString,
    pub time: Time,
}

impl Signature {
    pub fn new(name: impl Into<BString>, email: impl Into<BString>, time: Time) -> Signature {
        Signature {
            name: name.into(),
            email: email.into(),
            time,
        }
    }

    /// Parse "Name <email> 1234567890 +0000"
    pub fn parse(raw: &BStr) -> Result<Signature> {
        let lt = raw
            .rfind_byte(b'<')
            .ok_or_else(|| anyhow!("invalid signature `{}`", raw))?;
        let gt = raw[lt..]
            .find_byte(b'>')
            .map(|p| p + lt)
            .ok_or_else(|| anyhow!("invalid signature `{}`", raw))?;
        let name = BString::from(raw[..lt].trim());
        let email = BString::from(&raw[lt + 1..gt]);
        let rest = raw[gt + 1..].trim();
        let time = if rest.is_empty() {
            Time::new(0, 0)
        } else {
            let rest = rest.to_str_lossy();
            let mut it = rest.split_whitespace();
            let seconds = it
                .next()
                .and_then(|s| s.parse::<i64>().ok())
                .ok_or_else(|| anyhow!("invalid signature time `{}`", raw))?;
            let offset = it.next().and_then(parse_offset).unwrap_or(0);
            Time::new(seconds, offset)
        };
        Ok(Signature { name, email, time })
    }

    /// Parse "Name <email>" (no time). Name may be empty.
    pub fn parse_name_email(s: &str) -> Result<(BString, BString)> {
        let err = || anyhow!("invalid name and email `{s}`");
        let lt = s.rfind('<').ok_or_else(err)?;
        let gt = s[lt..].find('>').map(|p| p + lt).ok_or_else(err)?;
        if gt != s.len() - 1 {
            return Err(err());
        }
        let name = s[..lt].trim();
        let email = &s[lt + 1..gt];
        Ok((BString::from(name), BString::from(email)))
    }

    pub fn to_raw(&self) -> Vec<u8> {
        let mut out = Vec::new();
        out.extend_from_slice(&self.name);
        out.extend_from_slice(b" <");
        out.extend_from_slice(&self.email);
        out.extend_from_slice(b"> ");
        out.extend_from_slice(self.time.to_raw().as_bytes());
        out
    }

    /// "Name <email>"
    pub fn name_email(&self) -> String {
        format!("{} <{}>", self.name.to_str_lossy(), self.email.to_str_lossy())
    }

    pub fn with_time(&self, time: Time) -> Signature {
        Signature {
            name: self.name.clone(),
            email: self.email.clone(),
            time,
        }
    }

    pub fn same_person(&self, other: &Signature) -> bool {
        self.name == other.name && self.email == other.email
    }

    /// Default committer signature from environment and config.
    pub fn default_committer(config: &Config) -> Result<Signature> {
        let name = std::env::var("GIT_COMMITTER_NAME")
            .ok()
            .filter(|s| !s.is_empty())
            .or_else(|| config.get("user.name").map(|s| s.to_string()));
        let email = std::env::var("GIT_COMMITTER_EMAIL")
            .ok()
            .filter(|s| !s.is_empty())
            .or_else(|| config.get("user.email").map(|s| s.to_string()))
            .or_else(|| std::env::var("EMAIL").ok().filter(|s| !s.is_empty()));
        let (name, email) = match (name, email) {
            (Some(n), Some(e)) => (n, e),
            _ => {
                return Err(anyhow!(
                    "committer identity unknown; please configure `user.name` and `user.email`."
                ))
            }
        };
        let time = std::env::var("GIT_COMMITTER_DATE")
            .ok()
            .and_then(|s| parse_time(&s))
            .unwrap_or_else(Time::now);
        Ok(Signature::new(name, email, time))
    }

    /// Default author signature from environment and config.
    pub fn default_author(config: &Config) -> Result<Signature> {
        let name = std::env::var("GIT_AUTHOR_NAME")
            .ok()
            .filter(|s| !s.is_empty())
            .or_else(|| config.get("user.name").map(|s| s.to_string()));
        let email = std::env::var("GIT_AUTHOR_EMAIL")
            .ok()
            .filter(|s| !s.is_empty())
            .or_else(|| config.get("user.email").map(|s| s.to_string()))
            .or_else(|| std::env::var("EMAIL").ok().filter(|s| !s.is_empty()));
        let (name, email) = match (name, email) {
            (Some(n), Some(e)) => (n, e),
            _ => {
                return Err(anyhow!(
                    "author identity unknown; please configure `user.name` and `user.email`."
                ))
            }
        };
        let time = std::env::var("GIT_AUTHOR_DATE")
            .ok()
            .and_then(|s| parse_time(&s))
            .unwrap_or_else(Time::now);
        Ok(Signature::new(name, email, time))
    }
}
