cat > /workspace/src/git/repo.rs <<'EOF'
use std::cell::RefCell;
use std::collections::HashMap;
use std::ffi::OsStr;
use std::io::{BufRead, BufReader, Read, Write};
use std::path::{Path, PathBuf};
use std::process::{Child, ChildStdin, ChildStdout, Command, Stdio};
use std::rc::Rc;

use anyhow::{anyhow, Context, Result};
use bstr::{BStr, BString, ByteSlice};

use super::{Commit, Oid, Tree};
use crate::config::Config;
use crate::signature::Signature;

pub struct CommandOutput {
    pub status: std::process::ExitStatus,
    pub stdout: Vec<u8>,
    pub stderr: Vec<u8>,
}

impl CommandOutput {
    pub fn success(&self) -> bool {
        self.status.success()
    }
    pub fn stdout_str(&self) -> String {
        String::from_utf8_lossy(&self.stdout).into_owned()
    }
    pub fn stderr_str(&self) -> String {
        String::from_utf8_lossy(&self.stderr).into_owned()
    }
}

struct CatFile {
    child: Child,
    stdin: ChildStdin,
    stdout: BufReader<ChildStdout>,
}

impl Drop for CatFile {
    fn drop(&mut self) {
        let _ = self.child.kill();
        let _ = self.child.wait();
    }
}

pub struct Repository {
    pub git_dir: PathBuf,
    pub workdir: Option<PathBuf>,
    pub config: Config,
    catfile: RefCell<Option<CatFile>>,
    commit_cache: RefCell<HashMap<Oid, Rc<Commit>>>,
    tree_cache: RefCell<HashMap<Oid, Rc<Tree>>>,
}

impl Repository {
    pub fn open() -> Result<Repository> {
        let output = Command::new("git")
            .args(["rev-parse", "--absolute-git-dir", "--is-bare-repository", "--show-toplevel"])
            .stdin(Stdio::null())
            .stderr(Stdio::piped())
            .stdout(Stdio::piped())
            .output()
            .context("failed to run `git`")?;
        if !output.status.success() {
            let stderr = String::from_utf8_lossy(&output.stderr);
            if stderr.contains("not a git repository") || stderr.is_empty() {
                return Err(anyhow!(
                    "Could not find a git repository in '.' or in any of its parents"
                ));
            }
            return Err(anyhow!("{}", stderr.trim_end()));
        }
        let stdout = String::from_utf8_lossy(&output.stdout);
        let mut lines = stdout.lines();
        let git_dir = PathBuf::from(lines.next().unwrap_or(".git"));
        let is_bare = lines.next().unwrap_or("false") == "true";
        let workdir = lines.next().map(PathBuf::from);
        if is_bare || workdir.is_none() {
            // Inside the .git directory or a bare repository.
            if workdir.is_none() && !is_bare {
                let cwd = std::env::current_dir().unwrap_or_default();
                let rel = pathdiff(&git_dir, &cwd);
                return Err(anyhow!("'{}/objects' wasn't a directory", rel));
            }
        }
        let config = Config::load(None)?;
        Ok(Repository {
            git_dir,
            workdir,
            config,
            catfile: RefCell::new(None),
            commit_cache: RefCell::new(HashMap::new()),
            tree_cache: RefCell::new(HashMap::new()),
        })
    }

    pub fn workdir(&self) -> Option<&Path> {
        self.workdir.as_deref()
    }

    pub fn is_bare(&self) -> bool {
        self.workdir.is_none()
    }

    /// Build a git `Command` with the repository as its working directory.
    pub fn git_command(&self) -> Command {
        let mut cmd = Command::new("git");
        if let Some(workdir) = &self.workdir {
            cmd.current_dir(workdir);
        }
        cmd.stdin(Stdio::null());
        cmd
    }

    /// Run a git command, capturing output.
    pub fn git_output<I, S>(&self, args: I) -> Result<CommandOutput>
    where
        I: IntoIterator<Item = S>,
        S: AsRef<OsStr>,
    {
        let mut cmd = self.git_command();
        cmd.args(args);
        cmd.stdout(Stdio::piped()).stderr(Stdio::piped());
        let output = cmd.output().context("failed to run `git`")?;
        Ok(CommandOutput {
            status: output.status,
            stdout: output.stdout,
            stderr: output.stderr,
        })
    }

    /// Run a git command with stdin data, capturing output.
    pub fn git_output_with_input<I, S>(&self, args: I, input: &[u8]) -> Result<CommandOutput>
    where
        I: IntoIterator<Item = S>,
        S: AsRef<OsStr>,
    {
        let mut cmd = self.git_command();
        cmd.args(args);
        cmd.stdin(Stdio::piped())
            .stdout(Stdio::piped())
            .stderr(Stdio::piped());
        let mut child = cmd.spawn().context("failed to run `git`")?;
        {
            let mut stdin = child.stdin.take().unwrap();
            // Ignore broken pipe errors on write.
            let _ = stdin.write_all(input);
        }
        let output = child.wait_with_output()?;
        Ok(CommandOutput {
            status: output.status,
            stdout: output.stdout,
            stderr: output.stderr,
        })
    }

    /// Run git command and return stdout; error with git's stderr on failure.
    pub fn git_ok<I, S>(&self, name: &str, args: I) -> Result<Vec<u8>>
    where
        I: IntoIterator<Item = S>,
        S: AsRef<OsStr>,
    {
        let out = self.git_output(args)?;
        if out.success() {
            Ok(out.stdout)
        } else {
            Err(git_error(name, &out))
        }
    }

    // ---- object database ----

    fn with_catfile<R>(&self, f: impl FnOnce(&mut CatFile) -> Result<R>) -> Result<R> {
        let mut guard = self.catfile.borrow_mut();
        if guard.is_none() {
            let mut cmd = self.git_command();
            cmd.args(["cat-file", "--batch"]);
            cmd.stdin(Stdio::piped())
                .stdout(Stdio::piped())
                .stderr(Stdio::null());
            let mut child = cmd.spawn().context("failed to run `git cat-file`")?;
            let stdin = child.stdin.take().unwrap();
            let stdout = BufReader::new(child.stdout.take().unwrap());
            *guard = Some(CatFile {
                child,
                stdin,
                stdout,
            });
        }
        f(guard.as_mut().unwrap())
    }

    /// Read a raw object: returns (type, data).
    pub fn read_object(&self, spec: &str) -> Result<Option<(String, Oid, Vec<u8>)>> {
        self.with_catfile(|cf| {
            cf.stdin.write_all(spec.as_bytes())?;
            cf.stdin.write_all(b"\n")?;
            cf.stdin.flush()?;
            let mut header = String::new();
            cf.stdout.read_line(&mut header)?;
            let header = header.trim_end();
            if header.ends_with(" missing") || header.ends_with(" ambiguous") {
                return Ok(None);
            }
            let parts: Vec<&str> = header.split(' ').collect();
            if parts.len() != 3 {
                return Err(anyhow!("unexpected cat-file output: `{header}`"));
            }
            let oid = Oid::from_hex(parts[0]).ok_or_else(|| anyhow!("bad oid from cat-file"))?;
            let kind = parts[1].to_string();
            let size: usize = parts[2].parse()?;
            let mut data = vec![0u8; size];
            cf.stdout.read_exact(&mut data)?;
            let mut nl = [0u8; 1];
            cf.stdout.read_exact(&mut nl)?;
            Ok(Some((kind, oid, data)))
        })
    }

    pub fn find_commit(&self, oid: Oid) -> Result<Rc<Commit>> {
        if let Some(c) = self.commit_cache.borrow().get(&oid) {
            return Ok(c.clone());
        }
        let (kind, _, data) = self
            .read_object(&oid.to_hex())?
            .ok_or_else(|| anyhow!("object `{oid}` not found"))?;
        if kind != "commit" {
            return Err(anyhow!("object `{oid}` is not a commit"));
        }
        let commit = Rc::new(Commit::parse(oid, &data)?);
        self.commit_cache.borrow_mut().insert(oid, commit.clone());
        Ok(commit)
    }

    pub fn find_tree(&self, oid: Oid) -> Result<Rc<Tree>> {
        if let Some(t) = self.tree_cache.borrow().get(&oid) {
            return Ok(t.clone());
        }
        let (kind, _, data) = self
            .read_object(&oid.to_hex())?
            .ok_or_else(|| anyhow!("object `{oid}` not found"))?;
        if kind != "tree" {
            return Err(anyhow!("object `{oid}` is not a tree"));
        }
        let tree = Rc::new(Tree::parse(&data)?);
        self.tree_cache.borrow_mut().insert(oid, tree.clone());
        Ok(tree)
    }

    pub fn read_blob(&self, oid: Oid) -> Result<Vec<u8>> {
        let (kind, _, data) = self
            .read_object(&oid.to_hex())?
            .ok_or_else(|| anyhow!("object `{oid}` not found"))?;
        if kind != "blob" {
            return Err(anyhow!("object `{oid}` is not a blob"));
        }
        Ok(data)
    }

    /// Read a blob by "<tree-ish>:<path>" spec.
    pub fn read_blob_at(&self, tree: Oid, path: &str) -> Result<Option<Vec<u8>>> {
        match self.read_object(&format!("{tree}:{path}"))? {
            Some((kind, _, data)) if kind == "blob" => Ok(Some(data)),
            _ => Ok(None),
        }
    }

    pub fn object_kind(&self, oid: Oid) -> Result<Option<String>> {
        Ok(self.read_object(&oid.to_hex())?.map(|(k, _, _)| k))
    }

    pub fn write_blob(&self, data: &[u8]) -> Result<Oid> {
        let out = self.git_output_with_input(["hash-object", "-w", "--stdin"], data)?;
