    pub fn write_commit(
        &self,
        tree_id: Oid,
        parent_ids: &[Oid],
        author: &Signature,
        committer: &Signature,
        message: &BStr,
    ) -> Result<Oid> {
        self.write_commit_full(tree_id, parent_ids, author, committer, None, &[], message)
    }

