    pub fn write_commit_full(
        &self,
        tree_id: Oid,
        parent_ids: &[Oid],
        author: &Signature,
        committer: &Signature,
        encoding: Option<&str>,
        extra_headers: &[(String, BString)],
        message: &BStr,
    ) -> Result<Oid> {
