    pub fn update_refs(&self, updates: &[RefUpdate]) -> Result<()> {
        if updates.is_empty() {
            return Ok(());
        }
        let mut input = Vec::new();
        for u in updates {
            match u {
                RefUpdate::Update { refname, oid, msg: _ } => {
                    input.extend_from_slice(format!("update {refname}\0{oid}\0\0").as_bytes());
                }
                RefUpdate::Delete { refname } => {
                    input.extend_from_slice(format!("delete {refname}\0\0").as_bytes());
                }
                RefUpdate::Create { refname, oid } => {
                    input.extend_from_slice(format!("create {refname}\0{oid}\0").as_bytes());
                }
            }
        }
        let msg = updates
            .iter()
            .find_map(|u| match u {
                RefUpdate::Update { msg, .. } => Some(msg.as_str()),
                _ => None,
            })
            .unwrap_or("stg");
        let out = self.git_output_with_input(
            ["update-ref", "-m", msg, "--stdin", "-z", "--no-deref"],
