            "--format=%(refname) %(objectname)",
            prefix,
        ])?;
        if !out.success() {
            return Err(git_error("git for-each-ref", &out));
        }
        let mut refs = Vec::new();
        for line in out.stdout_str().lines() {
            if let Some((name, oid)) = line.split_once(' ') {
                if let Some(oid) = Oid::from_hex(oid) {
                    refs.push((name.to_string(), oid));
