            .stderr(Stdio::piped())
            .stdout(Stdio::piped())
            .output()
            .context("failed to run `git`")?;
        if !output.status.success() {
            let stderr = String::from_utf8_lossy(&output.stderr);
            if stderr.contains("not a git repository") || stderr.is_empty() {
