                    input.extend_from_slice(format!("create {refname}\0{oid}\0").as_bytes());
                }
            }
        }
        let msg = updates
            .iter()
            .find_map(|u| match u {
                RefUpdate::Update { msg, .. } => Some(msg.as_str()),
                _ => None,
            })
            .unwrap_or("stg");
        let out = self.git_output_with_input(
            ["update-ref", "-m", msg, "--stdin", "-z", "--no-deref"],
            &input,
        )?;
        if !out.success() {
            return Err(git_error("git update-ref", &out));
        }
        Ok(())
    }

    /// List refs matching the given prefix(es): returns (refname, oid).
    pub fn list_refs(&self, prefix: &str) -> Result<Vec<(String, Oid)>> {
        let out = self.git_output([
            "for-each-ref",
            "--format=%(refname) %(objectname)",
            prefix,
        ])?;
        if !out.success() {
            return Err(git_error("git for-each-ref", &out));
        }
        let mut refs = Vec::new();
        for line in out.stdout_str().lines() {
            if let Some((name, oid)) = line.split_once(' ') {
                if let Some(oid) = Oid::from_hex(oid) {
                    refs.push((name.to_string(), oid));
                }
            }
        }
        Ok(refs)
    }

    /// Symbolic target of HEAD, e.g. "refs/heads/master". None if detached.
    pub fn head_symbolic(&self) -> Result<Option<String>> {
        let out = self.git_output(["symbolic-ref", "-q", "HEAD"])?;
        if out.success() {
            Ok(Some(out.stdout_str().trim().to_string()))
        } else {
            Ok(None)
        }
    }

    pub fn head_oid(&self) -> Result<Option<Oid>> {
        self.rev_parse("HEAD")
    }

    pub fn set_head_symbolic(&self, refname: &str) -> Result<()> {
        let out = self.git_output(["symbolic-ref", "HEAD", refname])?;
        if !out.success() {
            return Err(git_error("git symbolic-ref", &out));
        }
        Ok(())
    }

    /// Abbreviate an object id using git's rules (core.abbrev / uniqueness).
    pub fn abbrev(&self, oid: Oid, len: Option<usize>) -> Result<String> {
        let mut args = vec!["rev-parse".to_string()];
        match len {
            Some(n) => args.push(format!("--short={n}")),
            None => args.push("--short".to_string()),
        }
        args.push(oid.to_hex());
        let out = self.git_output(&args)?;
        if out.success() {
            Ok(out.stdout_str().trim().to_string())
        } else {
            Ok(oid.to_hex())
        }
    }

    /// Check whether `ancestor` is an ancestor of `descendant`.
    pub fn is_ancestor(&self, ancestor: Oid, descendant: Oid) -> Result<bool> {
        let out = self.git_output([
            "merge-base",
            "--is-ancestor",
            &ancestor.to_hex(),
            &descendant.to_hex(),
        ])?;
        Ok(out.success())
    }

    pub fn merge_base(&self, a: Oid, b: Oid) -> Result<Option<Oid>> {
        let out = self.git_output(["merge-base", &a.to_hex(), &b.to_hex()])?;
        if out.success() {
            Ok(Oid::from_hex(out.stdout_str().trim()))
        } else {
            Ok(None)
        }
    }

    pub fn commit_message_from_rev(&self, oid: Oid) -> Result<BString> {
        Ok(self.find_commit(oid)?.message.clone())
    }
}

pub enum RefUpdate {
    Update { refname: String, oid: Oid, msg: String },
    Delete { refname: String },
    Create { refname: String, oid: Oid },
}

pub fn git_error(name: &str, out: &CommandOutput) -> anyhow::Error {
    let stderr = out.stderr_str();
    let stderr = stderr.trim_end();
    let msg = stderr
        .lines()
        .map(|l| {
            l.strip_prefix("fatal: ")
                .or_else(|| l.strip_prefix("error: "))
                .unwrap_or(l)
        })
        .collect::<Vec<_>>()
        .join("\n");
    anyhow!("`{name}`: {msg}")
}

fn pathdiff(target: &Path, base: &Path) -> String {
    match target.strip_prefix(base) {
        Ok(rel) => format!("./{}", rel.display()),
        Err(_) => target.display().to_string(),
    }
}
