//! Patch name validation and generation.

use std::fmt;
use std::str::FromStr;

use anyhow::{anyhow, Result};

#[derive(Debug, Clone, PartialEq, Eq, Hash, PartialOrd, Ord)]
pub struct PatchName(String);

impl PatchName {
    pub fn as_str(&self) -> &str {
        &self.0
    }

    pub fn len(&self) -> usize {
        self.0.len()
    }

    pub fn is_empty(&self) -> bool {
        self.0.is_empty()
    }

    pub fn into_string(self) -> String {
        self.0
    }

    /// Case-insensitive collision check.
    pub fn collides(&self, other: &PatchName) -> bool {
        self.0.eq_ignore_ascii_case(&other.0) || self.0.to_lowercase() == other.0.to_lowercase()
    }

    /// Create a patch name from an arbitrary string, making it valid.
    pub fn make(raw: &str, lower: bool, len_limit: Option<usize>) -> PatchName {
        let mut name = String::new();
        let mut prev_dash = true;
        for c in raw.chars() {
            if c.is_alphanumeric() {
                if lower {
                    name.extend(c.to_lowercase());
                } else {
                    name.push(c);
                }
                prev_dash = false;
            } else if !prev_dash {
                name.push('-');
                prev_dash = true;
            }
        }
        while name.ends_with('-') {
            name.pop();
        }
        let mut name = name;
        if let Some(limit) = len_limit {
            if limit > 0 && name.len() > limit {
                // Cut at a word boundary if possible.
                let mut candidate: Option<usize> = None;
                for (i, c) in name.char_indices() {
                    if i > limit {
                        break;
                    }
                    if c == '-' {
                        candidate = Some(i);
                    }
                }
                match candidate {
                    Some(i) if i > 0 => name.truncate(i),
                    _ => {
                        // Truncate on a char boundary.
                        let mut end = limit;
                        while !name.is_char_boundary(end) {
                            end -= 1;
                        }
                        name.truncate(end);
                    }
                }
                while name.ends_with('-') {
                    name.pop();
                }
            }
        }
        if name.is_empty() {
            name = "patch".to_string();
        }
        // ensure still valid
        match PatchName::from_str(&name) {
            Ok(pn) => pn,
            Err(_) => {
                let mut fixed = name;
                while fixed.starts_with('.') {
                    fixed.remove(0);
                }
                while fixed.ends_with('.') || fixed.ends_with('-') {
                    fixed.pop();
                }
                if fixed.ends_with(".lock") {
                    fixed.truncate(fixed.len() - 5);
                }
                if fixed.is_empty() {
                    fixed = "patch".to_string();
                }
                PatchName::from_str(&fixed).unwrap_or_else(|_| PatchName("patch".to_string()))
            }
        }
    }

    /// Make this name unique relative to the given set of existing names,
    /// appending "-N" suffixes as needed.
    pub fn uniquify<'a>(self, existing: impl Fn(&PatchName) -> bool) -> PatchName {
        if !existing(&self) {
            return self;
        }
        let base = self.0;
        // If the name already ends with -N, strip it.
        let (stem, start) = match base.rsplit_once('-') {
            Some((stem, num)) if !stem.is_empty() && num.chars().all(|c| c.is_ascii_digit()) && !num.is_empty() => {
                (stem.to_string(), num.parse::<usize>().unwrap_or(0) + 1)
            }
            _ => (base.clone(), 1),
        };
        let mut n = start;
        loop {
            let candidate = PatchName(format!("{stem}-{n}"));
            if !existing(&candidate) {
                return candidate;
            }
            n += 1;
        }
    }
}

impl fmt::Display for PatchName {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(&self.0)
    }
}

impl AsRef<str> for PatchName {
    fn as_ref(&self) -> &str {
        &self.0
    }
}

impl FromStr for PatchName {
    type Err = anyhow::Error;

    fn from_str(name: &str) -> Result<PatchName> {
        let err = |what: &str| anyhow!("invalid patch name `{name}`: patch name may not {what}");
        if name.is_empty() {
            return Err(err("be empty"));
        }
        if name == "@" {
            return Err(err("be '@'"));
        }
        if name == "{base}" {
            return Err(err("be '{base}'"));
        }
        if name.starts_with('.') {
            return Err(err("start with '.'"));
        }
        if name.ends_with('.') {
            return Err(err("end with '.'"));
        }
        if name.ends_with(".lock") {
            return Err(err("end with '.lock'"));
        }
        if name.contains("..") {
            return Err(err("contain '..'"));
        }
        if name.contains("@{") {
            return Err(err("contain '@{'"));
        }
        if name.chars().any(|c| c.is_whitespace()) {
            return Err(err("contain whitespace"));
        }
        for c in name.chars() {
            match c {
                '/' => return Err(err("contain '/'")),
                '~' => return Err(err("contain '~'")),
                '^' => return Err(err("contain '^'")),
                ':' => return Err(err("contain ':'")),
                '?' => return Err(err("contain '?'")),
                '*' => return Err(err("contain '*'")),
                '[' => return Err(err("contain '['")),
                '\\' => return Err(err("contain '\\'")),
                c if (c as u32) < 0x20 || c == '\x7f' => {
                    return Err(err("contain control characters"))
                }
                _ => {}
            }
        }
        Ok(PatchName(name.to_string()))
    }
}

/// Parse a patch name from the command line, allowing a leading backslash
/// to escape a leading dash.
pub fn parse_patchname_arg(s: &str) -> Result<PatchName> {
    let s = s.strip_prefix('\\').filter(|_| s.starts_with("\\-")).unwrap_or(s);
    PatchName::from_str(s)
}
