//! Stack state serialization (version 5 format).

use std::collections::BTreeMap;
use std::rc::Rc;

use anyhow::{anyhow, Context, Result};
use bstr::ByteSlice;
use serde::{Deserialize, Serialize};

use crate::git::{Commit, Oid, Repository, Tree, TreeEntry};
use crate::patch::PatchName;
use crate::signature::Signature;

#[derive(Debug, Clone)]
pub struct StackState {
    pub prev: Option<Oid>,
    pub head: Rc<Commit>,
    pub applied: Vec<PatchName>,
    pub unapplied: Vec<PatchName>,
    pub hidden: Vec<PatchName>,
    pub patches: BTreeMap<PatchName, Rc<Commit>>,
}

#[derive(Serialize, Deserialize)]
struct RawPatchState {
    oid: String,
}

#[derive(Serialize, Deserialize)]
struct RawStackState {
    version: i64,
    prev: Option<String>,
    head: String,
    applied: Vec<String>,
    unapplied: Vec<String>,
    hidden: Vec<String>,
    patches: BTreeMap<String, RawPatchState>,
}

impl StackState {
    pub fn new(head: Rc<Commit>) -> StackState {
        StackState {
            prev: None,
            head,
            applied: Vec::new(),
            unapplied: Vec::new(),
            hidden: Vec::new(),
            patches: BTreeMap::new(),
        }
    }

    pub fn from_commit(repo: &Repository, commit_id: Oid) -> Result<StackState> {
        let commit = repo.find_commit(commit_id)?;
        let tree = repo.find_tree(commit.tree_id)?;
        let entry = tree
            .get(b"stack.json")
            .ok_or_else(|| anyhow!("stack metadata `stack.json` not found in `{commit_id}`"))?;
        let data = repo.read_blob(entry.id)?;
        let raw: RawStackState =
            serde_json::from_slice(&data).context("parsing stack.json")?;
        if raw.version != 5 {
            return Err(anyhow!(
                "unsupported StGit stack metadata version {}; expected version 5",
                raw.version
            ));
        }
        let head_id = Oid::from_hex(&raw.head).ok_or_else(|| anyhow!("invalid head oid"))?;
        let head = repo.find_commit(head_id)?;
        let prev = match raw.prev {
            Some(p) => Some(Oid::from_hex(&p).ok_or_else(|| anyhow!("invalid prev oid"))?),
            None => None,
        };
        let mut patches = BTreeMap::new();
        for (name, raw_patch) in raw.patches {
            let pn: PatchName = PatchName::from_str_lenient(&name);
            let oid = Oid::from_hex(&raw_patch.oid).ok_or_else(|| anyhow!("invalid patch oid"))?;
            let commit = repo.find_commit(oid)?;
            patches.insert(pn, commit);
        }
        let to_names = |v: Vec<String>| -> Vec<PatchName> {
            v.iter().map(|s| PatchName::from_str_lenient(s)).collect()
        };
        Ok(StackState {
            prev,
            head,
            applied: to_names(raw.applied),
            unapplied: to_names(raw.unapplied),
            hidden: to_names(raw.hidden),
            patches,
        })
    }

    pub fn all_patches(&self) -> impl Iterator<Item = &PatchName> {
        self.applied
            .iter()
            .chain(self.unapplied.iter())
            .chain(self.hidden.iter())
    }

    pub fn top(&self) -> Option<&PatchName> {
        self.applied.last()
    }

    pub fn top_commit(&self) -> &Rc<Commit> {
        match self.applied.last() {
            Some(pn) => &self.patches[pn],
            None => &self.head,
        }
    }

    /// The commit upon which the stack is based.
    pub fn base(&self, repo: &Repository) -> Result<Rc<Commit>> {
        match self.applied.first() {
            Some(pn) => {
                let c = &self.patches[pn];
                let parent = c
                    .parent_ids
                    .first()
                    .ok_or_else(|| anyhow!("patch `{pn}` has no parent"))?;
                repo.find_commit(*parent)
            }
            None => Ok(self.head.clone()),
        }
    }

    fn patch_meta_blob(repo: &Repository, commit: &Commit) -> Result<Vec<u8>> {
        let parent_tree = match commit.parent_ids.first() {
            Some(p) => repo.find_commit(*p)?.tree_id,
            None => commit.tree_id,
        };
        let mut out = Vec::new();
        out.extend_from_slice(format!("Bottom: {}\n", parent_tree).as_bytes());
        out.extend_from_slice(format!("Top:    {}\n", commit.tree_id).as_bytes());
        out.extend_from_slice(b"Author: ");
        out.extend_from_slice(commit.author.name_email().as_bytes());
        out.push(b'\n');
        out.extend_from_slice(format!("Date:   {}\n", commit.committer.time.to_iso()).as_bytes());
        out.push(b'\n');
        out.extend_from_slice(&commit.message);
        Ok(out)
    }

    /// Write the state tree. Returns the tree oid.
    pub fn write_tree(&self, repo: &Repository) -> Result<Oid> {
        let raw = RawStackState {
            version: 5,
            prev: self.prev.map(|o| o.to_hex()),
            head: self.head.id.to_hex(),
            applied: self.applied.iter().map(|p| p.to_string()).collect(),
            unapplied: self.unapplied.iter().map(|p| p.to_string()).collect(),
            hidden: self.hidden.iter().map(|p| p.to_string()).collect(),
            patches: self
                .patches
                .iter()
                .map(|(k, v)| {
                    (
                        k.to_string(),
                        RawPatchState {
                            oid: v.id.to_hex(),
                        },
                    )
                })
                .collect(),
        };
        let json = serde_json::to_vec_pretty(&raw)?;
        let json_id = repo.write_blob(&json)?;

        let mut patch_entries = Vec::new();
        for (pn, commit) in &self.patches {
            let blob = Self::patch_meta_blob(repo, commit)?;
            let blob_id = repo.write_blob(&blob)?;
            patch_entries.push(TreeEntry {
                mode: 0o100644,
                name: pn.as_str().into(),
                id: blob_id,
            });
        }
        let patches_tree_id = repo.write_tree(&Tree {
            entries: patch_entries,
        })?;

        let tree = Tree {
            entries: vec![
                TreeEntry {
                    mode: 0o040000,
                    name: "patches".into(),
                    id: patches_tree_id,
                },
                TreeEntry {
                    mode: 0o100644,
                    name: "stack.json".into(),
                    id: json_id,
                },
            ],
        };
        repo.write_tree(&tree)
    }

    /// Commit this state. Writes the "simplified" commit (parent = previous
    /// simplified commit) and the full log commit. Returns the log commit id.
    pub fn commit(
        &self,
        repo: &Repository,
        prev_log_id: Option<Oid>,
        message: &str,
        author: &Signature,
        committer: &Signature,
    ) -> Result<Oid> {
        let tree_id = self.write_tree(repo)?;
        let simplified_parent = match prev_log_id {
            Some(prev) => {
                let prev_commit = repo.find_commit(prev)?;
                prev_commit.parent_ids.first().copied()
            }
            None => None,
        };
        let simplified_parents: Vec<Oid> = simplified_parent.into_iter().collect();
        let simplified_id = repo.write_commit(
            tree_id,
            &simplified_parents,
            author,
            committer,
            message.as_bytes().as_bstr(),
        )?;
        let mut parents = vec![simplified_id, self.head.id];
        if let Some(prev) = prev_log_id {
            parents.push(prev);
        }
        repo.write_commit(tree_id, &parents, author, committer, message.as_bytes().as_bstr())
    }
}
