//! Stack access: loading and initializing stacks for branches.

use std::rc::Rc;

use anyhow::{anyhow, Result};

use super::StackState;
use crate::git::{Commit, Oid, Repository};
use crate::patch::PatchName;
use crate::signature::Signature;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum InitializationPolicy {
    AllowUninitialized,
    RequireInitialized,
    AutoInitialize,
    MustNotBeInitialized,
}

pub struct Stack<'repo> {
    pub repo: &'repo Repository,
    pub branch_name: String,
    pub state: StackState,
    pub is_initialized: bool,
    /// The log commit that `refs/stacks/<branch>` points at (if any).
    pub log_id: Option<Oid>,
    /// Head commit of the branch (refs/heads/<branch>).
    pub branch_head: Rc<Commit>,
    pub base: Rc<Commit>,
}

impl<'repo> Stack<'repo> {
    pub fn stack_refname(branch: &str) -> String {
        format!("refs/stacks/{branch}")
    }

    pub fn patch_refname(branch: &str, patchname: &PatchName) -> String {
        format!("refs/patches/{branch}/{patchname}")
    }

    pub fn branch_refname(branch: &str) -> String {
        format!("refs/heads/{branch}")
    }

    pub fn get_patch_refname(&self, patchname: &PatchName) -> String {
        Self::patch_refname(&self.branch_name, patchname)
    }

    pub fn get_stack_refname(&self) -> String {
        Self::stack_refname(&self.branch_name)
    }

    pub fn get_branch_refname(&self) -> String {
        Self::branch_refname(&self.branch_name)
    }

    /// Determine the current branch name from HEAD.
    pub fn current_branch_name(repo: &Repository) -> Result<String> {
        match repo.head_symbolic()? {
            Some(refname) => {
                if let Some(name) = refname.strip_prefix("refs/heads/") {
                    Ok(name.to_string())
                } else {
                    Err(anyhow!("HEAD points to `{refname}` which is not a branch"))
                }
            }
            None => Err(anyhow!("not on branch, HEAD is detached")),
        }
    }

    /// Resolve the branch name, checking that the branch exists and has a commit.
    pub fn resolve_branch(repo: &Repository, branch: Option<&str>) -> Result<(String, Rc<Commit>)> {
        let branch_name = match branch {
            Some(b) => b.to_string(),
            None => Self::current_branch_name(repo)?,
        };
        let refname = Self::branch_refname(&branch_name);
        match repo.get_ref(&refname)? {
            Some(oid) => Ok((branch_name, repo.find_commit(oid)?)),
            None => {
                if branch.is_none() {
                    Err(anyhow!("branch `{refname}` is unborn"))
                } else {
                    Err(anyhow!("branch `{branch_name}` not found"))
                }
            }
        }
    }

    pub fn from_branch(
        repo: &'repo Repository,
        branch: Option<&str>,
        policy: InitializationPolicy,
    ) -> Result<Stack<'repo>> {
        let (branch_name, branch_head) = Self::resolve_branch(repo, branch)?;
        let stack_refname = Self::stack_refname(&branch_name);
        match repo.get_ref(&stack_refname)? {
            Some(log_id) => {
                if policy == InitializationPolicy::MustNotBeInitialized {
                    return Err(anyhow!(
                        "StGit stack already initialized for branch `{branch_name}`"
                    ));
                }
                let state = StackState::from_commit(repo, log_id)?;
                let base = state.base(repo)?;
                Ok(Stack {
                    repo,
                    branch_name,
                    state,
                    is_initialized: true,
                    log_id: Some(log_id),
                    branch_head,
                    base,
                })
            }
            None => {
                if policy == InitializationPolicy::RequireInitialized {
                    return Err(anyhow!(
                        "StGit stack not initialized for branch `{branch_name}`"
                    ));
                }
                let state = StackState::new(branch_head.clone());
                let mut stack = Stack {
                    repo,
                    branch_name,
                    base: branch_head.clone(),
                    state,
                    is_initialized: false,
                    log_id: None,
                    branch_head,
                };
                if policy == InitializationPolicy::AutoInitialize {
                    stack.initialize()?;
                }
                Ok(stack)
            }
        }
    }

    /// Write the initial stack state and the stack ref.
    pub fn initialize(&mut self) -> Result<()> {
        let log_id = self.write_initial_log()?;
        self.repo
            .update_ref(&self.get_stack_refname(), log_id, "initialize")?;
        self.log_id = Some(log_id);
        self.is_initialized = true;
        Ok(())
    }

    /// Write the "initialize" log commit (without updating the ref).
    pub fn write_initial_log(&self) -> Result<Oid> {
        let committer = Signature::default_committer(&self.repo.config)?;
        let author = Signature::default_author(&self.repo.config)?;
        self.state
            .commit(self.repo, None, "initialize", &author, &committer)
    }

    /// Log commit id, creating an in-memory initial log if needed.
    pub fn ensure_log_id(&mut self) -> Result<Oid> {
        match self.log_id {
            Some(id) => Ok(id),
            None => {
                let id = self.write_initial_log()?;
                self.log_id = Some(id);
                Ok(id)
            }
        }
    }

    pub fn applied(&self) -> &[PatchName] {
        &self.state.applied
    }
    pub fn unapplied(&self) -> &[PatchName] {
        &self.state.unapplied
    }
    pub fn hidden(&self) -> &[PatchName] {
        &self.state.hidden
    }
    pub fn all_patches(&self) -> impl Iterator<Item = &PatchName> {
        self.state.all_patches()
    }
    pub fn applied_and_unapplied(&self) -> impl Iterator<Item = &PatchName> {
        self.state.applied.iter().chain(self.state.unapplied.iter())
    }
    pub fn has_patch(&self, pn: &PatchName) -> bool {
        self.state.patches.contains_key(pn)
    }
    pub fn get_patch_commit(&self, pn: &PatchName) -> &Rc<Commit> {
        &self.state.patches[pn]
    }
    pub fn get_patch_commit_opt(&self, pn: &PatchName) -> Option<&Rc<Commit>> {
        self.state.patches.get(pn)
    }
    pub fn top(&self) -> &Rc<Commit> {
        self.state.top_commit()
    }
    pub fn head(&self) -> &Rc<Commit> {
        &self.state.head
    }
    pub fn is_applied(&self, pn: &PatchName) -> bool {
        self.state.applied.contains(pn)
    }
    pub fn is_unapplied(&self, pn: &PatchName) -> bool {
        self.state.unapplied.contains(pn)
    }
    pub fn is_hidden(&self, pn: &PatchName) -> bool {
        self.state.hidden.contains(pn)
    }

    /// Find a patch name whose spelling collides (case-insensitively) with the given name.
    pub fn collides(&self, pn: &PatchName) -> Option<&PatchName> {
        self.state.patches.keys().find(|k| k.collides(pn))
    }

    /// Check that the branch head matches the recorded stack head.
    pub fn check_head_top_mismatch(&self) -> Result<()> {
        if self.branch_head.id != self.state.head.id {
            Err(anyhow!(
                "HEAD and stack top are not the same. \
                 This can happen if you modify the branch with git. \
                 See `stg repair --help` for next steps to take."
            ))
        } else {
            Ok(())
        }
    }

    /// Check that the stack is initialized.
    pub fn check_initialized(&self) -> Result<()> {
        if !self.is_initialized {
            Err(anyhow!(
                "StGit stack not initialized for branch `{}`",
                self.branch_name
            ))
        } else {
            Ok(())
        }
    }

    pub fn is_protected(&self) -> bool {
        self.repo
            .config
            .get_bool(&format!("branch.{}.stgit.protect", self.branch_name))
            .unwrap_or(false)
    }

    pub fn check_protected(&self) -> Result<()> {
        if self.is_protected() {
            Err(anyhow!(
                "this branch is protected; modification is not permitted"
            ))
        } else {
            Ok(())
        }
    }

    /// Get all the patch refs from the repo for this branch.
    pub fn patch_refs(&self) -> Result<Vec<(String, Oid)>> {
        self.repo
            .list_refs(&format!("refs/patches/{}/", self.branch_name))
    }

    /// Update the branch head ref and state head.
    pub fn update_head(&mut self, commit: Rc<Commit>, msg: &str) -> Result<()> {
        self.repo
            .update_ref(&self.get_branch_refname(), commit.id, msg)?;
        self.branch_head = commit.clone();
        self.state.head = commit;
        Ok(())
    }

    /// Find a patch by commit id.
    pub fn patch_for_commit(&self, oid: Oid) -> Option<&PatchName> {
        self.all_patches()
            .find(|pn| self.state.patches[*pn].id == oid)
    }

    /// Find a patch name similar to the given one.
    pub fn similar_patch_name(&self, name: &str) -> Option<&PatchName> {
        let mut best: Option<(&PatchName, f64)> = None;
        for pn in self.all_patches() {
            let conf = strsim::jaro_winkler(name, pn.as_str());
            if conf > 0.7 && best.map(|(_, c)| conf > c).unwrap_or(true) {
                best = Some((pn, conf));
            }
        }
        best.map(|(pn, _)| pn)
    }

    /// Error for a non-existent patch, with a suggestion if available.
    pub fn patch_not_found_error(&self, name: &str) -> anyhow::Error {
        match self.similar_patch_name(name) {
            Some(similar) => {
                anyhow!("patch `{name}` does not exist, but is similar to `{similar}`")
            }
            None => anyhow!("patch `{name}` does not exist"),
        }
    }
}
