            status: output.status,
            stdout: output.stdout,
            stderr: output.stderr,
        })
    }

    fn ok(&self, name: &str, out: CommandOutput) -> Result<Vec<u8>> {
        if out.success() {
            Ok(out.stdout)
        } else {
