    pub fn apply_treediff_to_index(&self, tree1: Oid, tree2: Oid, want_3way: bool) -> Result<bool> {
        let diff = self.diff_tree_patch(tree1, tree2, None::<Vec<&str>>, true, &[])?;
        if diff.is_empty() {
            return Ok(true);
        }
        let mut args = vec!["apply", "--cached"];
        if want_3way {
            args.push("--3way");
