    /// Apply a diff to the index.
    pub fn apply_to_index(&self, diff: &[u8]) -> Result<bool> {
        if diff.is_empty() {
            return Ok(true);
        }
        let out = self.run_with_input(["apply", "--cached"], diff)?;
        Ok(out.success())
    }

    /// Apply a diff to the work tree (and index with --index).
    pub fn apply_to_worktree_and_index(
        &self,
        diff: &[u8],
        reject: bool,
        strip: Option<usize>,
        context: Option<usize>,
        directory: Option<&str>,
    ) -> Result<()> {
        let mut args: Vec<String> = vec!["apply".into(), "--index".into()];
        if reject {
            args.push("--reject".into());
        }
        if let Some(n) = strip {
            args.push(format!("-p{n}"));
        }
        if let Some(n) = context {
            args.push(format!("-C{n}"));
        }
        if let Some(d) = directory {
            args.push(format!("--directory={d}"));
        }
        let out = self.run_with_input(&args, diff)?;
        if out.success() {
            Ok(())
        } else {
            Err(anyhow!(
                "`git apply`: {}",
                clean_git_stderr(&out.stderr_str())
            ))
        }
    }

    /// Three-way merge in the work tree. Returns Ok(true) if clean, Ok(false) if conflicts.
    pub fn merge_recursive(&self, base: Oid, ours: Oid, theirs: Oid) -> Result<bool> {
        let mut cmd = self.command();
        cmd.args(["merge-recursive", &base.to_hex(), "--", &ours.to_hex(), &theirs.to_hex()]);
        cmd.env(format!("GITHEAD_{}", ours.to_hex()), "current");
        cmd.env(format!("GITHEAD_{}", theirs.to_hex()), "patched");
        cmd.stdout(Stdio::piped()).stderr(Stdio::piped());
        let output = cmd.output()?;
        match output.status.code() {
            Some(0) => Ok(true),
            Some(1) => Ok(false),
            _ => Err(anyhow!(
                "`git merge-recursive`: {}",
                clean_git_stderr(&String::from_utf8_lossy(&output.stderr))
            )),
        }
    }

    /// `git status --porcelain=v1 -z`
    pub fn statuses(&self, untracked: bool) -> Result<Vec<StatusEntry>> {
        let mut args = vec!["status", "--porcelain=v1", "-z"];
        if untracked {
            args.push("--untracked-files=normal");
        } else {
            args.push("--untracked-files=no");
        }
        let out = self.run(args)?;
        let stdout = self.ok("git status", out)?;
        let mut entries = Vec::new();
        let mut fields = stdout.split(|b| *b == 0).peekable();
        while let Some(field) = fields.next() {
            if field.len() < 4 {
                continue;
            }
            let xy = [field[0], field[1]];
            let path = BString::from(&field[3..]);
            let orig_path = if xy[0] == b'R' || xy[0] == b'C' {
                fields.next().map(BString::from)
            } else {
                None
            };
            entries.push(StatusEntry { xy, path, orig_path });
        }
        Ok(entries)
    }

    /// Paths with conflicts (unmerged entries), from `git ls-files --unmerged`.
    pub fn conflict_paths(&self) -> Result<Vec<BString>> {
        let out = self.run(["ls-files", "--unmerged", "-z"])?;
        let stdout = self.ok("git ls-files", out)?;
        let mut paths: Vec<BString> = Vec::new();
        for field in stdout.split(|b| *b == 0) {
            if field.is_empty() {
                continue;
            }
            if let Some(pos) = field.find_byte(b'\t') {
                let path = BString::from(&field[pos + 1..]);
                if !paths.contains(&path) {
                    paths.push(path);
                }
            }
        }
        Ok(paths)
    }

    /// Does the index differ from the given tree?
    pub fn index_differs_from_tree(&self, tree_id: Oid) -> Result<bool> {
        let out = self.run(["diff-index", "--quiet", "--cached", &tree_id.to_hex()])?;
        match out.status.code() {
            Some(0) => Ok(false),
            Some(1) => Ok(true),
            _ => Err(crate::git::repo_git_error("git diff-index", &out)),
        }
    }

    /// Does the work tree differ from the index?
    pub fn worktree_differs_from_index(&self) -> Result<bool> {
        self.update_index_refresh()?;
        let out = self.run(["diff-files", "--quiet"])?;
        match out.status.code() {
            Some(0) => Ok(false),
            Some(1) => Ok(true),
            _ => Err(crate::git::repo_git_error("git diff-files", &out)),
        }
    }

    /// Names of files changed between two trees.
    pub fn diff_tree_files(&self, tree1: Oid, tree2: Oid) -> Result<Vec<BString>> {
        let out = self.run([
            "diff-tree",
            "-r",
            "--name-only",
            "-z",
            &tree1.to_hex(),
            &tree2.to_hex(),
        ])?;
        let stdout = self.ok("git diff-tree", out)?;
        Ok(stdout
            .split(|b| *b == 0)
            .filter(|f| !f.is_empty())
            .map(BString::from)
            .collect())
    }

    /// Update the index from the work tree for the given paths (or all tracked).
    pub fn update_index_from_worktree(&self, pathspecs: &[String], all: bool) -> Result<()> {
        let mut cmd = self.command();
        cmd.args(["add", "--"]);
        if all || pathspecs.is_empty() {
            cmd.arg(".");
        } else {
            cmd.args(pathspecs);
        }
        let _ = cmd;
        // Use update-index for tracked files only.
        let mut cmd = self.command();
        cmd.args(["update-index", "-q", "--refresh"]);
        let _ = cmd.stdout(Stdio::null()).stderr(Stdio::null()).status();
        let mut args: Vec<String> = vec!["add".into(), "-u".into(), "--".into()];
        if all || pathspecs.is_empty() {
            args.push(".".into());
        } else {
            args.extend(pathspecs.iter().cloned());
        }
        let out = self.run(&args)?;
        self.ok("git add", out).map(|_| ())
    }

    pub fn run_git_passthrough<I, S>(&self, args: I) -> Result<std::process::ExitStatus>
    where
        I: IntoIterator<Item = S>,
        S: AsRef<OsStr>,
    {
        let mut cmd = self.command();
        cmd.args(args);
        cmd.stdin(Stdio::inherit())
            .stdout(Stdio::inherit())
            .stderr(Stdio::inherit());
        Ok(cmd.status()?)
    }

    pub fn git_command(&self) -> Command {
        self.command()
    }
}

pub fn clean_git_stderr(stderr: &str) -> String {
    stderr
        .trim_end()
        .lines()
        .map(|l| {
            l.strip_prefix("fatal: ")
                .or_else(|| l.strip_prefix("error: "))
                .unwrap_or(l)
        })
        .collect::<Vec<_>>()
        .join("\n")
}
