pub struct TransactionBuilder<'repo> {
    stack: Stack<'repo>,
    color_choice: ColorChoice,
    use_index_and_worktree: bool,
    conflict_mode: ConflictMode,
    discard_changes: bool,
    allow_bad_head: bool,
