        } = self;

        if !allow_bad_head {
            stack.check_head_top_mismatch()?;
        }

        let current_tree_id = stack.branch_head.tree_id;
        let applied = stack.state.applied.clone();
        let unapplied = stack.state.unapplied.clone();
        let hidden = stack.state.hidden.clone();
        let output = crate::color::stdout(color_choice);

        let mut trans = StackTransaction {
            stack,
            output,
            use_index_and_worktree,
            conflict_mode,
            discard_changes,
            committer_date_is_author_date,
            allow_push_conflicts,
            set_head,
            applied,
            unapplied,
            hidden,
            updated_patches: BTreeMap::new(),
            updated_head: None,
            updated_base: None,
            current_tree_id,
            initial_tree_id: current_tree_id,
            printed_top: false,
            conflicts: Vec::new(),
            error: None,
            halted: false,
            reflog_msg: None,
            conflict_mode_checked: false,
        };

        trans.check_conflict_mode()?;

        let result = f(&mut trans);
        match result {
            Ok(()) => {}
            Err(e) => {
                if trans.halted {
                    trans.error = Some(e);
                } else {
                    trans.rollback()?;
                    return Err(e);
                }
            }
        }
        trans.commit_transaction()
    }
