//! Stack transactions: atomic modifications of the stack state.

use std::collections::BTreeMap;
use std::io::Write;
use std::rc::Rc;

use anyhow::{anyhow, Result};
use bstr::{BString, ByteSlice};

use super::{Stack, StackState};
use crate::color::{Color, ColorChoice, ColorSpec, StdoutColor};
use crate::error::Error;
use crate::git::{Commit, Oid, RefUpdate};
use crate::patch::PatchName;
use crate::signature::Signature;
use crate::stupid::Stupid;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ConflictMode {
    Disallow,
    Allow,
    AllowIfSameTop,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum PushStatus {
    New,
    AlreadyMerged,
    Conflict,
    Empty,
    Modified,
    Unmodified,
}

pub struct TransactionBuilder<'repo> {
    stack: Stack<'repo>,
    color_choice: ColorChoice,
    use_index_and_worktree: bool,
    conflict_mode: ConflictMode,
    discard_changes: bool,
    allow_bad_head: bool,
    committer_date_is_author_date: bool,
    allow_push_conflicts: bool,
    set_head: bool,
}

impl<'repo> TransactionBuilder<'repo> {
    pub fn new(stack: Stack<'repo>, color_choice: ColorChoice) -> Self {
        TransactionBuilder {
            stack,
            color_choice,
            use_index_and_worktree: false,
            conflict_mode: ConflictMode::Disallow,
            discard_changes: false,
            allow_bad_head: false,
            committer_date_is_author_date: false,
            allow_push_conflicts: true,
            set_head: true,
        }
    }

    pub fn use_index_and_worktree(mut self, yes: bool) -> Self {
        self.use_index_and_worktree = yes;
        self
    }
    pub fn allow_conflicts(mut self, yes: bool) -> Self {
        self.conflict_mode = if yes {
            ConflictMode::Allow
        } else {
            ConflictMode::Disallow
        };
        self
    }
    pub fn allow_conflicts_if_same_top(mut self, yes: bool) -> Self {
        if yes {
            self.conflict_mode = ConflictMode::AllowIfSameTop;
        }
        self
    }
    pub fn discard_changes(mut self, yes: bool) -> Self {
        self.discard_changes = yes;
        self
    }
    pub fn allow_bad_head(mut self, yes: bool) -> Self {
        self.allow_bad_head = yes;
        self
    }
    pub fn committer_date_is_author_date(mut self, yes: bool) -> Self {
        self.committer_date_is_author_date = yes;
        self
    }
    pub fn allow_push_conflicts(mut self, yes: bool) -> Self {
        self.allow_push_conflicts = yes;
        self
    }
    pub fn set_head(mut self, yes: bool) -> Self {
        self.set_head = yes;
        self
    }

    /// Perform the transaction operations and then commit the result.
    pub fn transact<F>(self, f: F) -> Result<Stack<'repo>>
    where
        F: FnOnce(&mut StackTransaction<'repo>) -> Result<()>,
    {
        let TransactionBuilder {
            stack,
            color_choice,
            use_index_and_worktree,
            conflict_mode,
            discard_changes,
            allow_bad_head,
            committer_date_is_author_date,
            allow_push_conflicts,
            set_head,
        } = self;

        if !allow_bad_head {
            stack.check_head_top_mismatch()?;
        }

        let current_tree_id = stack.branch_head.tree_id;
        let applied = stack.state.applied.clone();
        let unapplied = stack.state.unapplied.clone();
        let hidden = stack.state.hidden.clone();
        let output = crate::color::stdout(color_choice);

        let mut trans = StackTransaction {
            stack,
            output,
            use_index_and_worktree,
            conflict_mode,
            discard_changes,
            committer_date_is_author_date,
            allow_push_conflicts,
            set_head,
            applied,
            unapplied,
            hidden,
            updated_patches: BTreeMap::new(),
            updated_head: None,
            updated_base: None,
            current_tree_id,
            initial_tree_id: current_tree_id,
            printed_top: false,
            conflicts: Vec::new(),
            error: None,
            halted: false,
            reflog_msg: None,
            conflict_mode_checked: false,
        };

        trans.check_conflict_mode()?;

        let result = f(&mut trans);
        match result {
            Ok(()) => {}
            Err(e) => {
                if trans.halted {
                    trans.error = Some(e);
                } else {
                    trans.rollback()?;
                    return Err(e);
                }
            }
        }
        trans.commit_transaction()
    }
}

pub struct StackTransaction<'repo> {
    stack: Stack<'repo>,
    output: StdoutColor,
    use_index_and_worktree: bool,
    conflict_mode: ConflictMode,
    discard_changes: bool,
    committer_date_is_author_date: bool,
    allow_push_conflicts: bool,
    set_head: bool,
    applied: Vec<PatchName>,
    unapplied: Vec<PatchName>,
    hidden: Vec<PatchName>,
    updated_patches: BTreeMap<PatchName, Option<Rc<Commit>>>,
    updated_head: Option<Rc<Commit>>,
    updated_base: Option<Rc<Commit>>,
    current_tree_id: Oid,
    initial_tree_id: Oid,
    printed_top: bool,
    conflicts: Vec<BString>,
    error: Option<anyhow::Error>,
    halted: bool,
    reflog_msg: Option<String>,
    conflict_mode_checked: bool,
}

impl<'repo> StackTransaction<'repo> {
    fn check_conflict_mode(&mut self) -> Result<()> {
        if self.conflict_mode_checked {
            return Ok(());
        }
        self.conflict_mode_checked = true;
        if self.use_index_and_worktree && !self.discard_changes {
            let stupid = self.stack.repo.stupid();
            let conflicts = stupid.conflict_paths()?;
            if !conflicts.is_empty() {
                match self.conflict_mode {
                    ConflictMode::Disallow => {
                        return Err(anyhow!("resolve outstanding conflicts first"));
                    }
                    ConflictMode::Allow => {}
                    ConflictMode::AllowIfSameTop => {}
                }
            }
        }
        Ok(())
    }

    pub fn stack(&self) -> &Stack<'repo> {
        &self.stack
    }

    pub fn repo(&self) -> &'repo crate::git::Repository {
        self.stack.repo
    }

    pub fn applied(&self) -> &[PatchName] {
        &self.applied
    }
    pub fn unapplied(&self) -> &[PatchName] {
        &self.unapplied
    }
    pub fn hidden(&self) -> &[PatchName] {
        &self.hidden
    }
    pub fn all_patches(&self) -> impl Iterator<Item = &PatchName> {
        self.applied
            .iter()
            .chain(self.unapplied.iter())
            .chain(self.hidden.iter())
    }
    pub fn is_applied(&self, pn: &PatchName) -> bool {
        self.applied.contains(pn)
    }
    pub fn is_unapplied(&self, pn: &PatchName) -> bool {
        self.unapplied.contains(pn)
    }
    pub fn is_hidden(&self, pn: &PatchName) -> bool {
        self.hidden.contains(pn)
    }
    pub fn has_patch(&self, pn: &PatchName) -> bool {
        self.all_patches().any(|p| p == pn)
    }

    pub fn top(&self) -> Rc<Commit> {
        match self.applied.last() {
            Some(pn) => self.get_patch_commit(pn),
            None => self.base(),
        }
    }

    pub fn base(&self) -> Rc<Commit> {
        match &self.updated_base {
            Some(c) => c.clone(),
            None => self.stack.base.clone(),
        }
    }

    pub fn head(&self) -> Rc<Commit> {
        match &self.updated_head {
            Some(c) => c.clone(),
            None => self.stack.branch_head.clone(),
        }
    }

    pub fn get_patch_commit(&self, pn: &PatchName) -> Rc<Commit> {
        match self.updated_patches.get(pn) {
            Some(Some(c)) => c.clone(),
            Some(None) => panic!("patch `{pn}` was deleted"),
            None => self.stack.get_patch_commit(pn).clone(),
        }
    }

    pub fn get_patch_commit_opt(&self, pn: &PatchName) -> Option<Rc<Commit>> {
        match self.updated_patches.get(pn) {
            Some(Some(c)) => Some(c.clone()),
            Some(None) => None,
            None => self.stack.get_patch_commit_opt(pn).cloned(),
        }
    }

    pub fn current_tree_id(&self) -> Oid {
        self.current_tree_id
    }

    pub fn committer_date_is_author_date(&self) -> bool {
        self.committer_date_is_author_date
    }

    /// Mark that the transaction should halt (commit what has been done so far)
    /// and return the given error.
    fn halt(&mut self, err: anyhow::Error) -> anyhow::Error {
        self.halted = true;
        err
    }

    pub fn conflicts(&self) -> &[BString] {
        &self.conflicts
    }

    // ---- committing ----

    fn make_committer(&self, author: &Signature) -> Result<Signature> {
        let committer = Signature::default_committer(&self.stack.repo.config)?;
        if self.committer_date_is_author_date {
            Ok(committer.with_time(author.time))
        } else {
            Ok(committer)
        }
    }

    /// Create a new commit for a patch using the given author and message.
    pub fn commit_patch(
        &self,
        author: &Signature,
        message: &[u8],
        tree_id: Oid,
        parent_ids: &[Oid],
    ) -> Result<Rc<Commit>> {
        let committer = self.make_committer(author)?;
        let repo = self.stack.repo;
        let oid = repo.write_commit(tree_id, parent_ids, author, &committer, message.as_bstr())?;
        repo.find_commit(oid)
    }

    // ---- UI ----

    fn write_status(&mut self, prefix: &str, pn: &PatchName, annotation: Option<&str>, kind: StatusKind) -> Result<()> {
        let (prefix_color, name_bold, name_dim) = match kind {
            StatusKind::Top => (Some(Color::Blue), true, false),
            StatusKind::Applied => (Some(Color::Green), false, false),
            StatusKind::Unapplied => (Some(Color::Magenta), false, true),
            StatusKind::Hidden => (Some(Color::Red), false, true),
            StatusKind::Deleted => (Some(Color::Yellow), false, false),
            StatusKind::Updated => (Some(Color::Cyan), false, false),
            StatusKind::Committed => (Some(Color::Green), false, false),
            StatusKind::RolledBack => (Some(Color::Red), false, false),
            StatusKind::Plain => (None, false, false),
        };
        let mut spec = ColorSpec::new();
        spec.set_fg(prefix_color);
        self.output.set_color(&spec)?;
        write!(self.output, "{prefix} ")?;
        self.output.reset()?;
        let mut spec = ColorSpec::new();
        spec.set_bold(name_bold).set_dimmed(name_dim);
        self.output.set_color(&spec)?;
        write!(self.output, "{pn}")?;
        self.output.reset()?;
        if let Some(annotation) = annotation {
            let mut spec = ColorSpec::new();
            spec.set_fg(Some(Color::Yellow));
            self.output.set_color(&spec)?;
            write!(self.output, " ({annotation})")?;
            self.output.reset()?;
        }
        writeln!(self.output)?;
        Ok(())
    }

    fn print_pushed(&mut self, pn: &PatchName, status: PushStatus, is_last: bool) -> Result<()> {
        let annotation = match status {
            PushStatus::New => Some("new"),
            PushStatus::AlreadyMerged => Some("merged"),
            PushStatus::Conflict => Some("conflict"),
            PushStatus::Empty => Some("empty"),
            PushStatus::Modified | PushStatus::Unmodified => None,
        };
        if is_last {
            self.printed_top = true;
            self.write_status(">", pn, annotation, StatusKind::Top)
        } else {
            self.write_status("+", pn, annotation, StatusKind::Applied)
        }
    }

    fn print_popped(&mut self, popped: &[PatchName]) -> Result<()> {
        if popped.is_empty() {
            return Ok(());
        }
        let mut spec = ColorSpec::new();
        spec.set_fg(Some(Color::Magenta));
        self.output.set_color(&spec)?;
        write!(self.output, "- ")?;
        self.output.reset()?;
        let mut spec = ColorSpec::new();
        spec.set_dimmed(true);
        self.output.set_color(&spec)?;
        if popped.len() == 1 {
            write!(self.output, "{}", popped[0])?;
        } else {
            write!(self.output, "{}..{}", popped[0], popped[popped.len() - 1])?;
        }
        self.output.reset()?;
        writeln!(self.output)?;
        Ok(())
    }

    pub fn print_top(&mut self) -> Result<()> {
        if let Some(top) = self.applied.last().cloned() {
            self.printed_top = true;
            self.write_status(">", &top, None, StatusKind::Top)?;
        }
        Ok(())
    }

    fn print_hidden(&mut self, pn: &PatchName) -> Result<()> {
        self.write_status("!", pn, None, StatusKind::Hidden)
    }

    fn print_unhidden(&mut self, pn: &PatchName) -> Result<()> {
        self.write_status("-", pn, None, StatusKind::Unapplied)
    }

    fn print_deleted(&mut self, pn: &PatchName) -> Result<()> {
        self.write_status("#", pn, None, StatusKind::Deleted)
    }

    pub fn print_updated(&mut self, pn: &PatchName) -> Result<()> {
        self.write_status("&", pn, None, StatusKind::Updated)
    }

    fn print_committed(&mut self, pn: &PatchName) -> Result<()> {
        self.write_status("$", pn, None, StatusKind::Committed)
    }

    fn print_rename(&mut self, old: &PatchName, new: &PatchName) -> Result<()> {
        let mut spec = ColorSpec::new();
        spec.set_dimmed(true);
        self.output.set_color(&spec)?;
        write!(self.output, "{old}")?;
        self.output.reset()?;
        write!(self.output, " => ")?;
        let mut spec = ColorSpec::new();
        spec.set_bold(true);
        self.output.set_color(&spec)?;
        write!(self.output, "{new}")?;
        self.output.reset()?;
        writeln!(self.output)?;
        Ok(())
    }

    pub fn print_merged(&mut self, merged: &[&PatchName]) -> Result<()> {
        if merged.len() == 1 {
            writeln!(self.output, "Found 1 patch merged upstream")?;
        } else {
            writeln!(self.output, "Found {} patches merged upstream", merged.len())?;
        }
        Ok(())
    }

    pub fn print_message(&mut self, msg: &str) -> Result<()> {
        writeln!(self.output, "{msg}")?;
        Ok(())
    }

    // ---- operations ----

    /// Add a new patch to the top of the applied stack.
    pub fn new_applied(&mut self, pn: &PatchName, commit: Rc<Commit>) -> Result<()> {
        self.updated_patches.insert(pn.clone(), Some(commit));
        self.applied.push(pn.clone());
        self.print_pushed(pn, PushStatus::New, true)
    }

    /// Add a new unapplied patch at the given position in the unapplied list.
    pub fn new_unapplied(&mut self, pn: &PatchName, commit: Rc<Commit>, index: usize) -> Result<()> {
        self.updated_patches.insert(pn.clone(), Some(commit));
        let index = index.min(self.unapplied.len());
        self.unapplied.insert(index, pn.clone());
        self.write_status("-", pn, Some("new"), StatusKind::Unapplied)
    }

    /// Replace the commit for an existing patch.
    pub fn update_patch(&mut self, pn: &PatchName, commit: Rc<Commit>) -> Result<()> {
        self.updated_patches.insert(pn.clone(), Some(commit));
        Ok(())
    }

    /// Update a patch and print "& patch".
    pub fn update_patch_print(&mut self, pn: &PatchName, commit: Rc<Commit>) -> Result<()> {
        self.update_patch(pn, commit)?;
        self.print_updated(pn)
    }

    /// Set the base (used by commit/uncommit/rebase).
    pub fn update_base(&mut self, commit: Rc<Commit>) {
        self.updated_base = Some(commit);
    }

    pub fn rename_patch(&mut self, old: &PatchName, new: &PatchName) -> Result<()> {
        if old == new {
            return Ok(());
        }
        if self.has_patch(new) {
            return Err(anyhow!("patch `{new}` already exists"));
        }
        let commit = self.get_patch_commit(old);
        self.updated_patches.insert(old.clone(), None);
        self.updated_patches.insert(new.clone(), Some(commit));
        for list in [&mut self.applied, &mut self.unapplied, &mut self.hidden] {
            if let Some(pos) = list.iter().position(|p| p == old) {
                list[pos] = new.clone();
            }
        }
        self.print_rename(old, new)
    }

    /// Delete the given patches. Applied patches must be popped first by the caller
    /// (or this will pop them).
    pub fn delete_patches(&mut self, to_delete: &[PatchName]) -> Result<Vec<PatchName>> {
        // Pop applied patches that are to be deleted (and everything above the lowest).
        let popped = self.pop_patches(|pn| to_delete.contains(pn))?;
        for pn in to_delete {
            if let Some(pos) = self.unapplied.iter().position(|p| p == pn) {
                self.unapplied.remove(pos);
            } else if let Some(pos) = self.hidden.iter().position(|p| p == pn) {
                self.hidden.remove(pos);
            }
            self.updated_patches.insert(pn.clone(), None);
            self.print_deleted(pn)?;
        }
        Ok(popped
            .into_iter()
            .filter(|pn| !to_delete.contains(pn))
            .collect())
    }

    pub fn hide_patches(&mut self, to_hide: &[PatchName]) -> Result<()> {
        let applied: Vec<PatchName> = self
            .applied
            .iter()
            .filter(|pn| !to_hide.contains(pn))
            .cloned()
            .collect();
        let unapplied: Vec<PatchName> = self
            .unapplied
            .iter()
            .filter(|pn| !to_hide.contains(pn))
            .cloned()
            .collect();
        let mut hidden: Vec<PatchName> = to_hide.to_vec();
        hidden.extend(self.hidden.iter().cloned());
        self.reorder_patches(Some(&applied), Some(&unapplied), Some(&hidden))?;
        for pn in to_hide {
            self.print_hidden(pn)?;
        }
        Ok(())
    }

    pub fn unhide_patches(&mut self, to_unhide: &[PatchName]) -> Result<()> {
        let mut unapplied = self.unapplied.clone();
        unapplied.extend(to_unhide.iter().cloned());
        let hidden: Vec<PatchName> = self
            .hidden
            .iter()
            .filter(|pn| !to_unhide.contains(pn))
            .cloned()
            .collect();
        for pn in to_unhide {
            self.print_unhidden(pn)?;
        }
        self.reorder_patches(None, Some(&unapplied), Some(&hidden))?;
        Ok(())
    }

    /// Pop applied patches matching the predicate. Patches above the lowest
    /// matched patch are also popped. Returns the popped patches that did NOT
    /// match (they may need to be re-pushed) -- in the order they were applied.
    pub fn pop_patches<F>(&mut self, should_pop: F) -> Result<Vec<PatchName>>
    where
        F: Fn(&PatchName) -> bool,
    {
        let lowest = self.applied.iter().position(|pn| should_pop(pn));
        let Some(lowest) = lowest else {
            return Ok(Vec::new());
        };
        let popped: Vec<PatchName> = self.applied.split_off(lowest);
        let mut unapplied_insert: Vec<PatchName> = Vec::new();
        let mut incidental: Vec<PatchName> = Vec::new();
        for pn in &popped {
            if should_pop(pn) {
                unapplied_insert.push(pn.clone());
            } else {
                incidental.push(pn.clone());
            }
        }
        // Incidentally popped patches go to the front of unapplied, followed by
        // the explicitly popped ones (in reverse-applied order so the lowest is
        // the next to push).
        let mut new_unapplied: Vec<PatchName> = Vec::new();
        new_unapplied.extend(incidental.iter().cloned());
        new_unapplied.extend(unapplied_insert.iter().cloned());
        new_unapplied.extend(self.unapplied.iter().cloned());
        self.unapplied = new_unapplied;
        self.print_popped(&popped)?;
        Ok(incidental)
    }

    /// Check which of the given patches are already merged upstream.
    pub fn check_merged<'a>(&mut self, patches: &'a [PatchName]) -> Result<Vec<&'a PatchName>> {
        let mut merged: Vec<&'a PatchName> = Vec::new();
        let head_tree_id = self.top().tree_id;
        let repo = self.stack.repo;
        let stupid = repo.stupid();
        let patches_info: Vec<(&PatchName, Oid, Oid)> = patches
            .iter()
            .map(|pn| {
                let c = self.get_patch_commit(pn);
                let parent_tree = c
                    .parent_ids
                    .first()
                    .and_then(|p| repo.find_commit(*p).ok())
                    .map(|p| p.tree_id)
                    .unwrap_or(c.tree_id);
                (pn, c.tree_id, parent_tree)
            })
            .collect();
        stupid.with_temp_index(|temp| {
            temp.read_tree(head_tree_id)?;
            for (pn, tree_id, parent_tree_id) in patches_info.iter().rev() {
                if tree_id == parent_tree_id {
                    continue;
                }
                if temp.apply_treediff_to_index(*tree_id, *parent_tree_id, true)? {
                    merged.push(pn);
                }
            }
            Ok(())
        })?;
        self.print_merged(&merged)?;
        Ok(merged)
    }

    /// Push the given unapplied patches.
    pub fn push_patches(&mut self, patches: &[PatchName], check_merged: bool) -> Result<()> {
        let merged: Vec<PatchName> = if check_merged {
            self.check_merged(patches)?.into_iter().cloned().collect()
        } else {
            Vec::new()
        };
        let n = patches.len();
        for (i, pn) in patches.iter().enumerate() {
            let is_last = i + 1 == n;
            let already_merged = merged.contains(pn);
            self.push_patch(pn, already_merged, is_last)?;
        }
        Ok(())
    }

    fn checkout_tree(&mut self, tree_id: Oid) -> Result<()> {
        if self.current_tree_id == tree_id {
            return Ok(());
        }
        let stupid = self.stack.repo.stupid();
        if self.discard_changes {
            stupid.read_tree_checkout_hard(tree_id)?;
        } else {
            stupid.read_tree_checkout(self.current_tree_id, tree_id)?;
        }
        self.current_tree_id = tree_id;
        Ok(())
    }

    /// Push a single patch onto the stack.
    pub fn push_patch(&mut self, pn: &PatchName, already_merged: bool, is_last: bool) -> Result<()> {
        let repo = self.stack.repo;
        let patch_commit = self.get_patch_commit(pn);
        let new_parent = self.top();
        let old_parent_id = patch_commit
            .parent_ids
            .first()
            .copied()
            .ok_or_else(|| anyhow!("patch `{pn}` has no parent"))?;
        let old_parent = repo.find_commit(old_parent_id)?;
        let base_tree = old_parent.tree_id;
        let ours_tree = new_parent.tree_id;
        let theirs_tree = patch_commit.tree_id;
        let is_empty = base_tree == theirs_tree;

        let (new_tree_id, mut status) = if already_merged {
            (ours_tree, PushStatus::AlreadyMerged)
        } else if base_tree == ours_tree {
            (theirs_tree, PushStatus::Unmodified)
        } else if is_empty {
            (ours_tree, PushStatus::Empty)
        } else {
            let stupid = repo.stupid();
            let maybe_tree = stupid.with_temp_index(|temp| {
                temp.read_tree(ours_tree)?;
                if temp.apply_treediff_to_index(base_tree, theirs_tree, false)? {
                    Ok(Some(temp.write_tree()?))
                } else {
                    Ok(None)
                }
            })?;
            match maybe_tree {
                Some(tree) => (tree, PushStatus::Modified),
                None => {
                    if !self.use_index_and_worktree {
                        return Err(self.halt(anyhow!(
                            "pushing patch `{pn}` would result in conflicts and \
                             push conflicts are disallowed"
                        )));
                    }
                    if !self.allow_push_conflicts {
                        // Check whether it would conflict before touching the worktree.
                        let would_conflict = stupid.with_temp_index(|temp| {
                            temp.read_tree(ours_tree)?;
                            Ok(!temp.apply_treediff_to_index(base_tree, theirs_tree, true)?)
                        })?;
                        if would_conflict {
                            // Attempt a worktree merge to determine conflicts properly.
                            let saved_tree = self.current_tree_id;
                            self.checkout_tree(ours_tree)?;
                            let clean = stupid.merge_recursive(base_tree, ours_tree, theirs_tree)?;
                            if clean {
                                let tree = stupid.write_tree()?;
                                self.current_tree_id = tree;
                                (tree, PushStatus::Modified)
                            } else {
                                // undo the merge attempt
                                stupid.read_tree_checkout_hard(ours_tree)?;
                                self.current_tree_id = ours_tree;
                                let _ = saved_tree;
                                return Err(self.halt(anyhow!(
                                    "pushing patch `{pn}` would result in conflicts and \
                                     push conflicts are disallowed"
                                )));
                            }
                        } else {
                            unreachable!()
                        }
                    } else {
                        self.checkout_tree(ours_tree)?;
                        let clean = stupid.merge_recursive(base_tree, ours_tree, theirs_tree)?;
                        if clean {
                            let tree = stupid.write_tree()?;
                            self.current_tree_id = tree;
                            (tree, PushStatus::Modified)
                        } else {
                            self.conflicts = stupid.conflict_paths()?;
                            (ours_tree, PushStatus::Conflict)
                        }
                    }
                }
            }
        };

        let new_commit = if new_parent.id == old_parent_id && new_tree_id == theirs_tree {
            if status != PushStatus::Conflict && status != PushStatus::AlreadyMerged {
                status = PushStatus::Unmodified;
            }
            patch_commit.clone()
        } else {
            let commit = self.commit_patch(
                &patch_commit.author,
                &patch_commit.message,
                new_tree_id,
                &[new_parent.id],
            )?;
            if status == PushStatus::Modified || status == PushStatus::Unmodified || status == PushStatus::Empty {
                status = if new_tree_id == ours_tree {
                    PushStatus::Empty
                } else {
                    PushStatus::Modified
                };
            }
            commit
        };

        self.updated_patches.insert(pn.clone(), Some(new_commit));
        if let Some(pos) = self.unapplied.iter().position(|p| p == pn) {
            self.unapplied.remove(pos);
        } else if let Some(pos) = self.hidden.iter().position(|p| p == pn) {
            self.hidden.remove(pos);
        }
        self.applied.push(pn.clone());

        if status == PushStatus::Conflict {
            self.print_pushed(pn, status, is_last)?;
            return Err(self.halt(Error::CausedConflicts(
                "merge conflicts; resolve conflicts manually then refresh or undo the operation with `stg undo --hard`.".to_string(),
            )
            .into()));
        }
        self.print_pushed(pn, status, is_last)
    }

    /// Push a patch keeping its tree (--set-tree).
    pub fn push_tree(&mut self, pn: &PatchName, is_last: bool) -> Result<()> {
        let patch_commit = self.get_patch_commit(pn);
        let new_parent = self.top();
        let old_parent_id = patch_commit.parent_ids.first().copied();
        let new_commit = if old_parent_id == Some(new_parent.id) {
            patch_commit.clone()
        } else {
            self.commit_patch(
                &patch_commit.author,
                &patch_commit.message,
                patch_commit.tree_id,
                &[new_parent.id],
            )?
        };
        let status = if new_commit.tree_id == new_parent.tree_id && new_commit.id != patch_commit.id {
            PushStatus::Empty
        } else {
            PushStatus::Unmodified
        };
        self.updated_patches.insert(pn.clone(), Some(new_commit));
        if let Some(pos) = self.unapplied.iter().position(|p| p == pn) {
            self.unapplied.remove(pos);
        } else if let Some(pos) = self.hidden.iter().position(|p| p == pn) {
            self.hidden.remove(pos);
        }
        self.applied.push(pn.clone());
        self.print_pushed(pn, status, is_last)
    }

    /// Reorder patches: pops and pushes as necessary so that the applied,
    /// unapplied and hidden lists match those given.
    pub fn reorder_patches(
        &mut self,
        applied: Option<&[PatchName]>,
        unapplied: Option<&[PatchName]>,
        hidden: Option<&[PatchName]>,
    ) -> Result<()> {
        if let Some(applied) = applied {
            // Determine common prefix of current applied and desired applied.
            let num_common = self
                .applied
                .iter()
                .zip(applied.iter())
                .take_while(|(a, b)| a == b)
                .count();
            let to_pop: Vec<PatchName> = self.applied[num_common..].to_vec();
            if !to_pop.is_empty() {
                let popped = self.applied.split_off(num_common);
                // Put popped patches at the front of unapplied for now.
                let mut new_unapplied = popped.clone();
                new_unapplied.extend(self.unapplied.iter().cloned());
                self.unapplied = new_unapplied;
                self.print_popped(&popped)?;
            }
            let to_push: Vec<PatchName> = applied[num_common..].to_vec();
            self.push_patches(&to_push, false)?;
        }
        if let Some(unapplied) = unapplied {
            self.unapplied = unapplied.to_vec();
        }
        if let Some(hidden) = hidden {
            self.hidden = hidden.to_vec();
        }
        Ok(())
    }

    /// Reset the transaction state to the given stack state (undo/redo/reset).
    pub fn reset_to_state(&mut self, state: &StackState) -> Result<()> {
        // Remove patches not in new state.
        let new_names: Vec<&PatchName> = state.all_patches().collect();
        for pn in self.all_patches().cloned().collect::<Vec<_>>() {
            if !new_names.contains(&&pn) {
                self.updated_patches.insert(pn.clone(), None);
            }
        }
        for (pn, commit) in &state.patches {
            self.updated_patches.insert(pn.clone(), Some(commit.clone()));
        }
        self.applied = state.applied.clone();
        self.unapplied = state.unapplied.clone();
        self.hidden = state.hidden.clone();
        self.updated_head = Some(state.head.clone());
        self.updated_base = Some(state.base(self.stack.repo)?);
        Ok(())
    }

    /// Reset only the given patches to their state in `state`.
    pub fn reset_to_state_partially(&mut self, state: &StackState, patches: &[PatchName]) -> Result<()> {
        // Patches to pop: any applied patch that is in `patches` set
        let popped = self.pop_patches(|pn| patches.contains(pn))?;
        for pn in patches {
            match state.patches.get(pn) {
                Some(commit) => {
                    self.updated_patches.insert(pn.clone(), Some(commit.clone()));
                    if !self.has_patch(pn) {
                        // re-add as unapplied
                        self.unapplied.insert(0, pn.clone());
                    }
                }
                None => {
                    if self.has_patch(pn) {
                        self.unapplied.retain(|p| p != pn);
                        self.hidden.retain(|p| p != pn);
                        self.updated_patches.insert(pn.clone(), None);
                        self.print_deleted(pn)?;
                    }
                }
            }
        }
        // Push patches in order of the saved state's applied list that were applied
        // in the saved state and are in `patches`.
        let to_push: Vec<PatchName> = state
            .applied
            .iter()
            .filter(|pn| patches.contains(pn) && self.has_patch(pn))
            .cloned()
            .collect();
        let mut all_push = to_push;
        all_push.extend(popped);
        self.push_patches(&all_push, false)?;
        Ok(())
    }

    /// Commit (finalize) the bottommost applied patches into the base.
    pub fn commit_patches(&mut self, patches: &[PatchName]) -> Result<()> {
        // patches must be a prefix of applied
        for pn in patches {
            let commit = self.get_patch_commit(pn);
            self.updated_base = Some(commit);
            self.applied.retain(|p| p != pn);
            self.updated_patches.insert(pn.clone(), None);
            self.print_committed(pn)?;
        }
        Ok(())
    }

    /// Uncommit: insert existing commits as applied patches at the bottom.
    pub fn uncommit_patches(&mut self, patches: &[(PatchName, Rc<Commit>)]) -> Result<()> {
        // patches given from topmost (nearest base) to bottommost
        let mut new_applied: Vec<PatchName> = Vec::new();
        for (pn, commit) in patches.iter().rev() {
            self.updated_patches.insert(pn.clone(), Some(commit.clone()));
            new_applied.push(pn.clone());
        }
        let (last_pn, last_commit) = patches.last().unwrap();
        let _ = last_pn;
        let new_base_id = last_commit
            .parent_ids
            .first()
            .ok_or_else(|| anyhow!("commit `{}` does not have a parent", last_commit.id))?;
        self.updated_base = Some(self.stack.repo.find_commit(*new_base_id)?);
        new_applied.extend(self.applied.iter().cloned());
        self.applied = new_applied;
        for (pn, _) in patches.iter().rev() {
            self.write_status("+", pn, None, StatusKind::Applied)?;
        }
        Ok(())
    }

    /// Set the unapplied list directly (used by push --noapply etc).
    pub fn set_unapplied(&mut self, unapplied: Vec<PatchName>) {
        self.unapplied = unapplied;
    }

    pub fn set_hidden(&mut self, hidden: Vec<PatchName>) {
        self.hidden = hidden;
    }

    pub fn set_applied(&mut self, applied: Vec<PatchName>) {
        self.applied = applied;
    }

    /// Update head directly (e.g. rebase changes base).
    pub fn set_head_commit(&mut self, commit: Rc<Commit>) {
        self.updated_head = Some(commit);
    }

    // ---- finishing ----

    fn rollback(&mut self) -> Result<()> {
        if self.use_index_and_worktree && self.current_tree_id != self.initial_tree_id {
            let stupid = self.stack.repo.stupid();
            stupid.read_tree_checkout_hard(self.initial_tree_id)?;
            self.current_tree_id = self.initial_tree_id;
        }
        Ok(())
    }

    pub fn set_reflog_msg(&mut self, msg: &str) {
        self.reflog_msg = Some(msg.to_string());
    }

    fn commit_transaction(mut self) -> Result<Stack<'repo>> {
        let repo = self.stack.repo;
        let reflog_msg = self.reflog_msg.clone().unwrap_or_else(|| "stg".to_string());

        // Determine new head.
        let new_head = match &self.updated_head {
            Some(h) => h.clone(),
            None => self.top(),
        };
        let head_changed = new_head.id != self.stack.branch_head.id;

        // Print top if needed (unless halted with an error).
        if !self.halted && self.error.is_none() && !self.printed_top {
            if let Some(top) = self.applied.last().cloned() {
                // Only print top if the top changed or something was printed.
                let _ = top;
                self.print_top()?;
            }
        }
        if self.error.is_some() && !self.printed_top {
            // nothing
        }
        self.output.flush()?;

        // Build the new state.
        let mut patches: BTreeMap<PatchName, Rc<Commit>> = BTreeMap::new();
        for pn in self.all_patches() {
            let commit = self.get_patch_commit(pn);
            patches.insert(pn.clone(), commit);
        }
        let prev_log_id = self.stack.ensure_log_id()?;
        let state = StackState {
            prev: Some(prev_log_id),
            head: new_head.clone(),
            applied: self.applied.clone(),
            unapplied: self.unapplied.clone(),
            hidden: self.hidden.clone(),
            patches,
        };

        let committer = Signature::default_committer(&repo.config);
        let author = Signature::default_author(&repo.config);
        let (author, committer) = match (author, committer) {
            (Ok(a), Ok(c)) => (a, c),
            (Err(e), _) | (_, Err(e)) => {
                return Err(self.abort_with(e));
            }
        };

        let log_msg = if let Some(err) = &self.error {
            if err.downcast_ref::<Error>().map(|e| matches!(e, Error::CausedConflicts(_))).unwrap_or(false) {
                format!("{reflog_msg} (CONFLICT)")
            } else {
                reflog_msg.clone()
            }
        } else {
            reflog_msg.clone()
        };

        let log_id = match state.commit(repo, Some(prev_log_id), &log_msg, &author, &committer) {
            Ok(id) => id,
            Err(e) => return Err(self.abort_with(e)),
        };

        // Update the index and worktree.
        if self.use_index_and_worktree && head_changed && self.set_head {
            let target_tree = new_head.tree_id;
            if self.current_tree_id != target_tree {
                let stupid = repo.stupid();
                let result = if self.discard_changes {
                    stupid.read_tree_checkout_hard(target_tree)
                } else {
                    stupid.read_tree_checkout(self.current_tree_id, target_tree)
                };
                if let Err(e) = result {
                    return Err(self.abort_with(e));
                }
                self.current_tree_id = target_tree;
            }
        }

        // Ref updates.
        let mut updates: Vec<RefUpdate> = Vec::new();
        for (pn, commit) in &self.updated_patches {
            let refname = self.stack.get_patch_refname(pn);
            match commit {
                Some(c) => updates.push(RefUpdate::Update {
                    refname,
                    oid: c.id,
                    msg: reflog_msg.clone(),
                }),
                None => {
                    if self.stack.has_patch(pn) {
                        updates.push(RefUpdate::Delete { refname });
                    }
                }
            }
        }
        // Make sure patch refs exist for all patches (e.g. after init).
        if !self.stack.is_initialized {
            for (pn, commit) in &state.patches {
                if !self.updated_patches.contains_key(pn) {
                    updates.push(RefUpdate::Update {
                        refname: self.stack.get_patch_refname(pn),
                        oid: commit.id,
                        msg: reflog_msg.clone(),
                    });
                }
            }
        }
        updates.push(RefUpdate::Update {
            refname: self.stack.get_stack_refname(),
            oid: log_id,
            msg: reflog_msg.clone(),
        });
        if head_changed && self.set_head {
            updates.push(RefUpdate::Update {
                refname: self.stack.get_branch_refname(),
                oid: new_head.id,
                msg: reflog_msg.clone(),
            });
        }
        repo.update_refs(&updates)?;

        // Update the stack object.
        let mut stack = self.stack;
        stack.state = state;
        stack.log_id = Some(log_id);
        stack.is_initialized = true;
        if head_changed && self.set_head {
            stack.branch_head = new_head.clone();
        }
        stack.base = stack.state.base(repo)?;

        if let Some(err) = self.error {
            // Print conflicts after the error message is printed by main; we
            // attach conflicts to the error.
            if let Some(Error::CausedConflicts(msg)) = err.downcast_ref::<Error>() {
                return Err(Error::CausedConflictsWithPaths(
                    msg.clone(),
                    self.conflicts.clone(),
                )
                .into());
            }
            return Err(err);
        }
        Ok(stack)
    }

    fn abort_with(&mut self, err: anyhow::Error) -> anyhow::Error {
        let _ = self.rollback();
        if let Some(top) = self.stack.state.applied.last().cloned() {
            let _ = self.write_status("@", &top, Some("rolled back"), StatusKind::RolledBack);
        }
        let _ = self.output.flush();
        anyhow!("{err};\ncommand aborted (all changes rolled back)")
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum StatusKind {
    Top,
    Applied,
    Unapplied,
    Hidden,
    Deleted,
    Updated,
    Committed,
    RolledBack,
    Plain,
}
EOF
