//! Error types and error printing.

use std::io::Write;

use bstr::BString;

use crate::color::{Color, ColorChoice, ColorSpec};

#[derive(Debug)]
pub enum Error {
    /// Merge conflicts occurred; exit code 3.
    CausedConflicts(String),
    CausedConflictsWithPaths(String, Vec<BString>),
    /// Conflicts in the repository prevent the operation; exit code 2.
    OutstandingConflicts,
    /// Error with a custom exit code.
    Exit(i32, String),
}

impl std::fmt::Display for Error {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Error::CausedConflicts(msg) => f.write_str(msg),
            Error::CausedConflictsWithPaths(msg, _) => f.write_str(msg),
            Error::OutstandingConflicts => f.write_str("resolve outstanding conflicts first"),
            Error::Exit(_, msg) => f.write_str(msg),
        }
    }
}

impl std::error::Error for Error {}

pub fn exit_code(err: &anyhow::Error) -> i32 {
    match err.downcast_ref::<Error>() {
        Some(Error::CausedConflicts(_)) | Some(Error::CausedConflictsWithPaths(_, _)) => 3,
        Some(Error::Exit(code, _)) => *code,
        _ => 2,
    }
}

/// Print "error: <message>" to stderr, colorizing backtick-quoted spans.
pub fn print_error_message(err: &anyhow::Error, color_choice: ColorChoice) {
    let mut stderr = crate::color::stderr(color_choice);
    let msg = format!("{err:#}");
    let mut spec = ColorSpec::new();
    spec.set_bold(true).set_fg(Some(Color::Red));
    let _ = stderr.set_color(&spec);
    let _ = write!(stderr, "error: ");
    let _ = stderr.reset();
    write_quoted_colored(&mut stderr, &msg);
    let _ = writeln!(stderr);
    let _ = stderr.flush();

    if let Some(Error::CausedConflictsWithPaths(_, paths)) = err.downcast_ref::<Error>() {
        print_conflict_paths(paths, color_choice);
    }
}

fn write_quoted_colored<W: Write>(w: &mut crate::color::ColorWriter<W>, msg: &str) {
    let mut rest = msg;
    loop {
        match rest.find('`') {
            Some(start) => {
                let after = &rest[start + 1..];
                match after.find('`') {
                    Some(end) => {
                        let _ = write!(w, "{}`", &rest[..start]);
                        let mut spec = ColorSpec::new();
                        spec.set_fg(Some(Color::Yellow));
                        let _ = w.set_color(&spec);
                        let _ = write!(w, "{}", &after[..end]);
                        let _ = w.reset();
                        let _ = write!(w, "`");
                        rest = &after[end + 1..];
                    }
                    None => {
                        let _ = write!(w, "{rest}");
                        break;
                    }
                }
            }
            None => {
                let _ = write!(w, "{rest}");
                break;
            }
        }
    }
}

fn print_conflict_paths(paths: &[BString], color_choice: ColorChoice) {
    // Use git status to get the status codes of the unmerged paths.
    let mut stdout = crate::color::stdout(color_choice);
    let repo = match crate::git::Repository::open() {
        Ok(r) => r,
        Err(_) => return,
    };
    let stupid = repo.stupid();
    let statuses = match stupid.statuses(false) {
        Ok(s) => s,
        Err(_) => return,
    };
    let mut printed = false;
    for entry in statuses.iter().filter(|e| e.is_conflict()) {
        if !paths.is_empty() && !paths.contains(&entry.path) {
            continue;
        }
        printed = true;
        let mut spec = ColorSpec::new();
        spec.set_fg(Some(Color::Red));
        let _ = stdout.set_color(&spec);
        let _ = write!(stdout, "{}{}", entry.xy[0] as char, entry.xy[1] as char);
        let _ = stdout.reset();
        let _ = writeln!(stdout, " {}", entry.path);
    }
    if !printed {
        for path in paths {
            let _ = writeln!(stdout, "UU {path}");
        }
    }
    let _ = stdout.flush();
}
EOF
