//! Patch locators and ranges.

use std::str::FromStr;

use anyhow::{anyhow, Result};
use clap::Arg;

use super::PatchName;
use crate::stack::Stack;

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum LocatorBase {
    /// `@` -- topmost applied patch
    Top,
    /// `^N` -- Nth patch from the last patch
    Last(i64),
    /// `{base}` -- the stack base (requires an offset)
    Base,
    /// Absolute index
    Index(usize),
    /// A patch name
    Name(PatchName),
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct PatchLocator {
    pub base: LocatorBase,
    /// Offsets: positive is forward (`+N`), negative is backward (`~N`).
    pub offsets: Vec<i64>,
    pub raw: String,
}

fn parse_offsets(s: &str, allow_minus: bool) -> Option<Vec<i64>> {
    let mut offsets = Vec::new();
    let mut rest = s;
    while !rest.is_empty() {
        let c = rest.chars().next().unwrap();
        let sign = match c {
            '+' => 1,
            '~' => -1,
            '-' if allow_minus => -1,
            _ => return None,
        };
        rest = &rest[1..];
        let digits_end = rest
            .char_indices()
            .find(|(_, c)| !c.is_ascii_digit())
            .map(|(i, _)| i)
            .unwrap_or(rest.len());
        let n: i64 = if digits_end == 0 {
            1
        } else {
            rest[..digits_end].parse().ok()?
        };
        rest = &rest[digits_end..];
        offsets.push(sign * n);
    }
    Some(offsets)
}

impl FromStr for PatchLocator {
    type Err = anyhow::Error;

    fn from_str(s: &str) -> Result<PatchLocator> {
        let err = || anyhow!("invalid patch locator `{s}`");
        if s.is_empty() {
            return Err(err());
        }
        let raw = s.to_string();
        // `@` with offsets
        if let Some(rest) = s.strip_prefix('@') {
            if let Some(offsets) = parse_offsets(rest, false) {
                return Ok(PatchLocator {
                    base: LocatorBase::Top,
                    offsets,
                    raw,
                });
            }
            // fall through to patch name
        }
        if let Some(rest) = s.strip_prefix('^') {
            // optional signed integer, then offsets
            let mut idx = 0;
            let bytes = rest.as_bytes();
            if idx < bytes.len() && (bytes[idx] == b'-' || bytes[idx] == b'+') {
                idx += 1;
            }
            while idx < bytes.len() && bytes[idx].is_ascii_digit() {
                idx += 1;
            }
            let num_str = &rest[..idx];
            let n: i64 = if num_str.is_empty() || num_str == "-" || num_str == "+" {
                if num_str.is_empty() {
                    0
                } else {
                    return Err(err());
                }
            } else {
                num_str.parse().map_err(|_| err())?
            };
            let offsets = parse_offsets(&rest[idx..], false).ok_or_else(err)?;
            return Ok(PatchLocator {
                base: LocatorBase::Last(n),
                offsets,
                raw,
            });
        }
        if let Some(rest) = s.strip_prefix("{base}") {
            let offsets = parse_offsets(rest, false).ok_or_else(err)?;
            return Ok(PatchLocator {
                base: LocatorBase::Base,
                offsets,
                raw,
            });
        }
        if s.chars().all(|c| c.is_ascii_digit()) {
            let n: usize = s.parse().map_err(|_| err())?;
            return Ok(PatchLocator {
                base: LocatorBase::Index(n),
                offsets: Vec::new(),
                raw,
            });
        }
        if s.starts_with(['+', '-', '~']) {
            if let Some(offsets) = parse_offsets(s, true) {
                return Ok(PatchLocator {
                    base: LocatorBase::Top,
                    offsets,
                    raw,
                });
            }
        }
        // Patch name with optional `~N` / `+N` offsets.
        let split = s
            .char_indices()
            .find(|(_, c)| *c == '~' || *c == '+')
            .map(|(i, _)| i)
            .unwrap_or(s.len());
        let (name_part, offset_part) = s.split_at(split);
        let name = PatchName::from_str(name_part).map_err(|_| err())?;
        let offsets = parse_offsets(offset_part, false).ok_or_else(err)?;
        Ok(PatchLocator {
            base: LocatorBase::Name(name),
            offsets,
            raw,
        })
    }
}

impl PatchLocator {
    /// Resolve this locator to an index into `patches` (the full ordered list).
    pub fn resolve(&self, stack: &Stack, patches: &[PatchName]) -> Result<usize> {
        let (mut index, desc): (i64, String) = match &self.base {
            LocatorBase::Top => {
                if stack.applied().is_empty() {
                    if self.offsets.is_empty() {
                        return Err(anyhow!("no patches applied"));
                    }
                    (-1, "topmost patch".to_string())
                } else {
                    let top = stack.applied().last().unwrap();
                    let idx = patches
                        .iter()
                        .position(|p| p == top)
                        .ok_or_else(|| anyhow!("no patches applied"))?;
                    (idx as i64, "topmost patch".to_string())
                }
            }
            LocatorBase::Last(n) => {
                let last = patches.len() as i64 - 1;
                let idx = last - n;
                if idx < 0 || idx >= patches.len() as i64 {
                    return Err(anyhow!("no patch at {} from last patch", fmt_signed(-n)));
                }
                (idx, "last patch".to_string())
            }
            LocatorBase::Base => {
                if self.offsets.is_empty() {
                    return Err(anyhow!(
                        "an offset is required when locating a patch relative to the stack base"
                    ));
                }
                (-1, "stack base".to_string())
            }
            LocatorBase::Index(n) => {
                if *n >= patches.len() {
                    return Err(anyhow!("invalid patch index `{n}`"));
                }
                (*n as i64, format!("`{n}`"))
            }
            LocatorBase::Name(name) => {
                let idx = patches
                    .iter()
                    .position(|p| p == name)
                    .ok_or_else(|| stack.patch_not_found_error(name.as_str()))?;
                (idx as i64, format!("`{name}`"))
            }
        };
        for offset in &self.offsets {
            let new_index = index + offset;
            if new_index < 0 || new_index >= patches.len() as i64 {
                let off_str = if *offset < 0 {
                    format!("~{}", -offset)
                } else {
                    format!("+{offset}")
                };
                return Err(anyhow!("`{off_str}` from {desc} goes outside the stack"));
            }
            index = new_index;
        }
        Ok(index as usize)
    }
}

fn fmt_signed(n: i64) -> String {
    if n >= 0 {
        format!("+{n}")
    } else {
        format!("{n}")
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum PatchRangeItem {
    Single(PatchLocator),
    Range(Option<PatchLocator>, Option<PatchLocator>),
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct PatchRange {
    pub item: PatchRangeItem,
    pub raw: String,
}

impl FromStr for PatchRange {
    type Err = anyhow::Error;

    fn from_str(s: &str) -> Result<PatchRange> {
        let err = || anyhow!("invalid patch range `{s}`");
        if s.is_empty() {
            return Err(err());
        }
        if let Some(pos) = s.find("..") {
            let (a, b) = (&s[..pos], &s[pos + 2..]);
            if b.contains("..") {
                return Err(err());
            }
            let a = if a.is_empty() {
                None
            } else {
                Some(PatchLocator::from_str(a).map_err(|_| err())?)
            };
            let b = if b.is_empty() {
                None
            } else {
                Some(PatchLocator::from_str(b).map_err(|_| err())?)
            };
            Ok(PatchRange {
                item: PatchRangeItem::Range(a, b),
                raw: s.to_string(),
            })
        } else {
            let loc = PatchLocator::from_str(s).map_err(|_| err())?;
            Ok(PatchRange {
                item: PatchRangeItem::Single(loc),
                raw: s.to_string(),
            })
        }
    }
}

impl PatchRange {
    pub fn is_range(&self) -> bool {
        matches!(self.item, PatchRangeItem::Range(_, _))
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum RangeConstraint {
    /// Patches must be visible (not hidden); any order allowed.
    Visible,
    /// Patches must be visible and ranges must be contiguous and in order.
    VisibleContiguous,
    /// Any patch (including hidden); contiguous in order (series).
    AllContiguous,
    /// Any patch, any order.
    All,
}

/// Resolve the given patch ranges to a list of patch names.
pub fn parse_patch_ranges(
    ranges: &[PatchRange],
    stack: &Stack,
    constraint: RangeConstraint,
) -> Result<Vec<PatchName>> {
    let all: Vec<PatchName> = stack.all_patches().cloned().collect();
    let visible_len = stack.applied().len() + stack.unapplied().len();
    let allow_hidden = matches!(constraint, RangeConstraint::All | RangeConstraint::AllContiguous);
    let contiguous = matches!(
        constraint,
        RangeConstraint::VisibleContiguous | RangeConstraint::AllContiguous
    );
    let list: &[PatchName] = if allow_hidden {
        &all
    } else {
        &all[..visible_len]
    };

    let mut result: Vec<PatchName> = Vec::new();
    let mut prev_range_end: Option<(usize, String)> = None;

    for range in ranges {
        match &range.item {
            PatchRangeItem::Single(loc) => {
                let idx = resolve_in_list(loc, stack, &all, list)?;
                if contiguous {
                    if let Some((prev_idx, prev_raw)) = &prev_range_end {
                        if idx != prev_idx + 1 {
                            if result.contains(&list[idx]) {
                                return Err(anyhow!("patch `{}` is used more than once", list[idx]));
                            }
                            return Err(anyhow!(
                                "`{}` not contiguous with preceding range `{}`",
                                range.raw,
                                prev_raw
                            ));
                        }
                    }
                }
                let pn = list[idx].clone();
                if result.contains(&pn) {
                    return Err(anyhow!("patch `{pn}` is used more than once"));
                }
                result.push(pn);
                prev_range_end = Some((idx, range.raw.clone()));
            }
            PatchRangeItem::Range(a, b) => {
                let start = match a {
                    Some(loc) => resolve_in_list(loc, stack, &all, list)?,
                    None => {
                        if list.is_empty() {
                            continue;
                        }
                        0
                    }
                };
                let end = match b {
                    Some(loc) => resolve_in_list(loc, stack, &all, list)?,
                    None => {
                        if list.is_empty() {
                            continue;
                        }
                        list.len() - 1
                    }
                };
                if contiguous {
                    if let Some((prev_idx, prev_raw)) = &prev_range_end {
                        if start != prev_idx + 1 {
                            return Err(anyhow!(
                                "`{}` not contiguous with preceding range `{}`",
                                range.raw,
                                prev_raw
                            ));
                        }
                    }
                    if end < start {
                        return Err(anyhow!(
                            "end patch `{}` is out of order with `{}`",
                            list[end],
                            list[start]
                        ));
                    }
                }
                let indices: Vec<usize> = if end >= start {
                    (start..=end).collect()
                } else {
                    (end..=start).rev().collect()
                };
                for idx in indices {
                    let pn = list[idx].clone();
                    if result.contains(&pn) {
                        return Err(anyhow!("patch `{pn}` is used more than once"));
                    }
                    result.push(pn);
                }
                prev_range_end = Some((end.max(start), range.raw.clone()));
            }
        }
    }
    Ok(result)
}

fn resolve_in_list(
    loc: &PatchLocator,
    stack: &Stack,
    all: &[PatchName],
    list: &[PatchName],
) -> Result<usize> {
    // Resolve against the full list so hidden patches give proper errors.
    let idx = loc.resolve(stack, all)?;
    if idx >= list.len() {
        let pn = &all[idx];
        return Err(anyhow!("hidden patch `{pn}` is not allowed"));
    }
    Ok(idx)
}

/// Resolve a single patch locator to a patch name.
pub fn resolve_single(loc: &PatchLocator, stack: &Stack, allow_hidden: bool) -> Result<PatchName> {
    let all: Vec<PatchName> = stack.all_patches().cloned().collect();
    let idx = loc.resolve(stack, &all)?;
    let pn = all[idx].clone();
    if !allow_hidden && stack.is_hidden(&pn) {
        return Err(anyhow!("hidden patch `{pn}` is not allowed"));
    }
    Ok(pn)
}

pub fn patch_range_arg() -> Arg {
    Arg::new("patchranges")
        .value_name("patch")
        .num_args(1..)
        .allow_hyphen_values(true)
        .value_parser(clap::value_parser!(PatchRange))
}

pub fn patch_range_arg_optional() -> Arg {
    Arg::new("patchranges")
        .value_name("patch")
        .num_args(0..)
        .allow_hyphen_values(true)
        .value_parser(clap::value_parser!(PatchRange))
}

pub fn get_ranges(matches: &clap::ArgMatches, id: &str) -> Vec<PatchRange> {
    matches
        .get_many::<PatchRange>(id)
        .map(|v| v.cloned().collect())
        .unwrap_or_default()
}
