impl FromStr for StGitRevision {
    type Err = anyhow::Error;

    fn from_str(s: &str) -> Result<StGitRevision> {
        if s.is_empty() {
            return Err(parse_error(s, 0));
        }
        let mut rest = s;
        let mut branch = None;
        let mut pos = 0;

        // Optional branch prefix: `<branch>:`; branch names may contain '/'
        if let Some(colon) = s.find(':') {
            let before = &s[..colon];
            if !before.is_empty() && !before.contains("..") && before.chars().all(|c| is_name_char(c) || c == '/') && !before.starts_with('{') {
                branch = Some(before.to_string());
                rest = &s[colon + 1..];
                pos = colon + 1;
                if rest.is_empty() {
                    return Err(parse_error(s, colon));
                }
            }
        }
        // Patch-like portion: `{base}` or name chars
        let patch_end = if rest.starts_with("{base}") {
            "{base}".len()
        } else {
            let mut end = 0;
            for (i, c) in rest.char_indices() {
                if c == '.' && rest[i..].starts_with("..") {
                    break;
                }
                if c == '@' && rest[i..].starts_with("@{") {
                    break;
                }
                if c == '{' || c == '}' {
                    break;
                }
                if !is_name_char(c) {
                    break;
                }
                end = i + c.len_utf8();
            }
            end
        };
        if patch_end == 0 {
            return Err(parse_error(s, pos));
        }
        let patch_like = &rest[..patch_end];
        let suffix = &rest[patch_end..];
        // Validate suffix: sequences of ^N, ~N, ^{...}, @{...}
        let mut i = 0;
        let sb = suffix.as_bytes();
        while i < sb.len() {
            match sb[i] {
                b'^' | b'~' => {
                    i += 1;
                    if i < sb.len() && sb[i] == b'{' {
                        match suffix[i..].find('}') {
                            Some(end) => i += end + 1,
                            None => return Err(parse_error(s, pos + patch_end + i)),
                        }
                    } else {
                        while i < sb.len() && sb[i].is_ascii_digit() {
                            i += 1;
                        }
                    }
                }
                b'@' if i + 1 < sb.len() && sb[i + 1] == b'{' => match suffix[i..].find('}') {
                    Some(end) => i += end + 1,
                    None => return Err(parse_error(s, pos + patch_end + i)),
                },
                _ => return Err(parse_error(s, pos + patch_end + i)),
            }
        }
        Ok(StGitRevision {
            branch,
            patch_like: patch_like.to_string(),
            suffix: suffix.to_string(),
            raw: s.to_string(),
        })
    }
}

pub struct ResolvedRevision {
    pub oid: Oid,
    pub commit: Option<Rc<Commit>>,
    pub patchname: Option<PatchName>,
    pub is_base: bool,
}

/// Resolve a StGit revision to an object id.
pub fn parse_stgit_revision(
    repo: &Repository,
    spec: Option<&StGitRevision>,
    branch: Option<&str>,
    policy: InitializationPolicy,
) -> Result<(Stack<'_>, ResolvedRevision)> {
    let spec_branch = spec.and_then(|s| s.branch.as_deref());
    let branch_name = spec_branch.or(branch);
    let stack = Stack::from_branch(repo, branch_name, policy)?;
    let Some(spec) = spec else {
        let top = stack.top().clone();
        let pn = stack.applied().last().cloned();
        return Ok((
            stack,
            ResolvedRevision {
                oid: top.id,
                commit: Some(top),
                patchname: pn,
                is_base: false,
            },
        ));
    };

    let base_oid: Option<(Oid, Option<PatchName>, bool)> = if spec.patch_like == "{base}" {
        Some((stack.base.id, None, true))
    } else {
        match PatchName::from_str(&spec.patch_like) {
            Ok(pn) if stack.has_patch(&pn) => {
                Some((stack.get_patch_commit(&pn).id, Some(pn), false))
            }
            _ => None,
        }
    };

    match base_oid {
        Some((oid, pn, is_base)) => {
            if spec.suffix.is_empty() {
                let commit = repo.find_commit(oid).ok();
                return Ok((
                    stack,
                    ResolvedRevision {
                        oid,
                        commit,
                        patchname: pn,
                        is_base,
                    },
                ));
            }
            let full = format!("{oid}{}", spec.suffix);
            let resolved = resolve_git_rev(repo, &full)?;
            let commit = repo.find_commit(resolved).ok();
            let patchname = commit
                .as_ref()
                .and_then(|c| stack.patch_for_commit(c.id).cloned());
            Ok((
                stack,
                ResolvedRevision {
                    oid: resolved,
                    commit,
                    patchname,
                    is_base: false,
                },
            ))
        }
        None => {
            if spec.branch.is_some() {
                return Err(stack.patch_not_found_error(&spec.patch_like));
            }
            let full = format!("{}{}", spec.patch_like, spec.suffix);
            let oid = match repo.rev_parse(&full)? {
                Some(oid) => oid,
                None => {
                    if PatchName::from_str(&spec.patch_like).is_ok() {
                        return Err(stack.patch_not_found_error(&spec.patch_like));
                    }
                    return Err(anyhow!("invalid StGit revision `{}`", spec.raw));
                }
            };
            let commit = repo.find_commit(oid).ok();
            let patchname = commit
                .as_ref()
                .and_then(|c| stack.patch_for_commit(c.id).cloned());
            let is_base = commit.as_ref().map(|c| c.id == stack.base.id).unwrap_or(false);
            Ok((
                stack,
                ResolvedRevision {
                    oid,
                    commit,
                    patchname,
                    is_base,
                },
            ))
        }
    }
}

/// Resolve `<oid><suffix>` using git, producing StGit-style error messages.
fn resolve_git_rev(repo: &Repository, full: &str) -> Result<Oid> {
    match repo.rev_parse(full)? {
        Some(oid) => Ok(oid),
        None => {
            // Produce a more specific error for common failures.
            let (base, suffix) = full.split_at(40);
            let base_oid = Oid::from_hex(base).unwrap();
            if let Some(rest) = suffix.strip_prefix('^') {
                let n: usize = if rest.is_empty() {
                    1
                } else {
                    rest.chars()
                        .take_while(|c| c.is_ascii_digit())
                        .collect::<String>()
                        .parse()
                        .unwrap_or(1)
                };
                if let Ok(commit) = repo.find_commit(base_oid) {
                    let short = repo.abbrev(commit.id, None)?;
                    if rest.starts_with('{') {
                        return Err(anyhow!("invalid StGit revision `{full}`"));
                    }
                    return Err(anyhow!(
                        "invalid StGit revision `{full}`: Commit {short} has {} parents and parent number {n} is out of range",
                        commit.parent_ids.len()
                    ));
                }
            }
            if suffix.starts_with('~') {
                return Err(anyhow!(
                    "finding ancestor: repository does not have enough commit depth"
                ));
            }
            if suffix.starts_with("@{") {
                return Err(anyhow!(
                    "invalid StGit revision `{full}`: Reflog entries require a ref name, got \"{base}\""
                ));
            }
            Err(anyhow!("invalid StGit revision `{full}`"))
        }
    }
}

pub fn revision_arg() -> Arg {
    Arg::new("stgit-revision")
        .value_name("revision")
        .help("StGit revision")
        .value_parser(clap::value_parser!(StGitRevision))
}
EOF
