pub fn print_warning(msg: &str, color_choice: ColorChoice) {
    let mut stderr = crate::color::stderr(color_choice);
    let mut spec = ColorSpec::new();
    spec.set_bold(true).set_fg(Some(Color::Yellow));
    let _ = stderr.set_color(&spec);
    let _ = write!(stderr, "warning: ");
    let _ = stderr.reset();
    let _ = writeln!(stderr, "{msg}");
}

/// Check that the index and work tree are clean relative to the stack top.
pub fn check_index_and_worktree_clean(stack: &Stack) -> Result<()> {
    let stupid = stack.repo.stupid();
    let top_tree = stack.top().tree_id;
    let index_dirty = stupid.index_differs_from_tree(top_tree)?;
    let worktree_dirty = stupid.worktree_differs_from_index()?;
    match (index_dirty, worktree_dirty) {
        (true, true) => Err(anyhow::anyhow!(
            "index and worktree not clean; use `refresh` or `reset --hard`"
        )),
        (true, false) => Err(anyhow::anyhow!(
            "index not clean; use `refresh` or `reset --hard`"
        )),
        (false, true) => Err(anyhow::anyhow!(
            "worktree not clean; use `refresh` or `reset --hard`"
        )),
        (false, false) => Ok(()),
    }
}

/// Check that there are no outstanding conflicts in the index.
pub fn check_no_conflicts(stack: &Stack) -> Result<()> {
    let stupid = stack.repo.stupid();
    if !stupid.conflict_paths()?.is_empty() {
        Err(anyhow::anyhow!("resolve outstanding conflicts first"))
    } else {
        Ok(())
    }
}

/// Check that the repository is in a normal state (no in-progress operations).
pub fn check_repository_state(stack: &Stack) -> Result<()> {
    let git_dir = &stack.repo.git_dir;
    let checks: &[(&str, &str)] = &[
        ("MERGE_HEAD", "merge"),
        ("rebase-merge", "rebase"),
        ("rebase-apply", "rebase"),
        ("CHERRY_PICK_HEAD", "cherry-pick"),
        ("BISECT_LOG", "bisect"),
        ("REVERT_HEAD", "revert"),
    ];
    for (file, op) in checks {
        if git_dir.join(file).exists() {
            return Err(anyhow::anyhow!(
                "complete the in-progress `{op}` before trying again"
            ));
        }
    }
    Ok(())
}

/// Describe a list of patch names: "`a`", "`a` and `b`", "`a`, `b` and `c`".
pub fn join_patch_names(names: &[&PatchName]) -> String {
    match names.len() {
        0 => String::new(),
        1 => format!("`{}`", names[0]),
        n => {
            let head: Vec<String> = names[..n - 1].iter().map(|p| format!("`{p}`")).collect();
            format!("{} and `{}`", head.join(", "), names[n - 1])
        }
    }
}

/// Get the editor command from config/environment.
pub fn get_editor(config: &crate::config::Config) -> String {
    if let Ok(e) = std::env::var("GIT_EDITOR") {
        if !e.is_empty() {
            return e;
        }
    }
    if let Some(e) = config.get("stgit.editor") {
        if !e.is_empty() {
            return e.to_string();
        }
    }
    if let Some(e) = config.get("core.editor") {
        if !e.is_empty() {
            return e.to_string();
        }
    }
    if let Ok(e) = std::env::var("VISUAL") {
        if !e.is_empty() {
            return e;
        }
    }
    if let Ok(e) = std::env::var("EDITOR") {
        if !e.is_empty() {
            return e;
        }
    }
    "vi".to_string()
}

/// Run the editor on the given file.
pub fn run_editor(config: &crate::config::Config, path: &std::path::Path) -> Result<()> {
    let editor = get_editor(config);
    let status = std::process::Command::new("sh")
        .arg("-c")
        .arg(format!("{editor} \"$@\""))
        .arg(&editor)
        .arg(path)
        .stdin(std::process::Stdio::inherit())
        .stdout(std::process::Stdio::inherit())
        .stderr(std::process::Stdio::inherit())
        .status()?;
    if !status.success() {
        return Err(anyhow::anyhow!(
            "problem with the editor `{editor}`"
        ));
    }
    Ok(())
}
