#[derive(Clone, Copy, PartialEq, Eq)]
enum Status {
    Top,
    Applied,
    Unapplied,
    Hidden,
}

fn run(matches: &ArgMatches, color: ColorChoice) -> Result<()> {
    let repo = Repository::open()?;
    let branch = matches.get_one::<String>("branch").map(|s| s.as_str());
    let stack = Stack::from_branch(&repo, branch, InitializationPolicy::AllowUninitialized)?;

    let opt_all = matches.get_flag("all");
    let opt_applied = matches.get_flag("applied");
    let opt_unapplied = matches.get_flag("unapplied");
    let opt_hidden = matches.get_flag("hidden");
    let opt_missing = matches.get_one::<String>("missing");
    let opt_short = matches.get_one::<String>("short");

    // Determine patches to show, as (name, status, commit).
    let ranges = get_ranges(matches, "patchranges");

    // For --missing, the patches come from the other branch.
    let (ref_stack, cmp_stack): (Stack, Option<Stack>) = if let Some(missing_branch) = opt_missing {
        let other = Stack::from_branch(&repo, Some(missing_branch), InitializationPolicy::AllowUninitialized)?;
        (other, Some(stack))
    } else {
        (stack, None)
    };
    let stack = &ref_stack;

    let status_of = |pn: &PatchName| -> Status {
        if stack.applied().last() == Some(pn) {
            Status::Top
        } else if stack.is_applied(pn) {
            Status::Applied
        } else if stack.is_unapplied(pn) {
            Status::Unapplied
        } else {
            Status::Hidden
        }
    };

    let mut patches: Vec<PatchName> = if !ranges.is_empty() {
        parse_patch_ranges(&ranges, stack, RangeConstraint::AllContiguous)?
    } else if opt_short.is_some() {
        let n: usize = match opt_short.map(|s| s.as_str()) {
            Some("") | None => repo
                .config
                .get_i64("stgit.shortnr")
                .map(|n| n.max(0) as usize)
                .unwrap_or(5),
            Some(s) => s
                .parse()
                .map_err(|_| anyhow!("invalid value for --short: `{s}`"))?,
        };
        let applied = stack.applied();
        let unapplied = stack.unapplied();
        let mut v: Vec<PatchName> = Vec::new();
        if applied.is_empty() {
            v.extend(unapplied.iter().take(n).cloned());
        } else {
            let start = applied.len().saturating_sub(n + 1);
            v.extend(applied[start..].iter().cloned());
            v.extend(unapplied.iter().take(n).cloned());
        }
        v
    } else if opt_all {
        stack.all_patches().cloned().collect()
    } else if opt_applied || opt_unapplied || opt_hidden {
        let mut v = Vec::new();
        if opt_applied {
            v.extend(stack.applied().iter().cloned());
        }
        if opt_unapplied {
            v.extend(stack.unapplied().iter().cloned());
        }
