                .help("Add Acked-by message trailer")
                .long_help(
                    "Add \"Acked-by\" message trailer.\n\
                     \n\
                     The value is optional and defaults to the committer's name and email. This \
                     option may be provided multiple times.",
                )
                .value_name("value")
                .num_args(0..=1)
                .default_missing_value("")
                .require_equals(true)
                .action(ArgAction::Append),
        )
        .arg(
            Arg::new("review")
                .long("review")
                .help("Add Reviewed-by message trailer")
                .long_help(
                    "Add \"Reviewed-by\" message trailer.\n\
                     \n\
                     The value is optional and defaults to the committer's name and email. This \
                     option may be provided multiple times.",
                )
                .value_name("value")
                .num_args(0..=1)
                .default_missing_value("")
                .require_equals(true)
                .action(ArgAction::Append),
        )
        .arg(
            Arg::new("author")
                .long("author")
                .help("Set the author \"name <email>\"")
                .value_name("name-and-email")
                .value_parser(parse_name_email_arg)
                .conflicts_with_all(["authname", "authemail"]),
        )
        .arg(
            Arg::new("authname")
                .long("authname")
                .help("Set the author name")
                .value_name("name")
                .value_parser(clap::value_parser!(String)),
        )
        .arg(
            Arg::new("authemail")
                .long("authemail")
                .help("Set the author email")
                .value_name("email")
                .value_parser(clap::value_parser!(String)),
        )
        .arg(
            Arg::new("authdate")
                .long("authdate")
                .help("Set the author date")
                .long_help(
                    "Set the date the patch was authored.\n\
                     \n\
                     Use \"now\" to use the current time and date.",
                )
                .value_name("date")
                .value_parser(parse_authdate_arg),
        )
        .arg(crate::argset::committer_date_is_author_date_arg());
    if add_save_template {
        command.arg(
            Arg::new("save-template")
                .long("save-template")
                .help("Save the patch description to FILE and exit")
                .long_help(
                    "Instead of running the command, just write the patch description to FILE, \
                     and exit. (If FILE is \"-\", write to stdout.)\n\
                     \n\
                     When driving StGit from another program, it may be useful to first call a \
                     command with '--save-template', then let the user edit the message, and \
                     then call the same command with '--file'.",
                )
                .value_name("file")
                .value_hint(ValueHint::FilePath)
                .value_parser(clap::value_parser!(PathBuf))
                .conflicts_with_all(["message", "file"]),
        )
    } else {
        command
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct NameEmail(pub String, pub String);

fn parse_name_email_arg(s: &str) -> Result<NameEmail, String> {
    Signature::parse_name_email(s)
        .map(|(n, e)| NameEmail(n.to_str_lossy().into_owned(), e.to_str_lossy().into_owned()))
        .map_err(|e| e.to_string())
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct AuthDate(pub Time);

fn parse_authdate_arg(s: &str) -> Result<AuthDate, String> {
    if s == "now" {
        return Ok(AuthDate(Time::now()));
    }
    Time::parse(s).map(AuthDate).map_err(|e| e.to_string())
}

/// A patch description as used in the edit template.
#[derive(Debug, Clone)]
pub struct PatchDescription {
    pub patchname: Option<PatchName>,
    pub author: Option<Signature>,
    pub message: String,
    pub diff: Option<Vec<u8>>,
}

const INSTRUCTION: &str = "# Please enter the message for your patch. Lines starting with\n\
                           # '#' will be ignored. An empty message aborts the new patch.\n\
                           # The patch name and author information may also be modified.\n";

impl PatchDescription {
    pub fn write(&self, out: &mut dyn Write, diff_instruction: Option<&str>) -> Result<()> {
        writeln!(
            out,
            "Patch:  {}",
            self.patchname.as_ref().map(|p| p.to_string()).unwrap_or_default()
        )?;
        if let Some(author) = &self.author {
            writeln!(out, "Author: {}", author.name_email())?;
            writeln!(out, "Date:   {}", author.time.to_iso())?;
        }
        writeln!(out)?;
        let msg = self.message.trim_end_matches('\n');
        writeln!(out, "{msg}")?;
        writeln!(out)?;
        out.write_all(INSTRUCTION.as_bytes())?;
        if let Some(diff) = &self.diff {
            if let Some(instr) = diff_instruction {
                out.write_all(instr.as_bytes())?;
            }
            out.write_all(b"# ------------------------ >8 ------------------------\n")?;
            out.write_all(b"# Do not modify or remove the line above.\n")?;
            out.write_all(diff)?;
        }
        Ok(())
    }

    pub fn parse(data: &[u8]) -> Result<PatchDescription> {
        // Split off the diff.
        let scissors = b"# ------------------------ >8 ------------------------\n";
        let (headers_and_msg, diff) = match data.find(scissors) {
            Some(pos) => {
                let after = &data[pos + scissors.len()..];
                let marker = b"# Do not modify or remove the line above.\n";
                let diff = if after.starts_with(marker) {
                    &after[marker.len()..]
                } else {
                    after
                };
                (&data[..pos], Some(diff.to_vec()))
            }
            None => (data, None),
        };
        let text = headers_and_msg.to_str_lossy();
        let mut patchname = None;
        let mut author_name: Option<String> = None;
        let mut author_email: Option<String> = None;
        let mut author_time: Option<Time> = None;
        let mut lines = text.lines();
        let mut message_lines: Vec<&str> = Vec::new();
        let mut in_headers = true;
        let mut pending: Vec<&str> = Vec::new();
        for line in lines.by_ref() {
            if in_headers {
                if let Some(v) = line.strip_prefix("Patch:") {
                    let v = v.trim();
                    patchname = if v.is_empty() {
                        None
                    } else {
                        Some(parse_patchname_arg(v)?)
                    };
                    continue;
                } else if let Some(v) = line.strip_prefix("Author:") {
                    let v = v.trim();
                    let (n, e) = Signature::parse_name_email(v)?;
                    author_name = Some(n.to_str_lossy().into_owned());
                    author_email = Some(e.to_str_lossy().into_owned());
                    continue;
                } else if let Some(v) = line.strip_prefix("Date:") {
                    let v = v.trim();
                    author_time = Some(Time::parse(v)?);
                    continue;
                } else if line.trim().is_empty() && message_lines.is_empty() && pending.is_empty() {
                    in_headers = false;
                    continue;
                } else {
                    in_headers = false;
                }
            }
            pending.push(line);
            message_lines.append(&mut pending);
        }
        let message_text: String = message_lines
            .iter()
            .filter(|l| !l.starts_with('#'))
            .map(|l| format!("{l}\n"))
            .collect();
        let message = normalize_message(&message_text);
        let author = match (author_name, author_email) {
            (Some(n), Some(e)) => Some(Signature::new(n, e, author_time.unwrap_or_else(Time::now))),
            _ => None,
        };
        Ok(PatchDescription {
            patchname,
            author,
            message,
            diff,
        })
    }
}

/// Normalize a commit message similar to `git stripspace`: trim trailing
/// whitespace on lines, collapse blank lines, strip leading/trailing blank lines,
/// and ensure a trailing newline (or empty string).
pub fn normalize_message(msg: &str) -> String {
    let mut out = String::new();
    let mut blank_pending = false;
    let mut started = false;
    for line in msg.lines() {
        let line = line.trim_end();
        if line.is_empty() {
            if started {
                blank_pending = true;
            }
            continue;
        }
        if blank_pending {
            out.push('\n');
            blank_pending = false;
        }
        started = true;
        out.push_str(line);
        out.push('\n');
    }
    out
}

/// Add trailers to a message using `git interpret-trailers`.
pub fn add_trailers(repo: &Repository, message: &str, trailers: &[(String, String)]) -> Result<String> {
    if trailers.is_empty() {
        return Ok(message.to_string());
    }
    let mut args: Vec<String> = vec!["interpret-trailers".to_string()];
    for (key, value) in trailers {
        args.push("--trailer".to_string());
        args.push(format!("{key}: {value}"));
    }
    let out = repo.git_output_with_input(&args, message.as_bytes())?;
    if !out.success() {
        return Err(anyhow!("`git interpret-trailers`: {}", out.stderr_str().trim()));
    }
    Ok(out.stdout_str())
}

pub struct EditOptions {
    pub edit: bool,
    pub diff: bool,
    pub message: Option<String>,
    pub file: Option<PathBuf>,
    pub no_verify: bool,
    pub trailers: Vec<(String, String)>,
    pub author: Option<NameEmail>,
    pub authname: Option<String>,
    pub authemail: Option<String>,
    pub authdate: Option<Time>,
    pub committer_date_is_author_date: bool,
    pub save_template: Option<PathBuf>,
}

impl EditOptions {
    pub fn from_matches(matches: &ArgMatches, config: &crate::config::Config) -> Result<EditOptions> {
        let committer = Signature::default_committer(config).ok();
        let default_ident = committer.map(|c| c.name_email());
        let mut trailers: Vec<(String, String)> = Vec::new();
        // Preserve command-line order of trailer options.
        let mut indexed: Vec<(usize, String, String)> = Vec::new();
        for (id, key) in [("signoff", "Signed-off-by"), ("ack", "Acked-by"), ("review", "Reviewed-by")] {
            if let (Some(values), Some(indices)) = (
                matches.get_many::<String>(id),
                matches.indices_of(id),
            ) {
                for (value, index) in values.zip(indices) {
                    let v = if value.is_empty() {
                        match &default_ident {
                            Some(d) => d.clone(),
                            None => {
                                return Err(anyhow!(
                                    "committer identity unknown; please configure `user.name` and `user.email`."
                                ))
                            }
                        }
                    } else {
                        value.clone()
                    };
                    indexed.push((index, key.to_string(), v));
                }
            }
        }
        indexed.sort_by_key(|(i, _, _)| *i);
        for (_, k, v) in indexed {
            trailers.push((k, v));
        }
        Ok(EditOptions {
            edit: matches.get_flag("edit"),
            diff: matches.get_flag("diff"),
            message: matches.try_get_one::<String>("message").ok().flatten().cloned(),
            file: matches.try_get_one::<PathBuf>("file").ok().flatten().cloned(),
            no_verify: matches.get_flag("no-verify"),
            trailers,
            author: matches.get_one::<NameEmail>("author").cloned(),
            authname: matches.get_one::<String>("authname").cloned(),
            authemail: matches.get_one::<String>("authemail").cloned(),
            authdate: matches.get_one::<AuthDate>("authdate").map(|d| d.0),
            committer_date_is_author_date: matches.get_flag("committer-date-is-author-date"),
            save_template: matches.try_get_one::<PathBuf>("save-template").ok().flatten().cloned(),
        })
    }

    /// Message from --message or --file, if any.
    pub fn given_message(&self) -> Result<Option<String>> {
        if let Some(m) = &self.message {
            return Ok(Some(m.clone()));
        }
        if let Some(path) = &self.file {
            let data = if path.as_os_str() == "-" {
                let mut buf = Vec::new();
                std::io::stdin().read_to_end(&mut buf)?;
                buf
            } else {
                std::fs::read(path).map_err(|e| anyhow!("{e}"))?
            };
            return Ok(Some(String::from_utf8_lossy(&data).into_owned()));
        }
        Ok(None)
    }

    /// Apply author overrides to the given author signature.
    pub fn apply_author(&self, author: &Signature) -> Signature {
        let mut author = author.clone();
        if let Some(NameEmail(n, e)) = &self.author {
            author.name = BString::from(n.as_str());
            author.email = BString::from(e.as_str());
        }
        if let Some(n) = &self.authname {
            author.name = BString::from(n.as_str());
        }
        if let Some(e) = &self.authemail {
            author.email = BString::from(e.as_str());
        }
        if let Some(d) = &self.authdate {
            author.time = *d;
        }
        author
    }
}

pub enum EditOutcome {
    TemplateSaved,
    Edited {
        patchname: Option<PatchName>,
        author: Signature,
        message: String,
        diff: Option<Vec<u8>>,
    },
}

/// Run the editing process.
///
/// `original_message` is the starting message; `default_patchname` is the
/// name shown in the template; `diff` is shown when --diff is given.
pub fn edit_description(
    repo: &Repository,
    opts: &EditOptions,
    default_patchname: Option<&PatchName>,
    original_author: &Signature,
    original_message: &str,
    diff: Option<&[u8]>,
    diff_instruction: &str,
    force_interactive: bool,
    allow_template_file: bool,
    color: crate::color::ColorChoice,
) -> Result<EditOutcome> {
    let given = opts.given_message()?;
    let mut message = match &given {
        Some(m) => m.clone(),
        None => {
            if original_message.is_empty() && allow_template_file {
                read_template_file(repo).unwrap_or_default()
            } else {
                original_message.to_string()
            }
        }
    };
    message = normalize_message(&message);
    if !opts.trailers.is_empty() {
        message = add_trailers(repo, &message, &opts.trailers)?;
    }
    let author = opts.apply_author(original_author);

    let need_interactive = force_interactive || opts.edit || (given.is_none() && opts.save_template.is_none() && false);
    let description = PatchDescription {
        patchname: default_patchname.cloned(),
        author: Some(author.clone()),
        message: message.clone(),
        diff: if opts.diff || opts.save_template.is_some() && opts.diff {
            diff.map(|d| d.to_vec())
        } else {
            None
        },
    };

    if let Some(path) = &opts.save_template {
        let mut buf = Vec::new();
        description.write(&mut buf, Some(diff_instruction))?;
        if path.as_os_str() == "-" {
            std::io::stdout().write_all(&buf)?;
        } else {
            std::fs::write(path, &buf).with_context(|| format!("writing {}", path.display()))?;
        }
        return Ok(EditOutcome::TemplateSaved);
    }

    let (patchname, author, message, diff) = if need_interactive {
        let edited = run_interactive_edit(repo, &description, diff_instruction, color)?;
        let pn = edited.patchname;
        let author = edited.author.map(|a| {
            // keep time from edited if provided, else original
            a
        }).unwrap_or(author);
        (pn, author, edited.message, edited.diff)
    } else {
        (default_patchname.cloned(), author, message, None)
    };

    let message = if opts.no_verify {
        message
    } else {
        run_commit_msg_hook(repo, &message)?
    };

    Ok(EditOutcome::Edited {
        patchname,
        author,
        message,
        diff,
    })
}

fn read_template_file(repo: &Repository) -> Option<String> {
    let candidates = [
        repo.git_dir.join("patchdescr.tmpl"),
        dirs_config_home().join("stgit").join("templates").join("patchdescr.tmpl"),
        home_dir().join(".stgit").join("templates").join("patchdescr.tmpl"),
    ];
    for path in candidates {
        if let Ok(s) = std::fs::read_to_string(&path) {
            return Some(s);
        }
    }
    None
}

fn home_dir() -> PathBuf {
    std::env::var_os("HOME").map(PathBuf::from).unwrap_or_default()
}

fn dirs_config_home() -> PathBuf {
    match std::env::var_os("XDG_CONFIG_HOME") {
        Some(p) if !p.is_empty() => PathBuf::from(p),
        _ => home_dir().join(".config"),
    }
}

fn run_interactive_edit(
    repo: &Repository,
    description: &PatchDescription,
    diff_instruction: &str,
    _color: crate::color::ColorChoice,
) -> Result<PatchDescription> {
    let workdir = repo.workdir().unwrap_or(Path::new("."));
    let path = workdir.join(EDIT_FILE_NAME);
    {
        let mut file = std::fs::File::create(&path)
            .with_context(|| format!("creating {}", path.display()))?;
        description.write(&mut file, Some(diff_instruction))?;
    }
    eprintln!("hint: Waiting for your editor to close the file...");
    let editor = crate::util::get_editor(&repo.config);
    let status = std::process::Command::new("sh")
        .arg("-c")
        .arg(format!("{editor} \"$@\""))
        .arg(&editor)
        .arg(EDIT_FILE_NAME)
        .current_dir(workdir)
        .stdin(std::process::Stdio::inherit())
        .stdout(std::process::Stdio::inherit())
        .stderr(std::process::Stdio::inherit())
        .status();
    let status = match status {
        Ok(s) => s,
        Err(e) => return Err(anyhow!("running editor: {editor}: {e}")),
    };
    if editor.is_empty() {
        return Err(anyhow!(
            "running editor: : No such file or directory (os error 2)"
        ));
    }
    if !status.success() {
        return Err(anyhow!(
            "problem with the editor `{editor}`"
        ));
    }
    let data = std::fs::read(&path)?;
    let mut parsed = PatchDescription::parse(&data)?;
    let _ = std::fs::remove_file(&path);
    // Only keep the diff if it differs from the original.
    if let (Some(new_diff), Some(old_diff)) = (&parsed.diff, &description.diff) {
        if new_diff == old_diff {
            parsed.diff = None;
        }
    }
    Ok(parsed)
}

/// Run the commit-msg hook if present; returns the possibly modified message.
pub fn run_commit_msg_hook(repo: &Repository, message: &str) -> Result<String> {
    let hooks_dir = match repo.config.get("core.hookspath") {
        Some(p) => PathBuf::from(p),
        None => repo.git_dir.join("hooks"),
    };
    let hook = hooks_dir.join("commit-msg");
    if !hook.exists() {
        return Ok(message.to_string());
    }
    let is_exec = std::fs::metadata(&hook)
        .map(|m| {
            use std::os::unix::fs::PermissionsExt;
            m.permissions().mode() & 0o111 != 0
        })
        .unwrap_or(false);
    if !is_exec {
        return Ok(message.to_string());
    }
    let tmp = repo.git_dir.join("COMMIT_EDITMSG"); // mimic git: use a temp file
    let tmp_path = repo.git_dir.join(".stgit-commit-msg.txt");
    let _ = tmp;
    std::fs::write(&tmp_path, message)?;
    let status = std::process::Command::new(&hook)
        .arg(&tmp_path)
        .current_dir(repo.workdir().unwrap_or(Path::new(".")))
        .env("GIT_DIR", &repo.git_dir)
        .stdin(std::process::Stdio::inherit())
        .stdout(std::process::Stdio::inherit())
        .stderr(std::process::Stdio::inherit())
        .status()?;
    let result = if status.success() {
        Ok(std::fs::read_to_string(&tmp_path)?)
    } else {
        Err(anyhow!("`commit-msg` hook returned {}", status.code().unwrap_or(1)))
    };
    let _ = std::fs::remove_file(&tmp_path);
    result
}

/// Diff of a patch commit against its parent, for the edit template.
pub fn patch_diff(repo: &Repository, commit: &Commit) -> Result<Vec<u8>> {
    let parent_tree = match commit.parent_ids.first() {
        Some(p) => repo.find_commit(*p)?.tree_id,
        None => return Ok(Vec::new()),
    };
    let stupid = repo.stupid();
    stupid.diff_tree_patch(parent_tree, commit.tree_id, None::<Vec<&str>>, true, &[])
}

/// Diff between a tree and the work tree/index state (for `new -d`).
pub fn worktree_diff(repo: &Repository, tree_id: Oid) -> Result<Vec<u8>> {
    let out = repo.git_output(["diff-index", "-p", "--full-index", "--binary", &tree_id.to_hex()])?;
    Ok(out.stdout)
}

/// Create a commit for an edited patch.
pub fn commit_edited(
    trans: &StackTransaction,
    author: &Signature,
    message: &str,
    tree_id: Oid,
    parent_ids: &[Oid],
) -> Result<std::rc::Rc<Commit>> {
    trans.commit_patch(author, message.as_bytes(), tree_id, parent_ids)
}
