pub struct RefreshOptions {
    pub update: bool,
    pub use_index: bool,
    pub force: bool,
    pub patchname: Option<PatchName>,
    pub annotate: Option<String>,
    pub pathspecs: Vec<String>,
    pub submodules: bool,
    pub no_submodules: bool,
    pub edit: Option<EditOptions>,
    pub committer_date_is_author_date: bool,
    pub allow_push_conflicts: bool,
}

fn run(matches: &ArgMatches, color: ColorChoice) -> Result<()> {
    let repo = Repository::open()?;
    let edit = EditOptions::from_matches(matches, &repo.config)?;
    let cdiad = edit.committer_date_is_author_date;
    let pathspecs: Vec<String> = matches
        .get_many::<std::ffi::OsString>("pathspecs")
        .map(|v| v.map(|p| p.to_string_lossy().into_owned()).collect())
        .unwrap_or_default();
    let patchname = match matches.get_one::<PatchLocator>("patch") {
        Some(loc) => {
            let stack = Stack::from_branch(&repo, None, InitializationPolicy::AllowUninitialized)?;
            Some(crate::patch::range::resolve_single(loc, &stack, true)?)
        }
        None => None,
    };
    let allow_push_conflicts = match matches.get_one::<String>("conflicts").map(|s| s.as_str()) {
        Some("disallow") => false,
        Some(_) => true,
        None => repo
            .config
            .get_bool("stgit.push.allow-conflicts")
            .unwrap_or(true),
    };
    refresh_patch(
        &repo,
        color,
        RefreshOptions {
            update: matches.get_flag("update"),
            use_index: matches.get_flag("index"),
            force: matches.get_flag("force"),
            patchname,
            annotate: matches.get_one::<String>("annotate").cloned(),
            pathspecs,
            submodules: matches.get_flag("submodules"),
            no_submodules: matches.get_flag("no-submodules"),
            edit: Some(edit),
            committer_date_is_author_date: cdiad,
            allow_push_conflicts,
        },
    )
}

/// Compute the tree for the refresh from the work tree/index.
fn make_refresh_tree(
    repo: &Repository,
    stack: &Stack,
    opts: &RefreshOptions,
    patch_commit: &Commit,
) -> Result<Oid> {
    let stupid = repo.stupid();
    let head_tree = stack.branch_head.tree_id;
    if opts.use_index {
        return stupid.write_tree();
    }

    let index_dirty = stupid.index_differs_from_tree(head_tree)?;
    let worktree_dirty = stupid.worktree_differs_from_index()?;
    if index_dirty && worktree_dirty && !opts.force {
        return Err(anyhow!(
            "the index is dirty; consider using `--index` or `--force`"
        ));
    }

    let is_path_limiting = opts.update || !opts.pathspecs.is_empty();

    // Determine the paths to update.
    let mut paths: Vec<String> = Vec::new();
    if opts.update {
        // Files in the patch.
        let parent_tree = match patch_commit.parent_ids.first() {
            Some(p) => repo.find_commit(*p)?.tree_id,
            None => patch_commit.tree_id,
        };
        let files = stupid.diff_tree_files(parent_tree, patch_commit.tree_id)?;
        let workdir = repo.workdir().unwrap();
        let cwd = std::env::current_dir()?;
        let prefix = cwd.strip_prefix(workdir).unwrap_or(std::path::Path::new(""));
        for f in files {
            let f = f.to_string();
            // Make path relative to cwd for git add
            let rel = if prefix.as_os_str().is_empty() {
                f
            } else {
                match std::path::Path::new(&f).strip_prefix(prefix) {
                    Ok(r) => r.to_string_lossy().into_owned(),
                    Err(_) => format!(
                        "{}/{}",
                        pathdiff_to_root(prefix),
                        f
                    ),
                }
            };
            paths.push(rel);
        }
        if paths.is_empty() {
            return Ok(head_tree_with_index(repo, head_tree, &stupid)?);
        }
    } else {
        paths = opts.pathspecs.clone();
    }

    if is_path_limiting {
        // Update only the limited paths in the real index, then build the tree
        // from HEAD plus those paths.
        let result = stupid.with_temp_index(|temp| {
            temp.read_tree(head_tree)?;
            // Copy the index entries for the paths (staged changes), then worktree.
            let mut args: Vec<String> = vec!["add".into(), "-u".into(), "--".into()];
            args.extend(paths.iter().cloned());
            let mut cmd = temp.git_command();
            cmd.args(&args);
            cmd.current_dir(std::env::current_dir()?);
            cmd.stdout(std::process::Stdio::piped())
                .stderr(std::process::Stdio::piped());
            let out = cmd.output()?;
            if !out.status.success() {
                return Err(anyhow!(
                    "`git add`: {}",
                    crate::stupid::clean_git_stderr(&String::from_utf8_lossy(&out.stderr))
                ));
            }
            temp.write_tree()
        })?;
        // Also apply the staged index changes for those paths.
        let tree = apply_staged_for_paths(repo, result, &paths)?;
        // Update the real index for those paths too.
        let mut args: Vec<String> = vec!["add".into(), "-u".into(), "--".into()];
        args.extend(paths.iter().cloned());
        let mut cmd = repo.git_command();
        cmd.args(&args);
        cmd.current_dir(std::env::current_dir()?);
        cmd.stdout(std::process::Stdio::null())
            .stderr(std::process::Stdio::null());
        let _ = cmd.status();
        Ok(tree)
    } else {
        let mut cmd = repo.git_command();
        cmd.args(["add", "-u", "--", "."]);
        if let Some(wd) = repo.workdir() {
            cmd.current_dir(wd);
        }
        cmd.stdout(std::process::Stdio::piped())
            .stderr(std::process::Stdio::piped());
        let out = cmd.output()?;
        if !out.status.success() {
            return Err(anyhow!(
                "`git add`: {}",
                crate::stupid::clean_git_stderr(&String::from_utf8_lossy(&out.stderr))
            ));
        }
        stupid.write_tree()
    }
}

fn pathdiff_to_root(prefix: &std::path::Path) -> String {
    let n = prefix.components().count();
    let parts: Vec<&str> = (0..n).map(|_| "..").collect();
    parts.join("/")
}

fn head_tree_with_index(_repo: &Repository, head_tree: Oid, _stupid: &crate::stupid::Stupid) -> Result<Oid> {
    Ok(head_tree)
}

/// For path-limited refresh: the temp-index approach above only captured work
/// tree changes relative to HEAD for tracked paths. Staged changes (e.g. new
/// files) for those paths must be taken from the real index.
fn apply_staged_for_paths(repo: &Repository, tree: Oid, paths: &[String]) -> Result<Oid> {
    let stupid = repo.stupid();
    // Build list of index entries for the paths and add them into a temp index
    // based on `tree`.
    let mut args: Vec<String> = vec!["ls-files".into(), "-s".into(), "-z".into(), "--".into()];
    args.extend(paths.iter().cloned());
    let mut cmd = repo.git_command();
    cmd.args(&args);
    cmd.current_dir(std::env::current_dir()?);
    cmd.stdout(std::process::Stdio::piped())
        .stderr(std::process::Stdio::null());
    let out = cmd.output()?;
    if out.stdout.is_empty() {
        return Ok(tree);
    }
    // Determine which of these entries differ from HEAD's tree (i.e., staged new files)
    let head_tree = tree;
    let entries: Vec<&[u8]> = out.stdout.split(|b| *b == 0).filter(|e| !e.is_empty()).collect();
    let mut index_info: Vec<u8> = Vec::new();
    for e in entries {
        // format: <mode> <oid> <stage>\t<path>
        let Some(tab) = e.iter().position(|b| *b == b'\t') else { continue };
        let meta = String::from_utf8_lossy(&e[..tab]).into_owned();
        let path = &e[tab + 1..];
        let parts: Vec<&str> = meta.split(' ').collect();
        if parts.len() != 3 || parts[2] != "0" {
            continue;
        }
        // Does this path exist in the tree with the same oid?
        let spec = format!("{}:{}", head_tree, String::from_utf8_lossy(path));
        let existing = repo.rev_parse(&spec)?;
        let oid = Oid::from_hex(parts[1]);
        if existing == oid {
            continue;
        }
        // Only add if the file is not already tracked in tree (new file) -- for
        // tracked files the worktree content was already taken.
        if existing.is_some() {
            continue;
        }
        index_info.extend_from_slice(format!("{} {} 0\t", parts[0], parts[1]).as_bytes());
        index_info.extend_from_slice(path);
        index_info.push(0);
    }
    if index_info.is_empty() {
        return Ok(tree);
    }
    stupid.with_temp_index(|temp| {
        temp.read_tree(tree)?;
        let mut cmd = temp.git_command();
        cmd.args(["update-index", "-z", "--index-info"]);
        cmd.stdin(std::process::Stdio::piped())
            .stdout(std::process::Stdio::null())
            .stderr(std::process::Stdio::null());
        let mut child = cmd.spawn()?;
        {
            use std::io::Write;
            let mut stdin = child.stdin.take().unwrap();
            let _ = stdin.write_all(&index_info);
        }
        let _ = child.wait()?;
        temp.write_tree()
    })
}

pub fn refresh_patch(repo: &Repository, color: ColorChoice, opts: RefreshOptions) -> Result<()> {
    let stack = Stack::from_branch(repo, None, InitializationPolicy::AllowUninitialized)?;
    crate::util::check_no_conflicts(&stack)?;
    stack.check_head_top_mismatch()?;

    let patchname = match &opts.patchname {
        Some(pn) => pn.clone(),
        None => stack
            .applied()
            .last()
            .cloned()
            .ok_or_else(|| anyhow!("no patches applied"))?,
    };
    let patch_commit = stack.get_patch_commit(&patchname).clone();

    let tree_id = make_refresh_tree(repo, &stack, &opts, &patch_commit)?;

    // Temporary patch name
    let temp_name = PatchName::make("refresh-temp", false, None)
        .uniquify(|pn| stack.collides(pn).is_some());

    let author = Signature::default_author(&repo.config)?;
    let temp_message = format!("Refresh of {patchname}");
    let cdiad = opts.committer_date_is_author_date;

    // Transaction 1: create temporary patch.
    let stack = TransactionBuilder::new(stack, color)
        .use_index_and_worktree(true)
        .committer_date_is_author_date(cdiad)
        .transact(|trans| {
            trans.set_reflog_msg(&format!("refresh {temp_name} (create temporary patch)"));
            let parent = trans.top();
            let commit = trans.commit_patch(&author, temp_message.as_bytes(), tree_id, &[parent.id])?;
            trans.new_applied(&temp_name, commit)
        })?;

    // Possibly edit the patch description.
    let (new_author, new_message) = match &opts.edit {
        Some(edit) => {
            let diff = if edit.diff {
                Some(patchedit::patch_diff(repo, &patch_commit)?)
            } else {
                None
            };
            let outcome = patchedit::edit_description(
                repo,
                edit,
                Some(&patchname),
                &patch_commit.author,
                &patch_commit.message_str(),
                diff.as_deref(),
                "# The diff below may be edited.\n",
                edit.edit,
                false,
                color,
            )?;
            match outcome {
                EditOutcome::TemplateSaved => return Ok(()),
                EditOutcome::Edited {
                    author, message, ..
                } => (author, message),
            }
        }
        None => (
            patch_commit.author.clone(),
            patch_commit.message_str().into_owned(),
        ),
    };

    // Transaction 2: absorb the temporary patch into the target patch.
    let target_is_applied = stack.is_applied(&patchname);
    let log_msg_note = opts.annotate.clone();
    let mut updated: Vec<PatchName> = Vec::new();
    let mut failed_absorb = false;
    let allow_push_conflicts = opts.allow_push_conflicts;
    let result = TransactionBuilder::new(stack, color)
        .use_index_and_worktree(true)
        .allow_conflicts(true)
        .committer_date_is_author_date(cdiad)
        .allow_push_conflicts(allow_push_conflicts)
        .transact(|trans| {
            if !target_is_applied {
                trans.pop_patches(|pn| pn == &temp_name)?;
                failed_absorb = true;
                return Ok(());
            }
            // Pop temp and everything above the target.
            let popped = trans.pop_patches(|pn| pn == &patchname || pn == &temp_name)?;
            // popped contains incidental patches (above target, not temp/target).
            // Now the target was popped too (since pop_patches pops from the lowest
            // match). Re-push target first.
            let mut to_push_back: Vec<PatchName> = Vec::new();
            // Determine what got popped: target, incidental..., temp
            trans.push_patches(&[patchname.clone()], false)?;
            let temp_tree: Oid;
            // Push temp onto target.
            match trans.push_patch(&temp_name, false, true) {
                Ok(()) => {
                    let temp_commit = trans.get_patch_commit(&temp_name);
                    temp_tree = temp_commit.tree_id;
                }
                Err(e) => return Err(e),
            }
            // Pop temp, delete it, update the target.
            trans.pop_patches(|pn| pn == &temp_name)?;
            trans.delete_patches(&[temp_name.clone()])?;
            let target_commit = trans.get_patch_commit(&patchname);
            if temp_tree != target_commit.tree_id
                || new_message.as_bytes() != target_commit.message.as_slice()
                || new_author != target_commit.author
            {
                let parent_id = target_commit.parent_ids[0];
                let new_commit = trans.commit_patch(
                    &new_author,
                    new_message.as_bytes(),
                    temp_tree,
                    &[parent_id],
                )?;
                trans.update_patch_print(&patchname, new_commit)?;
                updated.push(patchname.clone());
            }
            to_push_back.extend(popped);
            trans.push_patches(&to_push_back, false)?;
            Ok(())
        });
    let _ = result.map(|_| ())?;
    let _ = &log_msg_note;
    if failed_absorb {
        println!(
            "The new changes did not apply cleanly to {patchname}. They were saved in {temp_name}."
        );
    }
    Ok(())
}

