    about: "Incorporate worktree changes into current patch",
    category: CommandCategory::PatchManipulation,
    make,
    run,
};

fn make() -> clap::Command {
    let command = clap::Command::new("refresh")
        .about("Incorporate worktree changes into current patch")
        .long_about(
            "Include the latest work tree and index changes in the current patch. This command \
             generates a new git commit object for the patch; the old commit is no longer \
             visible.\n\
             \n\
