            trans.push_patches(&[patchname.clone()], false)?;
            let temp_tree: Oid;
            // Push temp onto target.
            match trans.push_patch(&temp_name, false, true) {
                Ok(()) => {
                    let temp_commit = trans.get_patch_commit(&temp_name);
                    temp_tree = temp_commit.tree_id;
                }
                Err(e) => return Err(e),
            }
            // Pop temp, delete it, update the target.
            trans.pop_patches(|pn| pn == &temp_name)?;
            trans.delete_patches(&[temp_name.clone()])?;
            let target_commit = trans.get_patch_commit(&patchname);
            if temp_tree != target_commit.tree_id
                || new_message.as_bytes() != target_commit.message.as_slice()
                || new_author != target_commit.author
            {
                let parent_id = target_commit.parent_ids[0];
                let new_commit = trans.commit_patch(
                    &new_author,
                    new_message.as_bytes(),
                    temp_tree,
                    &[parent_id],
                )?;
                trans.update_patch_print(&patchname, new_commit)?;
                updated.push(patchname.clone());
            }
            to_push_back.extend(popped);
            trans.push_patches(&to_push_back, false)?;
            Ok(())
        });
    let _ = result.map(|_| ())?;
    let _ = &log_msg_note;
    if failed_absorb {
        println!(
            "The new changes did not apply cleanly to {patchname}. They were saved in {temp_name}."
        );
    }
    Ok(())
}

