        )
        .arg(
            Arg::new("set-tree")
                .long("set-tree")
                .help("Push patches keeping their original trees")
                .long_help(
                    "Push patches keeping their original trees.\n\
                     \n\
                     For each patch pushed, instead of performing a merge, the patch is pushed \
                     such the resulting tree will be identical to the tree associated with the \
                     patch.\n\
                     \n\
                     This can be useful when splitting a patch by first popping the patch and \
                     creating a new patch with some of the changes. Pushing the original patch \
                     with '--set-tree' will avoid conflicts and only the remaining changes will \
                     be in the patch.",
                )
                .action(ArgAction::SetTrue),
        )
        .arg(crate::argset::keep_arg())
        .arg(crate::argset::merged_arg())
