                .long("spill")
                .short('s')
                .help("Keep patches' modifications in index and worktree after popping")
                .action(ArgAction::SetTrue),
        )
        .arg(crate::argset::keep_arg())
        .arg(crate::argset::color_arg())
}

fn run(matches: &ArgMatches, color: ColorChoice) -> Result<()> {
    let repo = Repository::open()?;
    let stack = Stack::from_branch(&repo, None, InitializationPolicy::AllowUninitialized)?;
    let opt_number = matches.get_one::<isize>("number").copied();
    let opt_all = matches.get_flag("all");
    let opt_spill = matches.get_flag("spill");
    let opt_keep = matches.get_flag("keep");

    let ranges = get_ranges(matches, "patchranges");

    let patches: Vec<PatchName> = if !ranges.is_empty() {
        let patches = parse_patch_ranges(&ranges, &stack, RangeConstraint::Visible)?;
        for pn in &patches {
            if stack.is_unapplied(pn) {
                return Err(anyhow!("patch `{pn}` is already unapplied"));
            }
        }
        patches
    } else if stack.applied().is_empty() {
        return Err(anyhow!("no patches applied"));
    } else if opt_all {
        stack.applied().to_vec()
    } else if let Some(n) = opt_number {
        let applied = stack.applied();
        if n >= 0 {
            let n = (n as usize).min(applied.len());
            applied[applied.len() - n..].to_vec()
        } else {
            let keep = ((-n) as usize).min(applied.len());
            applied[keep..].to_vec()
        }
    } else {
        vec![stack.applied().last().unwrap().clone()]
    };

    if patches.is_empty() {
        return Ok(());
