        .use_index_and_worktree(!opt_spill)
        .transact(|trans| {
            trans.set_reflog_msg("pop");
            let incidental = trans.pop_patches(|pn| patches.contains(pn))?;
            trans.push_patches(&incidental, false)
        })?;
    Ok(())
