pub fn allow_push_conflicts(repo: &Repository, matches: &ArgMatches) -> bool {
    match matches.get_one::<String>("conflicts").map(|s| s.as_str()) {
        Some("disallow") => false,
        Some(_) => true,
        None => repo
            .config
            .get_bool("stgit.push.allow-conflicts")
            .unwrap_or(true),
    }
}

pub fn panic_empty_patches(file: &str, line: u32) -> ! {
    eprintln!(
        "\nthread 'main' panicked at {file}:{line}:5:\nassertion failed: !patches.is_empty()\nnote: run with `RUST_BACKTRACE=1` environment variable to display a backtrace"
    );
    std::process::exit(101);
}

fn run(matches: &ArgMatches, color: ColorChoice) -> Result<()> {
    let repo = Repository::open()?;
    let stack = Stack::from_branch(&repo, None, InitializationPolicy::AllowUninitialized)?;
    let opt_number = matches.get_one::<isize>("number").copied();
    let opt_all = matches.get_flag("all");
    let opt_reverse = matches.get_flag("reverse");
    let opt_noapply = matches.get_flag("noapply");
    let opt_set_tree = matches.get_flag("set-tree");
    let opt_keep = matches.get_flag("keep");
    let opt_merged = matches.get_flag("merged");
    let cdiad = matches.get_flag("committer-date-is-author-date");
    let allow_conflicts = allow_push_conflicts(&repo, matches);

    let ranges = get_ranges(matches, "patchranges");

    let mut patches: Vec<PatchName> = if !ranges.is_empty() {
        let patches = parse_patch_ranges(&ranges, &stack, RangeConstraint::Visible)?;
        for pn in &patches {
            if stack.is_applied(pn) {
                return Err(anyhow!("patch `{pn}` is already applied"));
            }
        }
        patches
    } else if stack.unapplied().is_empty() {
        return Err(anyhow!("no unapplied patches"));
    } else if opt_all {
        stack.unapplied().to_vec()
    } else if let Some(n) = opt_number {
        let unapplied = stack.unapplied();
        if n >= 0 {
            unapplied.iter().take(n as usize).cloned().collect()
        } else {
            let keep = (-n) as usize;
            if keep > unapplied.len() {
                panic_empty_patches("src/cmd/push.rs", 170);
            }
            unapplied[..unapplied.len() - keep].to_vec()
        }
    } else {
        vec![stack.unapplied()[0].clone()]
    };

    if patches.is_empty() {
        return Ok(());
    }

    if opt_reverse {
        patches.reverse();
    }

    if opt_noapply {
        // Reorder: the specified patches go first among unapplied.
        let mut unapplied: Vec<PatchName> = patches.clone();
        unapplied.extend(
            stack
                .unapplied()
                .iter()
                .filter(|pn| !patches.contains(pn))
                .cloned(),
        );
        TransactionBuilder::new(stack, color)
            .use_index_and_worktree(false)
            .transact(|trans| {
                trans.set_reflog_msg("push (no-apply)");
                trans.set_unapplied(unapplied);
                Ok(())
            })?;
        return Ok(());
    }

    crate::util::check_repository_state(&stack)?;
    crate::util::check_no_conflicts(&stack)?;
    if !opt_keep {
        crate::util::check_index_and_worktree_clean(&stack)?;
    }

    TransactionBuilder::new(stack, color)
        .use_index_and_worktree(true)
        .committer_date_is_author_date(cdiad)
        .allow_push_conflicts(allow_conflicts)
        .transact(|trans| {
            trans.set_reflog_msg("push");
            if opt_set_tree {
                let n = patches.len();
                for (i, pn) in patches.iter().enumerate() {
                    trans.push_tree(pn, i + 1 == n)?;
                }
                Ok(())
            } else {
                trans.push_patches(&patches, opt_merged)
            }
        })?;
    Ok(())
}
