        .arg(crate::argset::committer_date_is_author_date_arg())
        .arg(crate::argset::push_conflicts_arg())
        .arg(crate::argset::color_arg())
}

fn run(matches: &ArgMatches, color: ColorChoice) -> Result<()> {
    let repo = Repository::open()?;
    let stack = Stack::from_branch(&repo, None, InitializationPolicy::AllowUninitialized)?;
    let opt_keep = matches.get_flag("keep");
    let opt_merged = matches.get_flag("merged");
    let cdiad = matches.get_flag("committer-date-is-author-date");
    let allow_conflicts = super::push::allow_push_conflicts(&repo, matches);

    let loc = matches.get_one::<PatchLocator>("patch").unwrap();
    let patchname = resolve_single(loc, &stack, false)?;

    crate::util::check_repository_state(&stack)?;
    crate::util::check_no_conflicts(&stack)?;
    if !opt_keep {
        crate::util::check_index_and_worktree_clean(&stack)?;
    }

    if stack.is_hidden(&patchname) {
        return Err(anyhow!("hidden patch `{patchname}` is not allowed"));
    }

    TransactionBuilder::new(stack, color)
        .use_index_and_worktree(true)
        .committer_date_is_author_date(cdiad)
        .allow_push_conflicts(allow_conflicts)
        .transact(|trans| {
            trans.set_reflog_msg("goto");
            if let Some(pos) = trans.applied().iter().position(|pn| pn == &patchname) {
                let to_pop: Vec<PatchName> = trans.applied()[pos + 1..].to_vec();
                if !to_pop.is_empty() {
                    trans.pop_patches(|pn| to_pop.contains(pn))?;
                }
                Ok(())
            } else {
                let pos = trans
                    .unapplied()
                    .iter()
                    .position(|pn| pn == &patchname)
                    .unwrap();
                let to_push: Vec<PatchName> = trans.unapplied()[..=pos].to_vec();
                trans.push_patches(&to_push, opt_merged)
            }
        })?;
    Ok(())
}
