    let committer = Signature::default_committer(&repo.config)?;
    let author = Signature::default_author(&repo.config)?;
    let mut state: StackState = stack.state.clone();
    state.prev = None;
    let log_id = state.commit(repo, None, "clear log", &author, &committer)?;
    repo.update_ref(&stack.get_stack_refname(), log_id, "clear log")?;
    stack.log_id = Some(log_id);
    stack.state = state;
    Ok(())
