/// Find the log entry (log commit id and its state) that is `steps` undo steps
/// back. Negative steps are redo steps.
pub fn find_undo_state(repo: &Repository, stack: &mut Stack, mut steps: isize) -> Result<(Oid, StackState)> {
    let is_redo = steps < 0;
    let mut log_id = stack.ensure_log_id()?;
    let mut state = stack.state.clone();
    let err = || {
        if is_redo {
            anyhow!("no more redo information available")
        } else {
            anyhow!("not enough undo information available")
        }
    };
    while steps != 0 {
        let commit = repo.find_commit(log_id)?;
        let msg = commit.summary_str();
        let msg = msg.trim();
        if let Some(n) = msg.strip_prefix("undo ").and_then(|n| n.parse::<isize>().ok()) {
            steps += n;
        } else if let Some(n) = msg.strip_prefix("redo ").and_then(|n| n.parse::<isize>().ok()) {
            steps -= n;
        } else {
            steps -= 1;
        }
        match state.prev {
            Some(prev) => {
                log_id = prev;
                state = StackState::from_commit(repo, prev)?;
            }
            None => return Err(err()),
        }
    }
    Ok((log_id, state))
}

