             stg reset --hard",
        )
        .arg(
            Arg::new("committish")
                .help("Stack state committish")
                .required_unless_present("hard"),
        )
        .arg(
            Arg::new("patchnames")
                .help("Only reset these patches")
                .value_name("patch")
                .num_args(1..)
                .value_parser(clap::value_parser!(PatchName))
                .requires("committish"),
        )
        .arg(
            Arg::new("hard")
                .long("hard")
                .help("Discard changes in the index and worktree")
                .action(ArgAction::SetTrue),
        )
        .arg(crate::argset::color_arg())
}

fn run(matches: &ArgMatches, color: ColorChoice) -> Result<()> {
    let repo = Repository::open()?;
    let stack = Stack::from_branch(&repo, None, InitializationPolicy::AllowUninitialized)?;
    let hard = matches.get_flag("hard");

    let Some(committish) = matches.get_one::<String>("committish") else {
        // Reset only the worktree/index to the stack top.
        let stupid = repo.stupid();
        stupid.read_tree_checkout_hard(stack.top().tree_id)?;
        if stack.branch_head.id != stack.top().id {
            repo.update_ref(&stack.get_branch_refname(), stack.top().id, "reset --hard")?;
        }
        return Ok(());
    };

    let oid = repo
        .rev_parse_commit(committish)?
        .ok_or_else(|| anyhow!("invalid committish `{committish}`"))?;
    let state = StackState::from_commit(&repo, oid)
        .map_err(|_| anyhow!("commit `{committish}` is not a stack state"))?;

    let patchnames: Vec<PatchName> = matches
        .get_many::<PatchName>("patchnames")
        .map(|v| v.cloned().collect())
        .unwrap_or_default();

    if !hard {
        crate::util::check_no_conflicts(&stack)?;
    }

    TransactionBuilder::new(stack, color)
        .use_index_and_worktree(true)
        .discard_changes(hard)
        .allow_bad_head(true)
        .transact(|trans| {
            trans.set_reflog_msg("reset");
            if patchnames.is_empty() {
                trans.reset_to_state(&state)
            } else {
                for pn in &patchnames {
                    if !trans.has_patch(pn) && !state.patches.contains_key(pn) {
                        return Err(anyhow!("patch `{pn}` does not exist"));
                    }
                }
                trans.reset_to_state_partially(&state, &patchnames)
            }
        })?;
    Ok(())
}
