new = '''/// Status summary for the (possibly path-limited) index and work tree.
struct DirtyStatus {
    index_dirty: bool,
    worktree_dirty: bool,
    conflicts: bool,
}

fn dirty_status(repo: &Repository, paths: Option<&[String]>) -> Result<DirtyStatus> {
    let mut args: Vec<String> = vec![
        "status".into(),
        "--porcelain=v1".into(),
        "-z".into(),
        "--untracked-files=no".into(),
    ];
    if let Some(paths) = paths {
        args.push("--".into());
        args.extend(paths.iter().cloned());
    }
    let out = repo.git_output(&args)?;
    if !out.success() {
        return Err(crate::git::repo_git_error("git status", &out));
    }
    let mut st = DirtyStatus {
        index_dirty: false,
        worktree_dirty: false,
        conflicts: false,
    };
    let mut fields = out.stdout.split(|b| *b == 0).peekable();
    while let Some(field) = fields.next() {
        if field.len() < 4 {
            continue;
        }
        let (x, y) = (field[0], field[1]);
        if x == b'R' || x == b'C' {
            fields.next();
        }
        let unmerged = x == b'U' || y == b'U' || (x == b'A' && y == b'A') || (x == b'D' && y == b'D');
        if unmerged {
            st.conflicts = true;
            st.index_dirty = true;
            st.worktree_dirty = true;
            continue;
        }
        if x != b' ' && x != b'?' {
            st.index_dirty = true;
        }
        if y != b' ' && y != b'?' {
            st.worktree_dirty = true;
        }
    }
    Ok(st)
}

/// Files touched by a patch, as paths relative to the work tree root.
fn patch_files(repo: &Repository, patch_commit: &Commit) -> Result<Vec<String>> {
    let parent_tree = match patch_commit.parent_ids.first() {
        Some(p) => repo.find_commit(*p)?.tree_id,
        None => patch_commit.tree_id,
    };
    let stupid = repo.stupid();
    let files = stupid.diff_tree_files(parent_tree, patch_commit.tree_id)?;
    let workdir = repo.workdir().unwrap().to_path_buf();
    let cwd = std::env::current_dir()?;
    let prefix = cwd.strip_prefix(&workdir).unwrap_or(std::path::Path::new(""));
    let mut paths = Vec::new();
    for f in files {
        let f = f.to_string();
        let rel = if prefix.as_os_str().is_empty() {
            f
        } else {
            match std::path::Path::new(&f).strip_prefix(prefix) {
                Ok(r) => r.to_string_lossy().into_owned(),
                Err(_) => format!("{}/{}", pathdiff_to_root(prefix), f),
            }
        };
        paths.push(rel);
    }
    Ok(paths)
}

/// Compute the tree for the refresh from the work tree/index.
fn make_refresh_tree(
    repo: &Repository,
    stack: &Stack,
    opts: &RefreshOptions,
    patch_commit: &Commit,
) -> Result<Oid> {
    let stupid = repo.stupid();
    let head_tree = stack.branch_head.tree_id;
    if opts.use_index {
        return stupid.write_tree();
    }

    let is_path_limiting = opts.update || !opts.pathspecs.is_empty();
    let paths: Vec<String> = if opts.update {
        patch_files(repo, patch_commit)?
    } else {
        opts.pathspecs.clone()
    };

    let status = if is_path_limiting {
        if paths.is_empty() {
            DirtyStatus {
                index_dirty: false,
                worktree_dirty: false,
                conflicts: false,
            }
        } else {
            dirty_status(repo, Some(&paths))?
        }
    } else {
        dirty_status(repo, None)?
    };
    if !is_path_limiting && status.conflicts {
        return Err(anyhow!("resolve outstanding conflicts first"));
    }
    if !opts.force && status.index_dirty && status.worktree_dirty {
        return Err(anyhow!(
            "the index is dirty; consider using `--index` or `--force`"
        ));
    }

    if is_path_limiting {
        if paths.is_empty() {
            return Ok(head_tree);
        }
        // Update the real index for the given paths from the work tree.
        let mut args: Vec<String> = vec!["add".into(), "-u".into(), "--".into()];
        args.extend(paths.iter().cloned());
        let out = repo.git_output(&args)?;
        if !out.success() {
            return Err(crate::git::repo_git_error("git add", &out));
        }
        // Build a tree from HEAD plus the index changes for those paths.
        let mut diff_args: Vec<String> = vec![
            "diff-index".into(),
            "--cached".into(),
            "-p".into(),
            "--full-index".into(),
            "--binary".into(),
            head_tree.to_hex(),
            "--".into(),
        ];
        diff_args.extend(paths.iter().cloned());
        let diff = repo.git_output(&diff_args)?;
        if !diff.success() {
            return Err(crate::git::repo_git_error("git diff-index", &diff));
        }
        stupid.with_temp_index(|temp| {
            temp.read_tree(head_tree)?;
            if !temp.apply_to_index(&diff.stdout)? {
                return Err(anyhow!("`git apply`: failed to apply path-limited changes"));
            }
            temp.write_tree()
        })
    } else {
        let out = repo.git_output(["add", "-u", "--", ":/"])?;
        if !out.success() {
            return Err(crate::git::repo_git_error("git add", &out));
        }
        stupid.write_tree()
    }
}

fn pathdiff_to_root(prefix: &std::path::Path) -> String {
    let n = prefix.components().count();
    let parts: Vec<&str> = (0..n).map(|_| "..").collect();
    parts.join("/")
}

