use anyhow::{anyhow, Result};
use clap::{Arg, ArgAction, ArgMatches};

use super::{CommandCategory, StGitCommand};
use crate::color::ColorChoice;
use crate::git::Repository;
use crate::patch::range::get_ranges;
use crate::patch::{parse_patch_ranges, patch_range_arg_optional, PatchName, RangeConstraint};
use crate::stack::{InitializationPolicy, Stack, TransactionBuilder};

pub const STGIT_COMMAND: StGitCommand = StGitCommand {
    name: "delete",
    about: "Delete patches",
    category: CommandCategory::StackManipulation,
    make,
    run,
};

fn make() -> clap::Command {
    clap::Command::new("delete")
        .about("Delete patches")
        .override_usage(
            "stg delete [OPTIONS] [<patch>...]\n       \
             stg delete [OPTIONS] [-A] [-U] [-H]\n       \
             stg delete [OPTIONS] --all\n       \
             stg delete [OPTIONS] --top",
        )
        .arg(
            patch_range_arg_optional()
                .help("Patches to delete")
                .required_unless_present_any(["all", "applied", "unapplied", "hidden", "top"])
                .conflicts_with_all(["all", "applied", "unapplied", "hidden", "top"]),
        )
        .arg(
            Arg::new("all")
                .long("all")
                .short('a')
                .help("Delete all patches")
                .action(ArgAction::SetTrue)
                .conflicts_with_all(["applied", "unapplied", "hidden", "top"]),
        )
        .arg(
            Arg::new("applied")
                .long("applied")
                .short('A')
                .help("Delete the applied patches")
                .action(ArgAction::SetTrue)
                .conflicts_with("top"),
        )
        .arg(
            Arg::new("unapplied")
                .long("unapplied")
                .short('U')
                .help("Delete the unapplied patches")
                .action(ArgAction::SetTrue)
                .conflicts_with("top"),
        )
        .arg(
            Arg::new("hidden")
                .long("hidden")
                .short('H')
                .help("Delete the hidden patches")
                .action(ArgAction::SetTrue)
                .conflicts_with("top"),
        )
        .arg(
            Arg::new("top")
                .long("top")
                .short('t')
                .help("Delete topmost patch")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("spill")
                .long("spill")
                .help("Spill patch contents to worktree and index")
                .long_help(
                    "Delete the patches, but without modifying the index and worktree. This only \
                     works when deleting applied patches at the top of the stack. The effect is \
                     to \"spill\" the patch contents into the index and worktree.\n\
                     \n\
                     This can be useful for splitting a patch into smaller pieces.",
                )
                .action(ArgAction::SetTrue),
        )
        .arg(crate::argset::branch_arg())
        .arg(crate::argset::push_conflicts_arg())
        .arg(crate::argset::color_arg())
}

fn run(matches: &ArgMatches, color: ColorChoice) -> Result<()> {
    let repo = Repository::open()?;
    let branch = matches.get_one::<String>("branch").map(|s| s.as_str());
    let stack = Stack::from_branch(&repo, branch, InitializationPolicy::AllowUninitialized)?;
    let opt_spill = matches.get_flag("spill");
    let allow_conflicts = super::push::allow_push_conflicts(&repo, matches);

    let ranges = get_ranges(matches, "patchranges");
    let patches: Vec<PatchName> = if !ranges.is_empty() {
        parse_patch_ranges(&ranges, &stack, RangeConstraint::All)?
    } else if matches.get_flag("all") {
        stack.all_patches().cloned().collect()
    } else if matches.get_flag("top") {
        match stack.applied().last() {
            Some(pn) => vec![pn.clone()],
            None => return Err(anyhow!("no patches applied")),
        }
    } else {
        let mut v = Vec::new();
        if matches.get_flag("applied") {
            v.extend(stack.applied().iter().cloned());
        }
        if matches.get_flag("unapplied") {
            v.extend(stack.unapplied().iter().cloned());
        }
        if matches.get_flag("hidden") {
            v.extend(stack.hidden().iter().cloned());
        }
        v
    };

    if opt_spill {
        // Only topmost applied patches may be spilled.
        let applied = stack.applied();
        let n = patches.len();
        let top_slice: Vec<&PatchName> = applied.iter().rev().take(n).collect();
        for pn in &patches {
            if !top_slice.contains(&pn) {
                return Err(anyhow!("can only spill topmost applied patches"));
            }
        }
    }

    let is_current_branch = branch.is_none() || branch == Some(stack.branch_name.as_str());
    let use_worktree = is_current_branch && !opt_spill;
    if use_worktree {
        crate::util::check_repository_state(&stack)?;
        crate::util::check_no_conflicts(&stack)?;
        crate::util::check_index_and_worktree_clean(&stack)?;
    }

    TransactionBuilder::new(stack, color)
        .use_index_and_worktree(use_worktree)
        .allow_bad_head(!is_current_branch)
        .allow_push_conflicts(allow_conflicts)
        .transact(|trans| {
            trans.set_reflog_msg("delete");
            let to_push = trans.delete_patches_ranged(&patches)?;
            trans.push_patches(&to_push, false)
        })?;
    Ok(())
}
