use anyhow::{anyhow, Result};
use clap::{Arg, ArgMatches};

use super::{CommandCategory, StGitCommand};
use crate::color::ColorChoice;
use crate::git::Repository;
use crate::patch::range::{resolve_single, PatchLocator};
use crate::patch::{parse_patchname_arg, PatchName};
use crate::stack::{InitializationPolicy, Stack, TransactionBuilder};

pub const STGIT_COMMAND: StGitCommand = StGitCommand {
    name: "rename",
    about: "Rename a patch",
    category: CommandCategory::PatchManipulation,
    make,
    run,
};

fn make() -> clap::Command {
    clap::Command::new("rename")
        .about("Rename a patch")
        .long_about(
            "Rename [old-patch] to <new-patch>. If [old-patch] is not given, the topmost patch \
             will be renamed.",
        )
        .override_usage("stg rename [OPTIONS] [old-patch] <new-patch>")
        .arg(
            Arg::new("patches")
                .help("Optional old patch and the new patch name")
                .value_name("patches")
                .num_args(1..=2)
                .required(true)
                .allow_hyphen_values(true),
        )
        .arg(crate::argset::branch_arg())
        .arg(crate::argset::color_arg())
}

fn run(matches: &ArgMatches, color: ColorChoice) -> Result<()> {
    let repo = Repository::open()?;
    let branch = matches.get_one::<String>("branch").map(|s| s.as_str());
    let stack = Stack::from_branch(&repo, branch, InitializationPolicy::AllowUninitialized)?;
    let args: Vec<&String> = matches.get_many::<String>("patches").unwrap().collect();
    let (old_name, new_name): (PatchName, PatchName) = if args.len() == 2 {
        let loc: PatchLocator = args[0]
            .parse()
            .map_err(|_| anyhow!("invalid patch locator `{}`", args[0]))?;
        let old = resolve_single(&loc, &stack, true)?;
        (old, parse_patchname_arg(args[1])?)
    } else {
        let old = stack
            .applied()
            .last()
            .cloned()
            .ok_or_else(|| anyhow!("no patches applied"))?;
        (old, parse_patchname_arg(args[0])?)
    };
    if old_name == new_name {
        return Ok(());
    }
    if let Some(existing) = stack.collides(&new_name) {
        if existing != &old_name {
            return Err(anyhow!("patch `{existing}` already exists"));
        }
    }
    TransactionBuilder::new(stack, color)
        .use_index_and_worktree(false)
        .allow_bad_head(true)
        .transact(|trans| {
            trans.set_reflog_msg(&format!("rename {old_name} {new_name}"));
            trans.rename_patch(&old_name, &new_name)
        })?;
    Ok(())
}
