             patch if '--above' or '--below' is used), then pushing the patches to sink, and \
             then, unless '--nopush' is specified, pushing back any other formerly applied \
             patches.\n\
             \n\
             Sinking may be useful, for example, to group stable patches at the bottom of the \
             stack where they less likely to be impacted by the push of another patch, and from \
             where they can be more easily committed or pushed to another repository.",
        )
        .arg(patch_range_arg_optional().help("Patches to sink"))
        .arg(
            Arg::new("nopush")
                .long("nopush")
                .short('n')
                .help("Do not push any patches back after sinking")
                .long_help(
                    "Do not push any formerly applied patches after sinking. Only the patches to \
                     sink are pushed.",
                )
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("below")
                .long("below")
                .short('t')
                .visible_alias("to")
                .help("Sink patches below <target> patch")
                .long_help(
                    "Sink patches below <target> patch.\n\
                     \n\
                     Specified patches are placed below <target> instead of at the bottom of the \
                     stack.",
                )
                .value_name("target")
                .value_parser(clap::value_parser!(PatchLocator))
                .conflicts_with("above"),
        )
        .arg(
            Arg::new("above")
                .long("above")
                .short('T')
                .help("Sink patches above <target> patch")
                .long_help(
                    "Sink patches above <target> patch.\n\
                     \n\
                     Specified patches are placed above <target> instead of at the bottom of the \
                     stack.",
                )
                .value_name("target")
                .value_parser(clap::value_parser!(PatchLocator)),
        )
        .arg(crate::argset::keep_arg())
        .arg(crate::argset::committer_date_is_author_date_arg())
        .arg(crate::argset::color_arg())
}

fn run(matches: &ArgMatches, color: ColorChoice) -> Result<()> {
    let repo = Repository::open()?;
    let stack = Stack::from_branch(&repo, None, InitializationPolicy::AllowUninitialized)?;
    let opt_nopush = matches.get_flag("nopush");
    let opt_keep = matches.get_flag("keep");
    let cdiad = matches.get_flag("committer-date-is-author-date");

    let ranges = get_ranges(matches, "patchranges");
    let patches: Vec<PatchName> = if ranges.is_empty() {
        match stack.applied().last() {
            Some(pn) => vec![pn.clone()],
            None => return Err(anyhow!("no patches applied")),
        }
    } else {
        parse_patch_ranges(&ranges, &stack, RangeConstraint::Visible)?
    };

    let (target, above): (Option<PatchName>, bool) =
        if let Some(loc) = matches.get_one::<PatchLocator>("below") {
            let pn = resolve_single(loc, &stack, false).map_err(|e| anyhow!("target: {e}"))?;
            (Some(pn), false)
        } else if let Some(loc) = matches.get_one::<PatchLocator>("above") {
            let pn = resolve_single(loc, &stack, false).map_err(|e| anyhow!("target: {e}"))?;
            (Some(pn), true)
        } else {
            (None, false)
        };

    if let Some(target) = &target {
        if patches.contains(target) {
            return Err(anyhow!("target patch `{target}` may not also be a patch to sink"));
        }
        if !stack.is_applied(target) {
            return Err(anyhow!(
                "cannot sink {} `{target}` since it is not applied",
                if above { "above" } else { "below" }
            ));
        }
    }

    crate::util::check_repository_state(&stack)?;
    crate::util::check_no_conflicts(&stack)?;
    if !opt_keep {
        crate::util::check_index_and_worktree_clean(&stack)?;
    }

    TransactionBuilder::new(stack, color)
        .use_index_and_worktree(true)
        .committer_date_is_author_date(cdiad)
        .transact(|trans| {
            trans.set_reflog_msg("sink");
            let applied = trans.applied().to_vec();
            let remaining: Vec<PatchName> = applied
                .iter()
                .filter(|pn| !patches.contains(pn))
                .cloned()
                .collect();
            let insert_pos = match &target {
                Some(t) => {
                    let pos = remaining.iter().position(|pn| pn == t).unwrap();
                    if above {
                        pos + 1
                    } else {
                        pos
                    }
                }
                None => 0,
            };
            let mut new_applied: Vec<PatchName> = remaining[..insert_pos].to_vec();
            new_applied.extend(patches.iter().cloned());
            if !opt_nopush {
                new_applied.extend(remaining[insert_pos..].iter().cloned());
            }
            let unapplied: Vec<PatchName> = if opt_nopush {
                let mut u: Vec<PatchName> = remaining[insert_pos..].to_vec();
                u.extend(
                    trans
                        .unapplied()
                        .iter()
                        .filter(|pn| !patches.contains(pn))
                        .cloned(),
                );
                u
            } else {
                trans
                    .unapplied()
                    .iter()
                    .filter(|pn| !patches.contains(pn))
                    .cloned()
                    .collect()
            };
            trans.reorder_patches(Some(&new_applied), Some(&unapplied), None)
        })?;
    Ok(())
}
