use anyhow::{anyhow, Result};
use clap::{Arg, ArgAction, ArgMatches};

use super::{CommandCategory, StGitCommand};
use crate::color::ColorChoice;
use crate::git::Repository;
use crate::patch::range::get_ranges;
use crate::patch::{parse_patch_ranges, patch_range_arg_optional, PatchName, RangeConstraint};
use crate::stack::{InitializationPolicy, Stack, TransactionBuilder};

pub const STGIT_COMMAND: StGitCommand = StGitCommand {
    name: "commit",
    about: "Finalize patches to the stack base",
    category: CommandCategory::StackManipulation,
    make,
    run,
};

fn make() -> clap::Command {
    clap::Command::new("commit")
        .about("Finalize patches to the stack base")
        .long_about(
            "Finalize one or more patches into the base of the current stack and remove them \
             from the series. This is the opposite of 'stg uncommit'. Use this command when a \
             patch is completed and no longer needs to be managed with StGit.\n\
             \n\
             By default, the bottommost patch is committed. If patch names are given, the stack \
             is rearranged so that those patches are at the bottom, and then they are \
             committed.\n\
             \n\
             The -n/--number option specifies the number of applied patches to commit (counting \
             from the bottom of the stack). If -a/--all is given, all applied patches are \
             committed.",
        )
        .override_usage(
            "stg commit [OPTIONS] [patch]...\n       \
             stg commit [OPTIONS] -n <number>\n       \
             stg commit [OPTIONS] --all",
        )
        .arg(
            patch_range_arg_optional()
                .help("Patches to commit")
                .conflicts_with_all(["number", "all"]),
        )
        .arg(
            Arg::new("number")
                .long("number")
                .short('n')
                .help("Commit the specified number of applied patches")
                .value_name("number")
                .value_parser(clap::value_parser!(usize))
                .conflicts_with("all"),
        )
        .arg(
            Arg::new("all")
                .long("all")
                .short('a')
                .help("Commit all applied patches")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("allow-empty")
                .long("allow-empty")
                .help("Allow empty patches to be committed")
                .action(ArgAction::SetTrue),
        )
        .arg(crate::argset::color_arg())
}

fn run(matches: &ArgMatches, color: ColorChoice) -> Result<()> {
    let repo = Repository::open()?;
    let stack = Stack::from_branch(&repo, None, InitializationPolicy::AllowUninitialized)?;
    stack.check_protected()?;
    let allow_empty = matches.get_flag("allow-empty");

    let ranges = get_ranges(matches, "patchranges");
    let patches: Vec<PatchName> = if !ranges.is_empty() {
        let patches = parse_patch_ranges(&ranges, &stack, RangeConstraint::Visible)?;
        for pn in &patches {
            if !stack.is_applied(pn) {
                return Err(anyhow!("patch `{pn}` is not applied"));
            }
        }
        patches
    } else if let Some(n) = matches.get_one::<usize>("number") {
        if *n == 0 {
            return Ok(());
        }
        if stack.applied().is_empty() {
            return Err(anyhow!("no patches applied"));
        }
        if *n > stack.applied().len() {
            return Err(anyhow!("there are not `{n}` applied patches to commit"));
        }
        stack.applied()[..*n].to_vec()
    } else if matches.get_flag("all") {
        if stack.applied().is_empty() {
            return Err(anyhow!("no patches applied"));
        }
        stack.applied().to_vec()
    } else {
        match stack.applied().first() {
            Some(pn) => vec![pn.clone()],
            None => return Err(anyhow!("no patches applied")),
        }
    };

    if !allow_empty {
        for pn in &patches {
            if super::clean::is_empty_patch(&repo, &stack, pn)? {
                return Err(anyhow!(
                    "attempt to commit empty patch `{pn}`; use --allow-empty to override"
                ));
            }
        }
    }

    crate::util::check_repository_state(&stack)?;
    crate::util::check_no_conflicts(&stack)?;

    TransactionBuilder::new(stack, color)
        .use_index_and_worktree(true)
        .transact(|trans| {
            trans.set_reflog_msg("commit");
            let applied = trans.applied().to_vec();
            let n = patches.len();
            // If the patches are already the bottom n applied patches (as a set),
            // no reordering is needed.
            let bottom: Vec<&PatchName> = applied.iter().take(n).collect();
            let needs_reorder = !patches.iter().all(|pn| bottom.contains(&pn));
            let to_commit: Vec<PatchName> = if needs_reorder {
                let mut new_applied: Vec<PatchName> = patches.clone();
                new_applied.extend(applied.iter().filter(|pn| !patches.contains(pn)).cloned());
                // Pop everything above the first changed position, push the committed
                // patches first, then commit, then push back the rest.
                let num_common = applied
                    .iter()
                    .zip(new_applied.iter())
                    .take_while(|(a, b)| a == b)
                    .count();
                let to_pop: Vec<PatchName> = applied[num_common..].to_vec();
                trans.pop_patches(|pn| to_pop.contains(pn))?;
                let to_push_first: Vec<PatchName> = new_applied[num_common..n].to_vec();
                trans.push_patches(&to_push_first, false)?;
                let committed: Vec<PatchName> = new_applied[..n].to_vec();
                trans.commit_patches_ranged(&committed)?;
                let rest: Vec<PatchName> = new_applied[n..].to_vec();
                trans.push_patches(&rest, false)?;
                return Ok(());
            } else {
                applied[..n].to_vec()
            };
            trans.commit_patches_ranged(&to_commit)
        })?;
    Ok(())
}
