use std::rc::Rc;

use anyhow::{anyhow, Result};
use clap::{Arg, ArgAction, ArgMatches};

use super::{CommandCategory, StGitCommand};
use crate::color::ColorChoice;
use crate::git::{Commit, Oid, Repository};
use crate::patch::PatchName;
use crate::stack::{InitializationPolicy, Stack, TransactionBuilder};

pub const STGIT_COMMAND: StGitCommand = StGitCommand {
    name: "uncommit",
    about: "Convert regular Git commits into StGit patches",
    category: CommandCategory::StackManipulation,
    make,
    run,
};

fn make() -> clap::Command {
    clap::Command::new("uncommit")
        .about("Convert regular Git commits into StGit patches")
        .long_about(
            "Convert one or more Git commits from the base of the current stack into StGit \
             patches. The original Git commits are not modified; the StGit stack extends to \
             incorporate these commits as the bottommost applied patches. This is the opposite \
             of 'stg commit'.\n\
             \n\
             By default, the number of patches to uncommit is determined by the number of patch \
             names provided on the command line. The first provided name is used for the first \
             patch to uncommit, i.e. for the newest patch.\n\
             \n\
             The -n/--number option specifies the number of patches to uncommit. In this case, \
             at most one patch name may be specified. It is used as prefix to which the patch \
             number is appended. If no patch names are provided on the command line, StGit \
             automatically generates names based on the first lines of the commit messages.\n\
             \n\
             The -t/--to option specifies that all commits up to and including the given commit \
             should be uncommitted. The -x/--exclusive option may be used to exclude the \"to\" \
             commit.\n\
             \n\
             Only commits with exactly one parent can be uncommitted; in other words, merge \
             commits may not be uncommitted.",
        )
        .override_usage(
            "stg uncommit <patchname-1> [<patchname-2> ...]\n       \
             stg uncommit -n number [<patchname-prefix>]\n       \
             stg uncommit -t <committish> [-x]",
        )
        .arg(
            Arg::new("patchname")
                .help("Patch names for the uncommitted commits")
                .value_name("patchname")
                .num_args(1..)
                .value_parser(clap::value_parser!(PatchName))
                .conflicts_with("to"),
        )
        .arg(
            Arg::new("number")
                .long("number")
                .short('n')
                .help("Uncommit the specified number of commits")
                .value_name("number")
                .value_parser(clap::value_parser!(usize))
                .conflicts_with("to"),
        )
        .arg(
            Arg::new("to")
                .long("to")
                .short('t')
                .help("Uncommit to the specified committish")
                .value_name("committish"),
        )
        .arg(
            Arg::new("exclusive")
                .long("exclusive")
                .short('x')
                .help("Exclude the commit specified by the '--to' option")
                .action(ArgAction::SetTrue)
                .requires("to"),
        )
        .arg(crate::argset::color_arg())
}

fn run(matches: &ArgMatches, color: ColorChoice) -> Result<()> {
    let repo = Repository::open()?;
    let stack = Stack::from_branch(&repo, None, InitializationPolicy::AutoInitialize)?;
    stack.check_protected()?;
    let patchnames: Vec<PatchName> = matches
        .get_many::<PatchName>("patchname")
        .map(|v| v.cloned().collect())
        .unwrap_or_default();
    let opt_number = matches.get_one::<usize>("number").copied();
    let opt_to = matches.get_one::<String>("to");
    let opt_exclusive = matches.get_flag("exclusive");

    let base = stack.base.clone();

    // Collect commits to uncommit, from the base downwards.
    let mut commits: Vec<Rc<Commit>> = Vec::new();
    let next_parent = |commit: &Commit| -> Result<Oid> {
        if commit.parent_ids.len() != 1 {
            return Err(anyhow!(
                "cannot uncommit `{}` which does not have exactly one parent",
                commit.id
            ));
        }
        Ok(commit.parent_ids[0])
    };

    if let Some(to) = opt_to {
        let to_id = repo
            .rev_parse_commit(to)?
            .ok_or_else(|| anyhow!("invalid committish `{to}`"))?;
        if opt_exclusive {
            println!("Uncommitting to {to_id} (exclusive)");
        } else {
            println!("Uncommitting to {to_id}");
        }
        let mut current = base.clone();
        loop {
            if current.id == to_id {
                if !opt_exclusive {
                    next_parent(&current)?;
                    commits.push(current.clone());
                }
                break;
            }
            let parent = next_parent(&current)?;
            commits.push(current.clone());
            current = repo.find_commit(parent)?;
        }
    } else {
        let count = match opt_number {
            Some(n) => {
                if patchnames.len() > 1 {
                    return Err(anyhow!(
                        "when using `--number`, specify at most one patch name"
                    ));
                }
                n
            }
            None => patchnames.len().max(1),
        };
        let mut current = base.clone();
        for _ in 0..count {
            let parent = next_parent(&current)?;
            commits.push(current.clone());
            current = repo.find_commit(parent)?;
        }
    }

    if commits.is_empty() {
        TransactionBuilder::new(stack, color)
            .use_index_and_worktree(false)
            .allow_bad_head(true)
            .transact(|trans| {
                trans.set_reflog_msg("uncommit");
                Ok(())
            })?;
        return Ok(());
    }

    // Assign names. commits[0] is the newest (nearest the stack).
    let mut names: Vec<PatchName> = Vec::new();
    if opt_number.is_some() && patchnames.len() == 1 {
        let prefix = &patchnames[0];
        let n = commits.len();
        for i in 0..n {
            // oldest gets 1
            let num = n - i;
            names.push(PatchName::from_str_lenient(&format!("{prefix}{num}")));
        }
    } else if !patchnames.is_empty() && opt_to.is_none() {
        names = patchnames.clone();
    } else {
        let mut taken: Vec<PatchName> = stack.all_patches().cloned().collect();
        for commit in &commits {
            let summary = commit.summary_str();
            let len_limit = repo
                .config
                .get_i64("stgit.namelength")
                .map(|n| n.max(0) as usize)
                .unwrap_or(30);
            let pn = PatchName::make(&summary, true, Some(len_limit))
                .uniquify(|p| taken.iter().any(|t| t.collides(p)));
            taken.push(pn.clone());
            names.push(pn);
        }
    }
    for pn in &names {
        if let Some(existing) = stack.collides(pn) {
            return Err(anyhow!("patch `{existing}` already exists"));
        }
    }

    let pairs: Vec<(PatchName, Rc<Commit>)> = names.into_iter().zip(commits).collect();
    TransactionBuilder::new(stack, color)
        .use_index_and_worktree(false)
        .allow_bad_head(true)
        .transact(|trans| {
            trans.set_reflog_msg("uncommit");
            trans.uncommit_patches(&pairs)
        })?;
    Ok(())
}
