    let contiguous = matches!(constraint, RangeConstraint::AllContiguous);
    let bounded = matches!(constraint, RangeConstraint::AllContiguous | RangeConstraint::AllBounded);
    let (list_start, list_end): (usize, usize) = match constraint {
        RangeConstraint::Visible | RangeConstraint::VisibleUnapplied => (0, visible_len),
        RangeConstraint::Applied => (0, num_applied),
        RangeConstraint::Unapplied => (num_applied, visible_len),
        RangeConstraint::Hidden | RangeConstraint::AllHidden => (visible_len, all.len()),
        RangeConstraint::AllContiguous
        | RangeConstraint::AllBounded
        | RangeConstraint::All
        | RangeConstraint::AllUnapplied => (0, all.len()),
    };
