                return Err(anyhow!("patch `{pn}` is not hidden"));
            } else if idx < num_applied {
                return Err(anyhow!("patch `{pn}` is already applied"));
            } else {
                return Err(anyhow!("patch `{pn}` is already unapplied"));
            }
        }
        Ok(idx - list_start)
    };

