    AllContiguous,
    /// All patches, any order; open ends bounded by the top applied patch (delete).
    AllBounded,
    /// All patches, any order, no boundary (sink, hide).
    All,
    /// Alias kept for callers: visible patches, open ranges over unapplied.
    VisibleUnapplied,
    AllUnapplied,
    AllHidden,
}

/// Resolve the given patch ranges to a list of patch names.
pub fn parse_patch_ranges(
    ranges: &[PatchRange],
    stack: &Stack,
    constraint: RangeConstraint,
) -> Result<Vec<PatchName>> {
    let all: Vec<PatchName> = stack.all_patches().cloned().collect();
    let num_applied = stack.applied().len();
    let visible_len = num_applied + stack.unapplied().len();
    let contiguous = matches!(constraint, RangeConstraint::AllContiguous);
    let bounded = matches!(constraint, RangeConstraint::AllContiguous | RangeConstraint::AllBounded);
    let (list_start, list_end): (usize, usize) = match constraint {
        RangeConstraint::Visible | RangeConstraint::VisibleUnapplied => (0, visible_len),
        RangeConstraint::Applied => (0, num_applied),
        RangeConstraint::Unapplied => (num_applied, visible_len),
        RangeConstraint::Hidden | RangeConstraint::AllHidden => (visible_len, all.len()),
        RangeConstraint::AllContiguous
        | RangeConstraint::AllBounded
        | RangeConstraint::All
        | RangeConstraint::AllUnapplied => (0, all.len()),
    };
    let list: &[PatchName] = &all[list_start..list_end];
    let is_hidden_list = matches!(constraint, RangeConstraint::Hidden | RangeConstraint::AllHidden);

    // Resolve a locator against the full list, then check membership.
    let resolve = |loc: &PatchLocator| -> Result<usize> {
        let idx = loc.resolve(stack, &all)?;
        if idx < list_start || idx >= list_end {
            let pn = &all[idx];
            if idx >= visible_len {
                if is_hidden_list {
                    unreachable!()
                }
                return Err(anyhow!("hidden patch `{pn}` is not allowed"));
            } else if is_hidden_list {
                return Err(anyhow!("patch `{pn}` is not hidden"));
            } else if idx < num_applied {
                return Err(anyhow!("patch `{pn}` is already applied"));
            } else {
                return Err(anyhow!("patch `{pn}` is already unapplied"));
            }
        }
        Ok(idx - list_start)
    };

    let mut result: Vec<PatchName> = Vec::new();
    let mut prev_range_end: Option<(usize, String)> = None;

    for range in ranges {
        match &range.item {
            PatchRangeItem::Single(loc) => {
                let idx = resolve(loc)?;
                if contiguous {
                    if let Some((prev_idx, prev_raw)) = &prev_range_end {
                        if idx != prev_idx + 1 {
                            if result.contains(&list[idx]) {
                                return Err(anyhow!("patch `{}` is used more than once", list[idx]));
                            }
                            return Err(anyhow!(
                                "`{}` not contiguous with preceding range `{}`",
                                range.raw,
                                prev_raw
                            ));
                        }
                    }
                }
                let pn = list[idx].clone();
                if result.contains(&pn) {
                    return Err(anyhow!("patch `{pn}` is used more than once"));
                }
                result.push(pn);
                prev_range_end = Some((idx, range.raw.clone()));
            }
            PatchRangeItem::Range(a, b) => {
                if list.is_empty() {
                    continue;
                }
                let start_idx = match a {
                    Some(loc) => Some(resolve(loc)?),
                    None => None,
                };
                let end_idx = match b {
                    Some(loc) => Some(resolve(loc)?),
                    None => None,
                };
                // Index of the top applied patch within `list`, if bounded.
                let top_in_list: Option<usize> = if bounded && num_applied > 0 {
                    Some(num_applied - 1 - list_start)
                } else {
                    None
                };
                let (start, end) = match (start_idx, end_idx) {
                    (Some(s), Some(e)) => (s, e),
                    (Some(s), None) => {
                        let e = match top_in_list {
                            Some(t) if s <= t => t,
                            _ => list.len() - 1,
                        };
                        (s, e)
                    }
                    (None, Some(e)) => (0, e),
                    (None, None) => match top_in_list {
                        Some(t) => (0, t),
                        None => (0, list.len() - 1),
                    },
                };
                if contiguous {
                    if let Some((prev_idx, prev_raw)) = &prev_range_end {
                        if start != prev_idx + 1 {
                            return Err(anyhow!(
                                "`{}` not contiguous with preceding range `{}`",
                                range.raw,
                                prev_raw
                            ));
                        }
                    }
                    if end < start {
                        return Err(anyhow!(
                            "end patch `{}` is out of order with `{}`",
                            list[end],
                            list[start]
                        ));
                    }
                }
                let indices: Vec<usize> = if end >= start {
                    (start..=end).collect()
                } else {
                    (end..=start).rev().collect()
                };
                for idx in indices {
                    let pn = list[idx].clone();
                    if result.contains(&pn) {
                        return Err(anyhow!("patch `{pn}` is used more than once"));
                    }
                    result.push(pn);
                }
                prev_range_end = Some((end.max(start), range.raw.clone()));
            }
        }
    }
    Ok(result)
}

fn resolve_in_list(
    loc: &PatchLocator,
    stack: &Stack,
    all: &[PatchName],
    list: &[PatchName],
) -> Result<usize> {
    let idx = loc.resolve(stack, all)?;
    if idx >= list.len() {
        let pn = &all[idx];
        return Err(anyhow!("hidden patch `{pn}` is not allowed"));
    }
    Ok(idx)
}

