use anyhow::{anyhow, Result};
use clap::{Arg, ArgMatches};

use super::{CommandCategory, StGitCommand};
use crate::color::ColorChoice;
use crate::git::{Oid, Repository};
use crate::patch::range::{resolve_single, PatchLocator};
use crate::patch::PatchName;
use crate::patchedit::{self, EditOptions, EditOutcome, PatchDescription};
use crate::stack::{InitializationPolicy, Stack, TransactionBuilder};

pub const STGIT_COMMAND: StGitCommand = StGitCommand {
    name: "edit",
    about: "Edit a patch",
    category: CommandCategory::PatchManipulation,
    make,
    run,
};

fn make() -> clap::Command {
    let command = clap::Command::new("edit")
        .about("Edit a patch")
        .long_about(
            "Edit a patch. Various aspects of a patch may be edited, including the message, \
             author, patch name, or even the patch's diff.\n\
             \n\
             By default, the topmost patch is edited.\n\
             \n\
             With no options or when '--edit' is specified, the patch details are edited \
             interactively. Alternatively, command line options may be used to modify the patch \
             non-interactively.\n\
             \n\
             The '--diff' option causes the patch's diff to be appended to the patch description \
             when editing interactively. This diff may be edited interactively (or just used as a \
             reference when editing the patch's message). The StGit attempts to apply the \
             modified diff to the patch's parent tree. If the updated diff does not apply, no \
             changes are made to the patch and the edited patch is saved to a file which may be \
             corrected and then fed-back into `stg edit --file`.",
        )
        .arg(
            Arg::new("patch")
                .help("Patch to edit")
                .value_parser(clap::value_parser!(PatchLocator))
                .allow_hyphen_values(true),
        )
        .arg(crate::argset::color_arg());
    patchedit::add_args(command, true, true).arg(
        Arg::new("set-tree")
            .long("set-tree")
            .short('t')
            .help("Set patch's tree to treeish")
            .long_help(
                "Set the patch's git tree to the specified treeish without changing the tree of \
                 any other patches. When used on the top patch, the index and work tree will be \
                 updated to match the new tree. This low-level option is primarily meant to be \
                 used by tools built on top of StGit, such as the Emacs mode. See also the \
                 '--set-tree' flag of 'stg push'.",
            )
            .value_name("treeish"),
    )
}

fn run(matches: &ArgMatches, color: ColorChoice) -> Result<()> {
    let repo = Repository::open()?;
    let stack = Stack::from_branch(&repo, None, InitializationPolicy::AllowUninitialized)?;
    let patchname = match matches.get_one::<PatchLocator>("patch") {
        Some(loc) => resolve_single(loc, &stack, true)?,
        None => stack
            .applied()
            .last()
            .cloned()
            .ok_or_else(|| anyhow!("no patches applied"))?,
    };
    let opts = EditOptions::from_matches(matches, &repo.config)?;
    let set_tree: Option<Oid> = match matches.get_one::<String>("set-tree") {
        Some(treeish) => Some(
            repo.rev_parse(&format!("{treeish}^{{tree}}"))?
                .ok_or_else(|| anyhow!("invalid treeish `{treeish}`"))?,
        ),
        None => None,
    };
    let patch_commit = stack.get_patch_commit(&patchname).clone();
    let parent_id = patch_commit.parent_ids[0];
    let parent_tree = repo.find_commit(parent_id)?.tree_id;

    let interactive = opts.edit || (opts.is_noop() && set_tree.is_none());
    let diff = if opts.diff {
        Some(patchedit::patch_diff(&repo, &patch_commit)?)
    } else {
        None
    };
    let outcome = patchedit::edit_description(
        &repo,
        &opts,
        Some(&patchname),
        &patch_commit.author,
        &patch_commit.message_str(),
        diff.as_deref(),
        "# The diff below may be edited.\n",
        interactive,
        false,
        color,
    )?;
    let (new_name, new_author, new_message, new_diff) = match outcome {
        EditOutcome::TemplateSaved => return Ok(()),
        EditOutcome::Edited {
            patchname,
            author,
            message,
            diff,
