/// Run a git command that produces diff-like output to stdout, propagating
/// errors as "`git <name>`: <stderr>".
pub fn run_git_to_stdout(repo: &crate::git::Repository, name: &str, args: &[String]) -> anyhow::Result<()> {
    use std::io::Write;
    let mut cmd = repo.git_command();
    cmd.args(args);
    cmd.stdout(std::process::Stdio::piped())
        .stderr(std::process::Stdio::piped());
    let mut child = cmd.spawn()?;
    let mut child_stdout = child.stdout.take().unwrap();
    let mut stdout = std::io::stdout().lock();
    let mut buf = [0u8; 8192];
    let mut write_err: Option<std::io::Error> = None;
    loop {
        let n = std::io::Read::read(&mut child_stdout, &mut buf)?;
        if n == 0 {
            break;
        }
        if write_err.is_none() {
            if let Err(e) = stdout.write_all(&buf[..n]).and_then(|_| stdout.flush()) {
                write_err = Some(e);
            }
        }
    }
    let output = child.wait_with_output()?;
    if let Some(e) = write_err {
        if e.kind() == std::io::ErrorKind::BrokenPipe {
            return Err(anyhow::anyhow!("`git {name}`: broken pipe"));
        }
        return Err(e.into());
    }
    if !output.status.success() {
        return Err(anyhow::anyhow!(
            "`git {name}`: {}",
            String::from_utf8_lossy(&output.stderr).trim_end()
        ));
    }
    Ok(())
}

