        )
        .arg(revision_arg().allow_hyphen_values(true))
        .arg(
            Arg::new("stat")
                .long("stat")
                .short('s')
                .help("Show patch's diffstat")
                .action(ArgAction::SetTrue)
                .conflicts_with("bare"),
        )
        .arg(
