fn run(matches: &ArgMatches, color: ColorChoice) -> Result<()> {
    let repo = Repository::open()?;
    let spec = matches.get_one::<StGitRevision>("stgit-revision");
    let (_stack, rev) = parse_stgit_revision(&repo, spec, None, InitializationPolicy::AllowUninitialized)?;
    let commit = rev
        .commit
        .clone()
        .ok_or_else(|| anyhow!("revision `{}` is not a commit", rev.oid))?;
    let parent_id = commit
        .parent_ids
        .first()
        .copied()
        .ok_or_else(|| anyhow!("commit `{}` does not have a parent", commit.id))?;
    let parent = repo.find_commit(parent_id)?;

    if matches.get_flag("stat") {
        let args: Vec<String> = vec![
            "diff-tree".to_string(),
            "--stat".to_string(),
            "--summary".to_string(),
            "-r".to_string(),
            crate::argset::color_arg_for_git(color),
            parent.tree_id.to_hex(),
            commit.tree_id.to_hex(),
        ];
        return crate::argset::run_git_to_stdout(&repo, "diff-tree", &args);
    }

    let out = repo.git_output([
        "diff-tree",
        "-r",
        "--name-status",
        "-z",
        &parent.tree_id.to_hex(),
        &commit.tree_id.to_hex(),
    ])?;
    if !out.success() {
        return Err(crate::git::repo_git_error("git diff-tree", &out));
    }
    let bare = matches.get_flag("bare");
    let mut stdout = crate::color::stdout(color);
    let mut fields = out.stdout.split(|b| *b == 0);
    while let Some(status) = fields.next() {
        if status.is_empty() {
            break;
        }
        let Some(path) = fields.next() else { break };
        let status_char = status[0] as char;
        if status_char == 'R' || status_char == 'C' {
            // name-status with rename: second path follows
            let _ = fields.next();
        }
        if bare {
            stdout.write_all(path)?;
            writeln!(stdout)?;
        } else {
            let c = match status_char {
                'A' => Color::Green,
                'D' => Color::Red,
                'M' => Color::Blue,
                _ => Color::Yellow,
            };
            let mut spec = ColorSpec::new();
            spec.set_fg(Some(c));
            stdout.set_color(&spec)?;
            write!(stdout, "{status_char}")?;
            stdout.reset()?;
            write!(stdout, " ")?;
            stdout.write_all(path)?;
            writeln!(stdout)?;
        }
    }
    stdout.flush()?;
    Ok(())
}
