/// Resolve a "patch-or-rev" argument to commit oids.
fn resolve_patch_or_rev(repo: &Repository, stack: &Stack, arg: &str) -> Result<Vec<Oid>> {
    if let Ok(range) = arg.parse::<PatchRange>() {
        if range.is_range() {
            let patches = parse_patch_ranges(&[range], stack, RangeConstraint::All)?;
            return Ok(patches
                .iter()
                .map(|pn| stack.get_patch_commit(pn).id)
                .collect());
        }
        if let Ok(pn) = arg.parse::<PatchName>() {
            if stack.has_patch(&pn) {
                return Ok(vec![stack.get_patch_commit(&pn).id]);
            }
        }
    }
    if let Ok(spec) = arg.parse::<StGitRevision>() {
        if let Ok((_, rev)) = crate::patch::parse_stgit_revision(
            repo,
            Some(&spec),
            Some(&stack.branch_name),
            InitializationPolicy::AllowUninitialized,
        ) {
            return Ok(vec![rev.oid]);
        }
    }
    if let Ok(range) = arg.parse::<PatchRange>() {
        let patches = parse_patch_ranges(&[range], stack, RangeConstraint::All)?;
        return Ok(patches
            .iter()
            .map(|pn| stack.get_patch_commit(pn).id)
            .collect());
    }
    Err(stack.patch_not_found_error(arg))
}

fn run(matches: &ArgMatches, color: ColorChoice) -> Result<()> {
    let repo = Repository::open()?;
    let branch = matches.get_one::<String>("branch").map(|s| s.as_str());
    let stack = Stack::from_branch(&repo, branch, InitializationPolicy::AllowUninitialized)?;

    let mut oids: Vec<Oid> = Vec::new();
    let mut args: Vec<String> = Vec::new();
    if let Some(v) = matches.get_many::<String>("patchranges") {
        args.extend(v.cloned());
    }
    if let Some(v) = matches.get_many::<String>("patch") {
        args.extend(v.cloned());
    }
    if !args.is_empty() {
        for arg in &args {
            oids.extend(resolve_patch_or_rev(&repo, &stack, arg)?);
        }
    } else if matches.get_flag("applied") || matches.get_flag("unapplied") || matches.get_flag("hidden") {
        if matches.get_flag("applied") {
            oids.extend(stack.applied().iter().map(|pn| stack.get_patch_commit(pn).id));
        }
        if matches.get_flag("unapplied") {
            oids.extend(stack.unapplied().iter().map(|pn| stack.get_patch_commit(pn).id));
        }
        if matches.get_flag("hidden") {
            oids.extend(stack.hidden().iter().map(|pn| stack.get_patch_commit(pn).id));
        }
    } else {
        oids.push(stack.top().id);
    }

    if oids.is_empty() {
        return Ok(());
    }

    let mut git_args: Vec<String> = vec![
        "show".to_string(),
        crate::argset::color_arg_for_git(color),
    ];
    if matches.get_flag("stat") {
        git_args.push("--stat".to_string());
        git_args.push("--summary".to_string());
    }
    git_args.extend(crate::argset::get_diff_opts(matches));
    for oid in &oids {
        git_args.push(oid.to_hex());
    }
    if let Some(paths) = matches.get_many::<OsString>("pathspecs") {
        git_args.push("--".to_string());
        for p in paths {
            git_args.push(p.to_string_lossy().into_owned());
        }
    }
    let _ = anyhow!("");
    crate::argset::run_git_to_stdout(&repo, "show", &git_args)
}
