fn resolve_patch_or_rev(repo: &Repository, stack: &Stack, arg: &str) -> Result<Vec<Oid>> {
    if let Ok(range) = arg.parse::<PatchRange>() {
        if range.is_range() {
            let patches = parse_patch_ranges(&[range], stack, RangeConstraint::All)?;
            return Ok(patches
                .iter()
                .map(|pn| stack.get_patch_commit(pn).id)
                .collect());
        }
        if let Ok(pn) = arg.parse::<PatchName>() {
            if stack.has_patch(&pn) {
                return Ok(vec![stack.get_patch_commit(&pn).id]);
            }
        }
    }
    if let Ok(spec) = arg.parse::<StGitRevision>() {
        if let Ok((_, rev)) = crate::patch::parse_stgit_revision(
            repo,
            Some(&spec),
            Some(&stack.branch_name),
            InitializationPolicy::AllowUninitialized,
        ) {
            return Ok(vec![rev.oid]);
        }
    }
    if let Ok(range) = arg.parse::<PatchRange>() {
        let patches = parse_patch_ranges(&[range], stack, RangeConstraint::All)?;
        return Ok(patches
            .iter()
            .map(|pn| stack.get_patch_commit(pn).id)
            .collect());
    }
    Err(stack.patch_not_found_error(arg))
}

