    make,
    run,
};

#[derive(Debug, Clone)]
struct RangeSpec {
    rev1: Option<StGitRevision>,
    rev2: Option<StGitRevision>,
    is_range: bool,
}

fn parse_range_spec(s: &str) -> Result<RangeSpec, String> {
    let err = |pos: usize| {
        format!(
            "invalid StGit revision `{s}`: {s}\n{}^\n",
            " ".repeat(pos)
        )
    };
    if let Some(pos) = s.find("..") {
        let (a, b) = (&s[..pos], &s[pos + 2..]);
        if b.contains("..") {
            return Err(err(pos + 2 + b.find("..").unwrap()));
        }
        let rev1 = if a.is_empty() {
            None
        } else {
            Some(a.parse::<StGitRevision>().map_err(|_| err(0))?)
        };
        if let Some(r) = &rev1 {
            if !r.suffix.is_empty() {
                return Err(err(r.patch_like.len()));
            }
        }
        let rev2 = if b.is_empty() {
            None
        } else {
            Some(b.parse::<StGitRevision>().map_err(|_| err(pos + 2))?)
        };
        Ok(RangeSpec {
            rev1,
            rev2,
            is_range: true,
        })
    } else {
        let rev1 = s.parse::<StGitRevision>().map_err(|e| {
            let msg = e.to_string();
            msg.trim_start_matches("invalid StGit revision ")
                .to_string()
                .replace(&format!("`{s}`: "), "");
            e.to_string()
        })?;
        Ok(RangeSpec {
            rev1: Some(rev1),
            rev2: None,
            is_range: false,
        })
    }
}

fn make() -> clap::Command {
    clap::Command::new("diff")
        .about("Show a diff")
        .long_about(
            "Show the diff (default) or diffstat between the current working copy or a tree-ish \
             object and another tree-ish object (defaulting to HEAD). File names can also be \
             given to restrict the diff output. The tree-ish object has the format accepted by \
             the 'stg id' command.",
        )
        .arg(
            Arg::new("pathspecs")
                .help("Limit diff to files matching path(s)")
                .value_name("path")
                .num_args(1..)
                .value_parser(clap::value_parser!(OsString))
                .value_hint(ValueHint::AnyPath),
        )
        .arg(
            Arg::new("range")
                .long("range")
                .short('r')
                .help("Show the diff between specified revisions")
                .long_help(
                    "Show diff between specified revisions. Revisions ranges are specified as \
                     'rev1[..[rev2]]'. The revisions may be standard Git revision specifiers or \
                     patches.",
                )
                .value_name("revspec")
                .value_parser(parse_range_spec),
        )
        .arg(
            Arg::new("stat")
                .long("stat")
                .short('s')
                .help("Show the stat instead of the diff")
                .action(ArgAction::SetTrue),
        )
        .arg(crate::argset::diff_opts_arg())
        .arg(crate::argset::color_arg())
}

fn resolve_patch_rev(repo: &Repository, stack: &Stack, spec: &StGitRevision) -> Result<Oid> {
    if spec.patch_like == "{base}" && spec.suffix.is_empty() {
        return Ok(stack.base.tree_id);
    }
    if let Ok(pn) = spec.patch_like.parse::<PatchName>() {
        if spec.suffix.is_empty() && stack.has_patch(&pn) {
            return Ok(stack.get_patch_commit(&pn).tree_id);
        }
    }
    Err(stack.patch_not_found_error(&spec.patch_like))
}

fn run(matches: &ArgMatches, color: ColorChoice) -> Result<()> {
    let repo = Repository::open()?;
    let stack = Stack::from_branch(&repo, None, InitializationPolicy::AllowUninitialized)?;
    let pathspecs: Vec<String> = matches
        .get_many::<OsString>("pathspecs")
        .map(|v| v.map(|p| p.to_string_lossy().into_owned()).collect())
        .unwrap_or_default();
    let diff_opts = crate::argset::get_diff_opts(matches);
    let stat = matches.get_flag("stat");

    let mut args: Vec<String> = vec!["diff".to_string(), crate::argset::color_arg_for_git(color)];
    if stat {
        args.push("--stat".to_string());
        args.push("--summary".to_string());
    }
    args.extend(diff_opts);

    match matches.get_one::<RangeSpec>("range") {
        None => {
            args.push(stack.branch_head.tree_id.to_hex());
        }
        Some(range) if !range.is_range => {
            let spec = range.rev1.as_ref().unwrap();
            let (_, rev) = parse_stgit_revision(
                &repo,
                Some(spec),
                None,
                InitializationPolicy::AllowUninitialized,
            )?;
            let tree = match repo.object_kind(rev.oid)?.as_deref() {
                Some("commit") => repo.find_commit(rev.oid)?.tree_id,
                Some("tree") => rev.oid,
                _ => return Err(anyhow!("revision `{}` is not a tree-ish", rev.oid)),
            };
            args.push(tree.to_hex());
        }
        Some(range) => {
            let tree1 = match &range.rev1 {
                Some(spec) => resolve_patch_rev(&repo, &stack, spec)?,
                None => {
                    let top = stack.top();
                    match top.parent_ids.first() {
                        Some(p) => repo.find_commit(*p)?.tree_id,
                        None => top.tree_id,
                    }
                }
            };
            let tree2 = match &range.rev2 {
                Some(spec) => resolve_patch_rev(&repo, &stack, spec)?,
                None => stack.branch_head.tree_id,
            };
            args.push(tree1.to_hex());
            args.push(tree2.to_hex());
        }
    }
    if !pathspecs.is_empty() {
        args.push("--".to_string());
        args.extend(pathspecs);
    }
    crate::argset::run_git_to_stdout(&repo, "diff", &args)
}
