            let mut args: Vec<String> = vec!["ls-files".into(), "-z".into(), "--full-name".into(), "--".into()];
            args.extend(specs.map(|p| p.to_string_lossy().into_owned()));
            let out = repo.git_output(&args)?;
            // ls-files only lists tracked files; also include deleted paths via diff
            let mut v: Vec<BString> = out
                .stdout
                .split(|b| *b == 0)
                .filter(|f| !f.is_empty())
                .map(BString::from)
                .collect();
            // Include paths touched by any patch matching the pathspec prefix.
            let mut args2: Vec<String> = vec![
                "diff-tree".into(),
                "-r".into(),
                "--name-only".into(),
                "-z".into(),
                stack.base.tree_id.to_hex(),
                stack.top().tree_id.to_hex(),
                "--".into(),
            ];
            args2.extend(matches.get_many::<OsString>("pathspecs").unwrap().map(|p| p.to_string_lossy().into_owned()));
            let mut cmd = repo.git_command();
            cmd.args(&args2);
            cmd.stdout(std::process::Stdio::piped()).stderr(std::process::Stdio::null());
            if let Ok(out2) = cmd.output() {
                for f in out2.stdout.split(|b| *b == 0).filter(|f| !f.is_empty()) {
                    let f = BString::from(f);
                    if !v.contains(&f) {
                        v.push(f);
                    }
                }
            }
            v
        }
        None => {
            let out = repo.git_output(["diff-index", "--name-only", "-z", "HEAD"])?;
            out.stdout
                .split(|b| *b == 0)
                .filter(|f| !f.is_empty())
                .map(BString::from)
                .collect()
        }
    };

    let stupid = repo.stupid();
    let show_diff = matches.get_flag("diff");
    let diff_opts = crate::argset::get_diff_opts(matches);
    let mut stdout = std::io::stdout().lock();
    for pn in stack.applied() {
        let commit = stack.get_patch_commit(pn);
        let parent_tree = repo.find_commit(commit.parent_ids[0])?.tree_id;
        let files = stupid.diff_tree_files(parent_tree, commit.tree_id)?;
        if !files.iter().any(|f| paths.contains(f)) {
            continue;
        }
        if show_diff {
            writeln!(stdout, "{}", "-".repeat(50))?;
            writeln!(stdout, "{pn}")?;
            writeln!(stdout, "{}", "-".repeat(50))?;
            stdout.write_all(&commit.message)?;
            writeln!(stdout, "\n---")?;
            stdout.flush()?;
            let mut args: Vec<String> = vec![
                "diff-tree".to_string(),
                "-p".to_string(),
                crate::argset::color_arg_for_git(color),
            ];
            args.extend(diff_opts.iter().cloned());
            args.push(parent_tree.to_hex());
            args.push(commit.tree_id.to_hex());
            crate::argset::run_git_to_stdout(&repo, "diff-tree", &args)?;
        } else {
            writeln!(stdout, "{pn}")?;
        }
    }
    let _ = PatchName::from_str_lenient;
    Ok(())
}
