{"command":"cat > /workspace/src/cmd/repair.rs <<'EOF'
use std::rc::Rc;

use anyhow::Result;
use clap::ArgMatches;

use super::{CommandCategory, StGitCommand};
use crate::color::ColorChoice;
use crate::git::{Commit, Oid, Repository};
use crate::patch::PatchName;
use crate::stack::{InitializationPolicy, Stack, StackState, TransactionBuilder};
use crate::util::{print_info, print_warning};

pub const STGIT_COMMAND: StGitCommand = StGitCommand {
    name: "repair",
    about: "Repair stack after branch is modified with git commands",
    category: CommandCategory::StackManipulation,
    make,
    run,
};

fn make() -> clap::Command {
    clap::Command::new("repair")
        .about("Repair stack after branch is modified with git commands")
        .long_about(
            "If a branch with a StGit stack is modified with certain git commands such as \
             git-commit(1), git-pull(1), git-merge(1), or git-rebase(1), the StGit stack metadata \
             will become inconsistent with the branch state. There are a few options for \
             resolving this kind of situation:\n\
             \n\
             1. Use 'stg undo' to undo the effect of the git commands. Or similarly use 'stg \
             reset' to reset the stack/branch to any previous stack state.\n\
             \n\
             2. Use `stg repair`. This will repair the StGit stack metadata to accommodate the \
             modifications to the branch made by the git commands. Specifically, it will do the \
             following:\n\
             \n\
             - If regular git commits were made on top of the stack of StGit patches (i.e. by \
             using plain `git commit`), `stg repair` will convert those commits to StGit \
             patches, preserving their content.\n\
             \n\
             - However, merge commits cannot become patches. So if a merge was committed on top \
             of the stack, `stg repair` will mark all patches below the merge commit as \
             unapplied, since they are no longer reachable. An alternative when this is not the \
             desired behavior is to use `stg undo` to first get rid of the offending merge and \
             then run `stg repair` again.\n\
             \n\
             - The applied patches are supposed to be precisely those that are reachable from \
             the branch head. If, for example, git-reset(1) was used to move the head, some \
             applied patches may no longer be reachable and some unapplied patches may have \
             become reachable. In this case, `stg repair` will correct the applied/unapplied \
             state of such patches.\n\
             \n\
             `stg repair` will repair these inconsistencies reliably, so there are valid \
             workflows where git commands are used followed by `stg repair`. For example, new \
             patches can be created by first making commits with a graphical commit tool and \
             then running `stg repair` to convert those commits into patches.",
        )
        .arg(crate::argset::color_arg())
}

fn run(_matches: &ArgMatches, color: ColorChoice) -> Result<()> {
    let repo = Repository::open()?;
    let stack = Stack::from_branch(&repo, None, InitializationPolicy::RequireInitialized)?;
    stack.check_protected()?;

    let head = stack.branch_head.clone();
    if head.id == stack.state.head.id {
        // Nothing to repair.
        TransactionBuilder::new(stack, color)
            .use_index_and_worktree(false)
            .allow_bad_head(true)
            .transact(|trans| {
                trans.set_reflog_msg("repair");
                Ok(())
            })?;
        return Ok(());
    }

    // Map commit ids to patch names.
    let patch_of = |oid: Oid, stack: &Stack| -> Option<PatchName> {
        stack.patch_for_commit(oid).cloned()
    };

    // Walk first parents from HEAD.
    let mut new_commits: Vec<Rc<Commit>> = Vec::new();
    let mut reachable: Vec<PatchName> = Vec::new();
    let mut current = head.clone();
    let mut merge_commit: Option<Oid> = None;
    let mut hit_patch = false;
    loop {
        if let Some(pn) = patch_of(current.id, &stack) {
            hit_patch = true;
            reachable.push(pn);
            match current.parent_ids.first() {
                Some(p) => current = repo.find_commit(*p)?,
                None => break,
            }
            continue;
        }
        if hit_patch {
            // Below the patches: reached the (new) base.
            break;
        }
        if current.id == stack.base.id {
            break;
        }
        if current.parent_ids.len() > 1 {
            merge_commit = Some(current.id);
            break;
        }
        if current.parent_ids.is_empty() {
            break;
        }
        new_commits.push(current.clone());
        current = repo.find_commit(current.parent_ids[0])?;
    }
    reachable.reverse();

    if let Some(merge) = merge_commit {
        let n = stack.applied().len();
        if n > 0 {
            print_warning(
                &format!(
                    "{n} {} hidden below the merge commit {merge} and will be considered unapplied",
                    if n == 1 { "patch is" } else { "patches are" }
                ),
                color,
            );
        }
        reachable.clear();
        new_commits.clear();
    }

    // Determine new applied/unapplied lists.
    let old_applied: Vec<PatchName> = stack.applied().to_vec();
    let old_unapplied: Vec<PatchName> = stack.unapplied().to_vec();
    let mut unapplied: Vec<PatchName> = Vec::new();
    for pn in &old_applied {
        if !reachable.contains(pn) {
            print_info(&format!("`{pn}` is now unapplied"), color);
            unapplied.push(pn.clone());
        }
    }
    for pn in &reachable {
        if !old_applied.contains(pn) {
            print_info(&format!("`{pn}` is now applied"), color);
        }
    }
    for pn in &old_unapplied {
        if !reachable.contains(pn) {
            unapplied.push(pn.clone());
        }
    }

    // Record the external modifications.
    let state = StackState {
        prev: None,
        head: head.clone(),
        applied: reachable.clone(),
        unapplied: unapplied.clone(),
        hidden: stack.hidden().to_vec(),
        patches: stack.state.patches.clone(),
    };
    let mut stack = stack;
    let prev_log = stack.ensure_log_id()?;
    let committer = crate::signature::Signature::default_committer(&repo.config)?;
    let author = crate::signature::Signature::default_author(&repo.config)?;
    let mut state_with_prev = state.clone();
    state_with_prev.prev = Some(prev_log);
    let log_id = state_with_prev.commit(
        &repo,
        Some(prev_log),
        "external modifications",
        &author,
        &committer,
    )?;
    repo.update_ref(&stack.get_stack_refname(), log_id, "external modifications")?;
    stack.log_id = Some(log_id);
    stack.state = state_with_prev;
    stack.base = stack.state.base(&repo)?;

    // Convert new commits into patches.
    new_commits.reverse(); // oldest first
    if !new_commits.is_empty() {
        let n = new_commits.len();
        print_info(
            &format!("Creating {n} new {}", if n == 1 { "patch" } else { "patches" }),
            color,
        );
    }
    let len_limit = repo
        .config
        .get_i64("stgit.namelength")
        .map(|n| n.max(0) as usize)
        .unwrap_or(30);
    let mut taken: Vec<PatchName> = stack.all_patches().cloned().collect();
    let mut new_patches: Vec<(PatchName, Rc<Commit>)> = Vec::new();
    for commit in &new_commits {
        let pn = PatchName::make(&commit.summary_str(), true, Some(len_limit))
            .uniquify(|p| taken.iter().any(|t| t.collides(p)));
        taken.push(pn.clone());
        new_patches.push((pn, commit.clone()));
    }

    TransactionBuilder::new(stack, color)
        .use_index_and_worktree(false)
        .allow_bad_head(true)
        .transact(|trans| {
            trans.set_reflog_msg("repair");
            for (pn, commit) in &new_patches {
                trans.new_applied(pn, commit.clone())?;
            }
            Ok(())
        })?;
    Ok(())
}
