        print_info(
            &format!("Creating {n} new {}", if n == 1 { "patch" } else { "patches" }),
            color,
        );
    }
    let len_limit = repo
        .config
        .get_i64("stgit.namelength")
        .map(|n| n.max(0) as usize)
        .unwrap_or(30);
    let mut taken: Vec<PatchName> = stack.all_patches().cloned().collect();
    let mut new_patches: Vec<(PatchName, Rc<Commit>)> = Vec::new();
    for commit in &new_commits {
        let pn = PatchName::make(&commit.summary_str(), true, Some(len_limit))
            .uniquify(|p| taken.iter().any(|t| t.collides(p)));
        taken.push(pn.clone());
        new_patches.push((pn, commit.clone()));
    }

    TransactionBuilder::new(stack, color)
        .use_index_and_worktree(false)
        .allow_bad_head(true)
        .transact(|trans| {
            trans.set_reflog_msg("repair");
            for (pn, commit) in &new_patches {
                trans.new_applied(pn, commit.clone())?;
            }
            Ok(())
        })?;
    Ok(())
}
