#[derive(Debug, Clone, PartialEq, Eq)]
pub enum BranchLocator {
    Name(String),
    PrevCheckout(usize),
}

fn parse_branch_locator(s: &str) -> Result<BranchLocator, String> {
    if s == "-" {
        return Ok(BranchLocator::PrevCheckout(1));
    }
    if let Some(inner) = s.strip_prefix("@{").and_then(|r| r.strip_suffix('}')) {
        if let Some(n) = inner.strip_prefix('-') {
            if let Ok(n) = n.parse::<usize>() {
                if n > 0 {
                    return Ok(BranchLocator::PrevCheckout(n));
                }
            }
        }
        return Err(format!("invalid branch locator `{s}`"));
    }
    validate_branch_name(s)?;
    Ok(BranchLocator::Name(s.to_string()))
}

fn validate_branch_name(s: &str) -> Result<(), String> {
    let bad = |pos: usize| format!("{s}\n{}^\n", " ".repeat(pos));
    if s.is_empty() {
        return Err(bad(0));
    }
    let bytes = s.as_bytes();
    for (i, c) in s.char_indices() {
        if c == '/' && (i == 0 || i + 1 == s.len()) {
            return Err(bad(i));
        }
        if c == '.' && i + 1 < s.len() && bytes[i + 1] == b'.' {
            return Err(bad(i));
        }
        if c == '.' && (i == 0 || bytes[i - 1] == b'/') {
            return Err(bad(i));
        }
        if c.is_whitespace() || matches!(c, '~' | '^' | ':' | '?' | '*' | '[' | '\\') || (c as u32) < 0x20 {
            return Err(bad(i));
        }
        if c == '@' && i + 1 < s.len() && bytes[i + 1] == b'{' {
            return Err(bad(i));
        }
        if c == '/' && i + 1 < s.len() && bytes[i + 1] == b'/' {
            return Err(bad(i));
        }
    }
    if s.ends_with(".lock") || s.ends_with('.') || s == "@" {
        return Err(bad(s.len() - 1));
    }
    Ok(())
}

fn parse_new_branch_name(s: &str) -> Result<String, String> {
    validate_branch_name(s)?;
    Ok(s.to_string())
}

