fn branch_exists(repo: &Repository, name: &str) -> Result<bool> {
    Ok(repo.get_ref(&format!("refs/heads/{name}"))?.is_some())
}

fn require_branch(repo: &Repository, name: &str) -> Result<()> {
    if branch_exists(repo, name)? {
        Ok(())
    } else {
        Err(anyhow!("branch `{name}` not found"))
    }
}

fn set_config(repo: &Repository, key: &str, value: &str) -> Result<()> {
    let out = repo.git_output(["config", key, value])?;
    if !out.success() {
        return Err(crate::git::repo_git_error("git config", &out));
    }
    Ok(())
}

fn unset_config(repo: &Repository, key: &str) -> Result<()> {
    let _ = repo.git_output(["config", "--unset", key])?;
    Ok(())
}

fn remove_config_section(repo: &Repository, section: &str) -> Result<()> {
    let _ = repo.git_output(["config", "--remove-section", section])?;
    Ok(())
}

fn resolve_branch_locator(repo: &Repository, loc: &BranchLocator) -> Result<String> {
    match loc {
        BranchLocator::Name(name) => Ok(name.clone()),
        BranchLocator::PrevCheckout(n) => {
            let out = repo.git_output(["rev-parse", "--symbolic-full-name", &format!("@{{-{n}}}")])?;
            let name = out.stdout_str().trim().to_string();
            if out.success() {
                if let Some(short) = name.strip_prefix("refs/heads/") {
                    return Ok(short.to_string());
                }
            }
            Err(anyhow!("`@{{-{n}}}` does not refer to a local branch"))
        }
    }
}

fn current_branch(repo: &Repository) -> Result<Option<String>> {
    Ok(repo
        .head_symbolic()?
        .and_then(|r| r.strip_prefix("refs/heads/").map(|s| s.to_string())))
}

fn run(matches: &ArgMatches, color: ColorChoice) -> Result<()> {
    let repo = Repository::open()?;
    match matches.subcommand() {
        Some(("--list", _)) => list(&repo, color),
        Some(("--create", m)) => create(&repo, m, color),
        Some(("--clone", m)) => clone(&repo, m, color),
        Some(("--rename", m)) => rename(&repo, m),
        Some(("--protect", m)) => protect(&repo, m, true),
        Some(("--unprotect", m)) => protect(&repo, m, false),
        Some(("--delete", m)) => delete(&repo, m, color),
        Some(("--cleanup", m)) => cleanup(&repo, m, color),
        Some(("--describe", m)) => describe(&repo, m),
        _ => {
            if let Some(loc) = matches.get_one::<BranchLocator>("branch") {
                let name = resolve_branch_locator(&repo, loc)?;
                switch(&repo, &name, matches.get_flag("merge"), color)
            } else {
                if let Some(name) = current_branch(&repo)? {
                    println!("{name}");
                }
                Ok(())
            }
        }
    }
}

fn list(repo: &Repository, color: ColorChoice) -> Result<()> {
    let refs = repo.list_refs("refs/heads/")?;
    let mut names: Vec<String> = refs
        .iter()
        .filter_map(|(r, _)| r.strip_prefix("refs/heads/").map(|s| s.to_string()))
        .collect();
    names.sort();
    let current = current_branch(repo)?;
    let stacks: Vec<String> = repo
        .list_refs("refs/stacks/")?
        .iter()
        .filter_map(|(r, _)| r.strip_prefix("refs/stacks/").map(|s| s.to_string()))
        .collect();
    let width = names.iter().map(|n| n.len()).max().unwrap_or(0);
    let mut stdout = crate::color::stdout(color);
    for name in &names {
        let is_current = current.as_deref() == Some(name.as_str());
        let has_stack = stacks.contains(name);
        let protected = repo
            .config
            .get_bool(&format!("branch.{name}.stgit.protect"))
            .unwrap_or(false);
        let desc = repo
            .config
            .get(&format!("branch.{name}.description"))
            .unwrap_or("")
            .to_string();
        let spec = ColorSpec::new();
        stdout.set_color(&spec)?;
        write!(stdout, "{}", if is_current { "> " } else { "  " })?;
        stdout.reset()?;
        let mut spec = ColorSpec::new();
        spec.set_fg(Some(Color::Cyan));
        stdout.set_color(&spec)?;
        write!(stdout, "{}", if has_stack { "s" } else { " " })?;
        stdout.reset()?;
        let mut spec = ColorSpec::new();
        spec.set_fg(Some(Color::Yellow));
        stdout.set_color(&spec)?;
        write!(stdout, "{}", if protected { "p" } else { " " })?;
        stdout.reset()?;
        write!(stdout, "\t")?;
        let mut spec = ColorSpec::new();
        if is_current {
            spec.set_fg(Some(Color::Green));
        }
        stdout.set_color(&spec)?;
        write!(stdout, "{name}")?;
        stdout.reset()?;
        let mut spec = ColorSpec::new();
        spec.set_dimmed(true);
        stdout.set_color(&spec)?;
        write!(stdout, "{}  |", " ".repeat(width - name.len()))?;
        if !desc.is_empty() {
            write!(stdout, " {desc}")?;
        }
        stdout.reset()?;
        writeln!(stdout)?;
    }
    stdout.flush()?;
    Ok(())
}

fn check_worktree_clean(repo: &Repository) -> Result<()> {
    let stupid = repo.stupid();
    if stupid.worktree_differs_from_index()? {
        return Err(anyhow!("worktree not clean; use `refresh` or `reset --hard`"));
    }
    Ok(())
}

fn switch(repo: &Repository, name: &str, merge: bool, _color: ColorChoice) -> Result<()> {
    if current_branch(repo)?.as_deref() == Some(name) {
        return Err(anyhow!("{name} is already the current branch"));
    }
    require_branch(repo, name)?;
    if !merge {
        check_worktree_clean(repo)?;
    }
    let out = repo.git_output(["checkout", name])?;
    if !out.success() {
        return Err(crate::git::repo_git_error("git checkout", &out));
    }
    Ok(())
}

fn record_parent(repo: &Repository, new_branch: &str, parent: Option<&str>, color: ColorChoice) -> Result<()> {
    if let Some(parent) = parent {
        set_config(repo, &format!("branch.{new_branch}.stgit.parentbranch"), parent)?;
        let remote = repo.config.get(&format!("branch.{parent}.remote")).map(|s| s.to_string());
        let merge = repo.config.get(&format!("branch.{parent}.merge")).map(|s| s.to_string());
        if let (Some(remote), Some(merge)) = (remote, merge) {
            set_config(repo, &format!("branch.{new_branch}.remote"), &remote)?;
            set_config(repo, &format!("branch.{new_branch}.merge"), &merge)?;
            print_info(&format!("Recording `{remote}/{merge}` as remote branch"), color);
            return Ok(());
        }
    }
    print_info("Recording as a local branch", color);
    Ok(())
}

fn create(repo: &Repository, matches: &ArgMatches, color: ColorChoice) -> Result<()> {
    let new_branch = matches.get_one::<String>("new-branch").unwrap();
    if branch_exists(repo, new_branch)? {
        return Err(anyhow!("branch `{new_branch}` already exists"));
    }
    let current = current_branch(repo)?;
    let (target, parent): (Oid, Option<String>) = match matches.get_one::<String>("committish") {
        Some(committish) => {
            let parent = if branch_exists(repo, committish)? {
                print_info(&format!("Recording `{committish}` as parent branch"), color);
                Some(committish.clone())
            } else {
                print_info(
                    &format!("Do not know how to determine parent branch from `{committish}`"),
                    color,
                );
                None
            };
            let oid = repo
                .rev_parse_commit(committish)?
                .ok_or_else(|| anyhow!("patch `{committish}` does not exist"))?;
            (oid, parent)
        }
        None => {
            let head = repo
                .head_oid()?
                .ok_or_else(|| anyhow!("HEAD is unborn"))?;
            (head, current.clone())
        }
    };
    // Create the branch and switch to it.
    let out = repo.git_output(["checkout", "-b", new_branch, &target.to_hex()])?;
    if !out.success() {
        return Err(crate::git::repo_git_error("git checkout", &out));
    }
    record_parent(repo, new_branch, parent.as_deref(), color)?;
    // Initialize the stack.
    let repo2 = Repository::open()?;
    let mut stack = Stack::from_branch(&repo2, Some(new_branch), InitializationPolicy::AllowUninitialized)?;
    if !stack.is_initialized {
        stack.initialize()?;
    }
    Ok(())
}

fn clone(repo: &Repository, matches: &ArgMatches, color: ColorChoice) -> Result<()> {
    let current = current_branch(repo)?.ok_or_else(|| anyhow!("not on branch, HEAD is detached"))?;
    let new_branch = match matches.get_one::<String>("new-branch") {
        Some(n) => n.clone(),
        None => {
            let now = crate::signature::Time::now();
            let (y, m, d, hh, mm, ss) = civil(&now);
            format!("{current}-{y:04}{m:02}{d:02}-{hh:02}{mm:02}{ss:02}")
        }
    };
    if branch_exists(repo, &new_branch)? {
        return Err(anyhow!("branch `{new_branch}` already exists"));
    }
    let stack = Stack::from_branch(repo, Some(&current), InitializationPolicy::AllowUninitialized)?;
    let head = stack.branch_head.id;
    // Create the branch ref.
    repo.update_ref(&format!("refs/heads/{new_branch}"), head, "clone")?;
    if stack.is_initialized {
        // Copy the stack state.
        let mut state: StackState = stack.state.clone();
        state.prev = None;
        let committer = crate::signature::Signature::default_committer(&repo.config)?;
        let author = crate::signature::Signature::default_author(&repo.config)?;
        let log_id = state.commit(repo, None, &format!("clone from {current}"), &author, &committer)?;
        repo.update_ref(&format!("refs/stacks/{new_branch}"), log_id, "clone")?;
        for pn in stack.all_patches() {
            repo.update_ref(
                &format!("refs/patches/{new_branch}/{pn}"),
                stack.get_patch_commit(pn).id,
                "clone",
            )?;
        }
    }
    // Copy parent info.
    if let Some(parent) = repo.config.get(&format!("branch.{current}.stgit.parentbranch")) {
        set_config(repo, &format!("branch.{new_branch}.stgit.parentbranch"), parent)?;
    } else {
        set_config(repo, &format!("branch.{new_branch}.stgit.parentbranch"), &current)?;
    }
    if let Some(remote) = repo.config.get(&format!("branch.{current}.remote")) {
        set_config(repo, &format!("branch.{new_branch}.remote"), remote)?;
    }
    if let Some(merge) = repo.config.get(&format!("branch.{current}.merge")) {
        set_config(repo, &format!("branch.{new_branch}.merge"), merge)?;
    }
    set_config(
        repo,
        &format!("branch.{new_branch}.description"),
        &format!("clone of {current}"),
    )?;
    let out = repo.git_output(["checkout", &new_branch])?;
    if !out.success() {
        return Err(crate::git::repo_git_error("git checkout", &out));
    }
    let _ = color;
    Ok(())
}

fn civil(t: &crate::signature::Time) -> (i64, u32, u32, u32, u32, u32) {
    let iso = t.to_iso(); // "YYYY-MM-DD HH:MM:SS +ZZZZ"
    let y: i64 = iso[0..4].parse().unwrap_or(1970);
    let m: u32 = iso[5..7].parse().unwrap_or(1);
    let d: u32 = iso[8..10].parse().unwrap_or(1);
    let hh: u32 = iso[11..13].parse().unwrap_or(0);
    let mm: u32 = iso[14..16].parse().unwrap_or(0);
    let ss: u32 = iso[17..19].parse().unwrap_or(0);
    (y, m, d, hh, mm, ss)
}

fn rename(repo: &Repository, matches: &ArgMatches) -> Result<()> {
    let args: Vec<&String> = matches.get_many::<String>("branch-any").unwrap().collect();
    let (old_name, new_name) = if args.len() == 2 {
        (args[0].clone(), args[1].clone())
    } else {
        let cur = current_branch(repo)?.ok_or_else(|| anyhow!("not on branch, HEAD is detached"))?;
        (cur, args[0].clone())
    };
    validate_branch_name(&new_name).map_err(|e| anyhow!("invalid branch name `{new_name}`: {e}"))?;
    require_branch(repo, &old_name)?;
    if branch_exists(repo, &new_name)? {
        return Err(anyhow!("branch `{new_name}` already exists"));
    }
    let out = repo.git_output(["branch", "-m", &old_name, &new_name])?;
    if !out.success() {
        return Err(crate::git::repo_git_error("git branch", &out));
    }
    // Rename stack ref and patch refs.
    if let Some(oid) = repo.get_ref(&format!("refs/stacks/{old_name}"))? {
        repo.update_ref(&format!("refs/stacks/{new_name}"), oid, "rename")?;
        repo.delete_ref(&format!("refs/stacks/{old_name}"))?;
    }
    for (refname, oid) in repo.list_refs(&format!("refs/patches/{old_name}/"))? {
        let suffix = refname
            .strip_prefix(&format!("refs/patches/{old_name}/"))
            .unwrap()
            .to_string();
        repo.update_ref(&format!("refs/patches/{new_name}/{suffix}"), oid, "rename")?;
        repo.delete_ref(&refname)?;
    }
    // Update parentbranch references of other branches.
    for (key, value) in repo.config.entries_with_prefix("branch.") {
        if key.ends_with(".stgit.parentbranch") && value == Some(old_name.as_str()) {
            set_config(repo, key, &new_name)?;
        }
    }
    Ok(())
}

fn protect(repo: &Repository, matches: &ArgMatches, protect: bool) -> Result<()> {
    let name = match matches.get_one::<String>("branch") {
        Some(n) => n.clone(),
        None => current_branch(repo)?.ok_or_else(|| anyhow!("not on branch, HEAD is detached"))?,
    };
    require_branch(repo, &name)?;
    let stack = Stack::from_branch(repo, Some(&name), InitializationPolicy::RequireInitialized)?;
    let _ = stack;
    if protect {
        set_config(repo, &format!("branch.{name}.stgit.protect"), "true")?;
    } else {
        unset_config(repo, &format!("branch.{name}.stgit.protect"))?;
    }
    Ok(())
}

fn delete(repo: &Repository, matches: &ArgMatches, color: ColorChoice) -> Result<()> {
    let force = matches.get_flag("force");
    let current = current_branch(repo)?;
    let name = match matches.get_one::<String>("branch") {
        Some(n) => n.clone(),
        None => current.clone().ok_or_else(|| anyhow!("not on branch, HEAD is detached"))?,
    };
    let is_current = current.as_deref() == Some(name.as_str());
    let parent = repo
        .config
        .get(&format!("branch.{name}.stgit.parentbranch"))
        .map(|s| s.to_string());
    if is_current && parent.is_none() {
        return Err(anyhow!(
            "cannot delete the current branch without a known parent branch"
        ));
    }
    require_branch(repo, &name)?;
    let stack = Stack::from_branch(repo, Some(&name), InitializationPolicy::AllowUninitialized)?;
    if stack.is_initialized {
        if stack.is_protected() {
            return Err(anyhow!("delete not permitted: this branch is protected"));
        }
        if stack.all_patches().next().is_some() && !force {
            return Err(anyhow!(
                "delete not permitted: the series still contains patches (override with --force)"
            ));
        }
    }
    if is_current {
        check_worktree_clean(repo)?;
        let parent = parent.unwrap();
        let out = repo.git_output(["checkout", &parent])?;
        if !out.success() {
            return Err(crate::git::repo_git_error("git checkout", &out));
        }
    }
    remove_stack_refs(repo, &name)?;
    let out = repo.git_output(["branch", "-D", &name])?;
    if !out.success() {
        return Err(crate::git::repo_git_error("git branch", &out));
    }
    remove_config_section(repo, &format!("branch.{name}"))?;
    let _ = color;
    Ok(())
}

fn remove_stack_refs(repo: &Repository, name: &str) -> Result<()> {
    if repo.get_ref(&format!("refs/stacks/{name}"))?.is_some() {
        repo.delete_ref(&format!("refs/stacks/{name}"))?;
    }
    for (refname, _) in repo.list_refs(&format!("refs/patches/{name}/"))? {
        repo.delete_ref(&refname)?;
    }
    Ok(())
}

fn cleanup(repo: &Repository, matches: &ArgMatches, color: ColorChoice) -> Result<()> {
    let force = matches.get_flag("force");
    let name = match matches.get_one::<String>("branch") {
        Some(n) => n.clone(),
        None => current_branch(repo)?.ok_or_else(|| anyhow!("not on branch, HEAD is detached"))?,
    };
    require_branch(repo, &name)?;
    let stack = Stack::from_branch(repo, Some(&name), InitializationPolicy::RequireInitialized)?;
    if stack.is_protected() {
        return Err(anyhow!("clean up not permitted: this branch is protected"));
    }
    if stack.all_patches().next().is_some() && !force {
        return Err(anyhow!(
            "clean up not permitted: the series still contains patches (override with --force)"
        ));
    }
    remove_stack_refs(repo, &name)?;
    remove_config_section(repo, &format!("branch.{name}.stgit"))?;
    let _ = color;
    Ok(())
}

fn describe(repo: &Repository, matches: &ArgMatches) -> Result<()> {
    let desc = matches.get_one::<String>("description").unwrap();
    let name = match matches.get_one::<String>("branch") {
        Some(n) => n.clone(),
        None => current_branch(repo)?.ok_or_else(|| anyhow!("not on branch, HEAD is detached"))?,
    };
    require_branch(repo, &name)?;
    if desc.is_empty() {
        unset_config(repo, &format!("branch.{name}.description"))?;
    } else {
        set_config(repo, &format!("branch.{name}.description"), desc)?;
    }
    Ok(())
}
