use std::io::Write;
use std::path::PathBuf;

use anyhow::{anyhow, Result};
use bstr::ByteSlice;
use clap::{Arg, ArgAction, ArgMatches, ValueHint};

use super::{CommandCategory, StGitCommand};
use crate::color::ColorChoice;
use crate::git::{Commit, Repository};
use crate::patch::range::get_ranges;
use crate::patch::{parse_patch_ranges, patch_range_arg_optional, PatchName, RangeConstraint};
use crate::stack::{InitializationPolicy, Stack};

pub const STGIT_COMMAND: StGitCommand = StGitCommand {
    name: "export",
    about: "Export patches to a directory",
    category: CommandCategory::StackInspection,
    make,
    run,
};

const DEFAULT_TEMPLATE: &str = "%(shortdescr)s\n\nFrom: %(authname)s <%(authemail)s>\n\n%(longdescr)s\n---\n%(diffstat)s\n";

fn make() -> clap::Command {
    clap::Command::new("export")
        .about("Export patches to a directory")
        .long_about(
            "Export a range of patches to a given directory in unified diff format. All applied \
             patches are exported by default.\n\
             \n\
             Patches are exported to 'patches-<branch>' by default. The '--dir' option may be \
             used to specify a different output directory.\n\
             \n\
             The patch file output may be customized via a template file found at \
             \"$GIT_DIR/patchexport.tmpl\", \"~/.stgit/templates/patchexport.tmpl\", or \
             \"$(prefix)/share/stgit/templates\". The following variables are supported in the \
             template file:\n\
             \n    \
             %(description)s - patch description\n    \
             %(shortdescr)s  - the first line of the patch description\n    \
             %(longdescr)s   - the rest of the patch description, after the first line\n    \
             %(diffstat)s    - the diff statistics\n    \
             %(authname)s    - author name\n    \
             %(authemail)s   - author email\n    \
             %(authdate)s    - patch creation date (ISO-8601 format)\n    \
             %(commname)s    - committer name\n    \
             %(commemail)s   - committer email",
        )
        .arg(
            patch_range_arg_optional()
                .help("Patches to export")
                .long_help(
                    "Patches to export.\n\
                     \n\
                     A patch name or patch range of the form '[begin-patch]..[end-patch]' may be \
                     specified.",
                ),
        )
        .arg(crate::argset::branch_arg())
        .arg(
            Arg::new("dir")
                .long("dir")
                .short('d')
                .help("Export patches to <dir> instead of the default")
                .value_name("dir")
                .value_hint(ValueHint::DirPath)
                .value_parser(clap::value_parser!(PathBuf)),
        )
        .arg(
            Arg::new("patch")
                .long("patch")
                .short('p')
                .help("Suffix patch file names with \".patch\"")
                .action(ArgAction::SetTrue)
                .conflicts_with("extension"),
        )
        .arg(
            Arg::new("extension")
                .long("extension")
                .short('e')
                .help("Suffix patch file names with \".<ext>\"")
                .value_name("ext"),
        )
        .arg(
            Arg::new("numbered")
                .long("numbered")
                .short('n')
                .help("Prefix patch file names with order numbers.")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("template")
                .long("template")
                .short('t')
                .help("Use <file> as template")
                .value_name("file")
                .value_hint(ValueHint::FilePath)
                .value_parser(clap::value_parser!(PathBuf)),
        )
        .arg(
            Arg::new("stdout")
                .long("stdout")
                .short('s')
                .help("Export to stdout instead of directory")
                .action(ArgAction::SetTrue)
                .conflicts_with("dir"),
        )
        .arg(crate::argset::diff_opts_arg())
        .arg(crate::argset::color_arg())
}

fn read_template(repo: &Repository, path: Option<&PathBuf>) -> Result<String> {
    if let Some(p) = path {
        return std::fs::read_to_string(p).map_err(|e| anyhow!("{e}"));
    }
    let candidates = [
        repo.git_dir.join("patchexport.tmpl"),
        std::env::var_os("HOME")
            .map(PathBuf::from)
            .unwrap_or_default()
            .join(".stgit")
            .join("templates")
            .join("patchexport.tmpl"),
    ];
    for c in candidates {
        if let Ok(s) = std::fs::read_to_string(&c) {
            return Ok(s);
        }
    }
    Ok(DEFAULT_TEMPLATE.to_string())
}

pub fn diffstat(repo: &Repository, diff: &[u8]) -> Result<String> {
    if diff.is_empty() {
        return Ok(String::new());
    }
    let out = repo.git_output_with_input(["apply", "--stat", "--summary"], diff)?;
    if !out.success() {
        return Err(crate::git::repo_git_error("git apply", &out));
    }
    Ok(out.stdout_str())
}

pub fn expand_template(template: &str, repo: &Repository, commit: &Commit, diff: &[u8]) -> Result<String> {
    let message = commit.message_str().into_owned();
    let trimmed = message.trim_start_matches('\n');
    let (shortdescr, longdescr) = match trimmed.find('\n') {
        Some(pos) => {
            let short = &trimmed[..pos];
            let long = trimmed[pos + 1..].trim_start_matches('\n');
            (short.to_string(), long.trim_end_matches('\n').to_string())
        }
        None => (trimmed.trim_end_matches('\n').to_string(), String::new()),
    };
    let stat = diffstat(repo, diff)?;
    let mut out = String::new();
    let mut rest = template;
    while let Some(pos) = rest.find("%(") {
        out.push_str(&rest[..pos]);
        let after = &rest[pos + 2..];
        match after.find(")s") {
            Some(end) => {
                let key = &after[..end];
                let value: String = match key {
                    "description" => message.clone(),
                    "shortdescr" => shortdescr.clone(),
                    "longdescr" => longdescr.clone(),
                    "diffstat" => stat.clone(),
                    "authname" => commit.author.name.to_str_lossy().into_owned(),
                    "authemail" => commit.author.email.to_str_lossy().into_owned(),
                    "authdate" => commit.author.time.to_iso(),
                    "commname" => commit.committer.name.to_str_lossy().into_owned(),
                    "commemail" => commit.committer.email.to_str_lossy().into_owned(),
                    _ => format!("%({key})s"),
                };
                out.push_str(&value);
                rest = &after[end + 2..];
            }
            None => {
                out.push_str("%(");
                rest = after;
            }
        }
    }
    out.push_str(rest);
    Ok(out)
}

fn run(matches: &ArgMatches, _color: ColorChoice) -> Result<()> {
    let repo = Repository::open()?;
    let branch = matches.get_one::<String>("branch").map(|s| s.as_str());
    let stack = Stack::from_branch(&repo, branch, InitializationPolicy::AllowUninitialized)?;
    let ranges = get_ranges(matches, "patchranges");
    let patches: Vec<PatchName> = if ranges.is_empty() {
        if stack.applied().is_empty() {
            return Err(anyhow!("no patches applied"));
        }
        stack.applied().to_vec()
    } else {
        parse_patch_ranges(&ranges, &stack, RangeConstraint::All)?
    };

    let template = read_template(&repo, matches.get_one::<PathBuf>("template"))?;
    let to_stdout = matches.get_flag("stdout");
    let numbered = matches.get_flag("numbered");
    let extension: Option<String> = if matches.get_flag("patch") {
        Some("patch".to_string())
    } else {
        matches.get_one::<String>("extension").cloned()
    };
    let diff_opts = crate::argset::get_diff_opts(matches);

    let dir = match matches.get_one::<PathBuf>("dir") {
        Some(d) => d.clone(),
        None => PathBuf::from(format!("patches-{}", stack.branch_name)),
    };
    if !to_stdout {
        if dir.exists() && !dir.is_dir() {
            return Err(anyhow!(
                "creating \"{}\": File exists (os error 17)",
                dir.display()
            ));
        }
        std::fs::create_dir_all(&dir).map_err(|e| anyhow!("creating \"{}\": {e}", dir.display()))?;
    }

    let width = std::cmp::max(2, patches.len().to_string().len());
    let mut series_lines: Vec<String> = Vec::new();
    let stupid = repo.stupid();
    let mut stdout = std::io::stdout().lock();
    for (i, pn) in patches.iter().enumerate() {
        let commit = stack.get_patch_commit(pn);
        let parent_tree = repo.find_commit(commit.parent_ids[0])?.tree_id;
        let diff = stupid.diff_tree_patch(parent_tree, commit.tree_id, None::<Vec<&str>>, false, &diff_opts)?;
        let plain_diff = if diff_opts.is_empty() {
            diff.clone()
        } else {
            stupid.diff_tree_patch(parent_tree, commit.tree_id, None::<Vec<&str>>, false, &[])?
        };
        let header = expand_template(&template, &repo, commit, &plain_diff)?;
        let mut content: Vec<u8> = header.into_bytes();
        content.extend_from_slice(&diff);
        if to_stdout {
            stdout.write_all(&content)?;
        } else {
            let mut name = String::new();
            if numbered {
                name.push_str(&format!("{:0width$}-", i + 1));
            }
            name.push_str(pn.as_str());
            if let Some(ext) = &extension {
                name.push('.');
                name.push_str(ext);
            }
            std::fs::write(dir.join(&name), &content)?;
            series_lines.push(name);
        }
    }
    if !to_stdout {
        let mut series = format!(
            "# This series applies on Git commit {}\n",
            stack.get_patch_commit(&patches[0]).parent_ids[0]
        );
        for l in series_lines {
            series.push_str(&l);
            series.push('\n');
        }
        std::fs::write(dir.join("series"), series)?;
    }
    stdout.flush()?;
    Ok(())
}
