/// A parsed patch ready to be imported.
struct ImportPatch {
    name: Option<PatchName>,
    message: String,
    author_name: Option<String>,
    author_email: Option<String>,
    author_date: Option<Time>,
    diff: Vec<u8>,
}

fn is_mail_like(data: &[u8]) -> bool {
    let first = data.lines().next().unwrap_or(b"");
    first.starts_with(b"From ")
        || first.starts_with(b"From: ")
        || first.starts_with(b"Subject: ")
        || first.starts_with(b"Date: ")
        || first.starts_with(b"Return-Path: ")
        || first.starts_with(b"Received: ")
}

/// Split a plain patch file into description and diff.
fn parse_plain(data: &[u8]) -> ImportPatch {
    let mut desc_lines: Vec<&[u8]> = Vec::new();
    let mut diff_start: Option<usize> = None;
    let mut pos = 0;
    for line in data.lines_with_terminator() {
        let l = line.trim_end_with(|c| c == '\n' || c == '\r');
        if l == b"---"
            || l.starts_with(b"--- ")
            || l.starts_with(b"diff -")
            || l.starts_with(b"Index: ")
        {
            diff_start = Some(pos);
            break;
        }
        desc_lines.push(l);
        pos += line.len();
    }
    let rest: &[u8] = match diff_start {
        Some(p) => &data[p..],
        None => &data[data.len()..],
    };
    // The diff proper starts at the first "diff " or "--- " line
    let mut diff_pos = 0;
    let mut found = false;
    let mut p = 0;
    for line in rest.lines_with_terminator() {
        let l = line.trim_end_with(|c| c == '\n' || c == '\r');
        if l.starts_with(b"diff -") || l.starts_with(b"Index: ") || (l.starts_with(b"--- ") && l != b"--- ") {
            diff_pos = p;
            found = true;
            break;
        }
        p += line.len();
    }
    let diff = if found { rest[diff_pos..].to_vec() } else { Vec::new() };

    let mut author_name = None;
    let mut author_email = None;
    let mut author_date = None;
    let mut message_lines: Vec<String> = Vec::new();
    for l in desc_lines {
        let ls = l.to_str_lossy();
        if let Some(v) = ls.strip_prefix("From: ") {
            if let Ok((n, e)) = Signature::parse_name_email(v.trim()) {
                author_name = Some(n.to_str_lossy().into_owned());
                author_email = Some(e.to_str_lossy().into_owned());
                continue;
            }
        } else if let Some(v) = ls.strip_prefix("Date: ") {
            if let Some(t) = crate::signature::parse_time(v.trim()) {
                author_date = Some(t);
                continue;
            }
        }
        message_lines.push(ls.into_owned());
    }
    let message = patchedit::normalize_message(&message_lines.join("\n"));
    ImportPatch {
        name: None,
        message,
        author_name,
        author_email,
        author_date,
        diff,
    }
}

/// Parse a mail using `git mailinfo`.
fn parse_mail(repo: &Repository, data: &[u8], keep_cr: bool, message_id: bool) -> Result<ImportPatch> {
    let tmp = tempfile::tempdir()?;
    let msg_path = tmp.path().join("msg");
    let patch_path = tmp.path().join("patch");
    let mut args: Vec<String> = vec!["mailinfo".into()];
    if keep_cr {
        args.push("--keep-cr".into());
    }
    if message_id {
        args.push("-m".into());
    }
    args.push(msg_path.to_string_lossy().into_owned());
    args.push(patch_path.to_string_lossy().into_owned());
    let out = repo.git_output_with_input(&args, data)?;
    if !out.success() {
        return Err(crate::git::repo_git_error("git mailinfo", &out));
    }
    let mut author_name = None;
    let mut author_email = None;
    let mut author_date = None;
    let mut subject = String::new();
    for line in out.stdout_str().lines() {
        if let Some(v) = line.strip_prefix("Author: ") {
            author_name = Some(v.to_string());
        } else if let Some(v) = line.strip_prefix("Email: ") {
            author_email = Some(v.to_string());
        } else if let Some(v) = line.strip_prefix("Subject: ") {
            subject = v.to_string();
        } else if let Some(v) = line.strip_prefix("Date: ") {
            author_date = crate::signature::parse_time(v);
        }
    }
    let body = std::fs::read(&msg_path).unwrap_or_default();
    let diff = std::fs::read(&patch_path).unwrap_or_default();
    let body_str = body.to_str_lossy().into_owned();
    let mut message = subject.clone();
    if !body_str.trim().is_empty() {
        message.push_str("\n\n");
        message.push_str(body_str.trim_end_matches('\n'));
    }
    let message = patchedit::normalize_message(&message);
    let name = if subject.is_empty() {
        None
    } else {
        Some(PatchName::make(&subject, true, Some(30)))
    };
    Ok(ImportPatch {
        name,
        message,
        author_name,
        author_email,
        author_date,
        diff,
    })
}

fn strip_patch_name(name: &str) -> String {
    // Strip leading number and extension: "0001-foo.patch" -> "foo"
    let mut s = name;
    let digits_end = s.chars().take_while(|c| c.is_ascii_digit()).count();
    if digits_end > 0 && s[digits_end..].starts_with('-') {
        s = &s[digits_end + 1..];
    }
    let s = match s.rfind('.') {
        Some(pos) if pos > 0 => &s[..pos],
        _ => s,
    };
    s.to_string()
}

struct ImportContext<'a> {
    repo: &'a Repository,
    color: ColorChoice,
    edit: EditOptions,
    strip: Option<usize>,
    context: Option<usize>,
    directory: Option<String>,
    reject: bool,
    three_way: bool,
    stripname: bool,
    replace: bool,
    ignore: bool,
    base: Option<Oid>,
}

fn import_one(ctx: &ImportContext, stack: Stack, patch: ImportPatch, default_name: &str, name_override: Option<&PatchName>) -> Result<Stack> {
    let repo = ctx.repo;
    let len_limit = repo
        .config
        .get_i64("stgit.namelength")
        .map(|n| n.max(0) as usize)
        .unwrap_or(30);
    let mut name: PatchName = match name_override {
        Some(n) => n.clone(),
        None => match &patch.name {
            Some(n) => n.clone(),
            None => {
                let raw = if ctx.stripname {
                    strip_patch_name(default_name)
                } else {
                    default_name.to_string()
                };
                PatchName::make(&raw, false, Some(len_limit))
            }
        },
    };
    if ctx.stripname && patch.name.is_some() {
        // name from subject already stripped
    }
    let mut stack = stack;
    if stack.has_patch(&name) {
        if ctx.ignore && stack.is_applied(&name) {
            return Ok(stack);
        }
        if ctx.replace && stack.is_unapplied(&name) {
            stack = TransactionBuilder::new(stack, ctx.color)
                .use_index_and_worktree(false)
                .transact(|trans| {
                    trans.set_reflog_msg("import: replace");
                    trans.delete_patches(&[name.clone()])?;
                    Ok(())
                })?;
        } else if !ctx.ignore && !ctx.replace {
            name = name.uniquify(|pn| stack.collides(pn).is_some());
        } else {
            name = name.uniquify(|pn| stack.collides(pn).is_some());
        }
    } else if let Some(existing) = stack.collides(&name) {
        let _ = existing;
        name = name.uniquify(|pn| stack.collides(pn).is_some());
    }

    // Author
    let default_author = Signature::default_author(&repo.config)?;
    let mut author = default_author.clone();
    if let (Some(n), Some(e)) = (&patch.author_name, &patch.author_email) {
        author.name = BString::from(n.as_str());
        author.email = BString::from(e.as_str());
    }
    if let Some(d) = patch.author_date {
        author.time = d;
    }

    // Apply the diff to the index and work tree.
    let stupid = repo.stupid();
    let head_tree = stack.branch_head.tree_id;
    let mut apply_failed_output: Option<String> = None;
    if !patch.diff.is_empty() {
        let mut args: Vec<String> = vec!["apply".into(), "--index".into()];
        if ctx.reject {
            args.push("--reject".into());
        }
        if ctx.three_way {
            args.push("--3way".into());
        }
        if let Some(n) = ctx.strip {
            args.push(format!("-p{n}"));
        }
        if let Some(n) = ctx.context {
            args.push(format!("-C{n}"));
        }
        if let Some(d) = &ctx.directory {
            args.push(format!("--directory={d}"));
        }
        let mut cmd = repo.git_command();
        cmd.args(&args);
        if let Some(wd) = repo.workdir() {
            cmd.current_dir(wd);
        }
        cmd.stdin(std::process::Stdio::piped())
            .stdout(std::process::Stdio::piped())
            .stderr(std::process::Stdio::piped());
        let mut child = cmd.spawn()?;
        {
            use std::io::Write;
            let mut stdin = child.stdin.take().unwrap();
            let _ = stdin.write_all(&patch.diff);
        }
        let out = child.wait_with_output()?;
        if !out.status.success() {
            let stderr = String::from_utf8_lossy(&out.stderr).trim_end().to_string();
            if ctx.reject {
                apply_failed_output = Some(stderr);
            } else {
                return Err(anyhow!("`git apply --index`: {stderr}"));
            }
        }
    }
    let _ = head_tree;
    if let Some(output) = &apply_failed_output {
        print_info(&format!("`git apply --index`: {output}"), ctx.color);
    }
    let tree_id = stupid.write_tree()?;

    // Edit the description if requested.
    let (final_name, author, message) = {
        let diff = if ctx.edit.diff { Some(patch.diff.clone()) } else { None };
        let outcome = patchedit::edit_description(
            repo,
            &ctx.edit,
            Some(&name),
            &author,
            &patch.message,
            diff.as_deref(),
            "# The diff below is for reference. Any edits will be ignored.\n",
            ctx.edit.edit,
            false,
            ctx.color,
        )?;
        match outcome {
            EditOutcome::TemplateSaved => return Ok(stack),
            EditOutcome::Edited {
                patchname,
                author,
                message,
                ..
            } => (patchname.unwrap_or(name.clone()), author, message),
        }
    };
    let message = if ctx.edit.is_noop() { patch.message.clone() } else { message };

    let cdiad = ctx.edit.committer_date_is_author_date;
    let conflicts = apply_failed_output.is_some();
    let stack = TransactionBuilder::new(stack, ctx.color)
        .use_index_and_worktree(true)
        .allow_conflicts(true)
        .committer_date_is_author_date(cdiad)
        .transact(|trans| {
            trans.set_reflog_msg(&format!("import: {final_name}"));
            let parent = trans.top();
            let commit = trans.commit_patch(&author, message.as_bytes(), tree_id, &[parent.id])?;
            trans.new_applied(&final_name, commit)
        })?;
    if conflicts {
        return Err(crate::error::Error::CausedConflicts("patch conflicts".to_string()).into());
    }
    Ok(stack)
}

fn read_source(path: Option<&Path>) -> Result<Vec<u8>> {
    match path {
        Some(p) => std::fs::read(p).map_err(|e| anyhow!("{e}")),
        None => {
            let mut buf = Vec::new();
            std::io::stdin().read_to_end(&mut buf)?;
            Ok(buf)
        }
    }
}

fn run(matches: &ArgMatches, color: ColorChoice) -> Result<()> {
    let repo = Repository::open()?;
    let stack = Stack::from_branch(&repo, None, InitializationPolicy::AutoInitialize)?;
    stack.check_head_top_mismatch()?;
    crate::util::check_repository_state(&stack)?;
    crate::util::check_no_conflicts(&stack)?;
    crate::util::check_index_and_worktree_clean(&stack)?;

    if matches.get_flag("url") {
        return Err(anyhow!("URL import is not supported"));
    }
    let edit = EditOptions::from_matches(matches, &repo.config)?;
    let base = match matches.get_one::<String>("base") {
        Some(b) => Some(
            repo.rev_parse_commit(b)?
                .ok_or_else(|| anyhow!("invalid committish `{b}`"))?,
        ),
        None => None,
    };
    let keep_cr = matches.get_flag("keep-cr");
    let message_id = matches.get_flag("message-id")
        || repo.config.get_bool("stgit.import.message-id").unwrap_or(false);
    let ctx = ImportContext {
        repo: &repo,
        color,
        edit,
        strip: matches.get_one::<usize>("strip").copied(),
        context: matches.get_one::<usize>("context-lines").copied(),
        directory: matches.get_one::<String>("directory").cloned(),
        reject: matches.get_flag("reject"),
        three_way: matches.get_flag("3way"),
        stripname: matches.get_flag("stripname"),
        replace: matches.get_flag("replace"),
        ignore: matches.get_flag("ignore"),
        base,
    };
    let name_override = matches.get_one::<PatchName>("name");
    let source = matches.get_one::<PathBuf>("source");

    if matches.get_flag("series") {
        let data = read_source(source.map(|p| p.as_path()))?;
        let dir = source
            .and_then(|p| p.parent().map(|d| d.to_path_buf()))
            .unwrap_or_default();
        let mut stack = stack;
        for line in data.to_str_lossy().lines() {
            let line = match line.find('#') {
                Some(pos) => &line[..pos],
                None => line,
            };
            let line = line.trim();
            if line.is_empty() {
                continue;
            }
            let mut parts = line.split_whitespace();
            let fname = parts.next().unwrap();
            let path = dir.join(fname);
            let pdata = std::fs::read(&path).map_err(|e| anyhow!("{e}"))?;
            let patch = if is_mail_like(&pdata) {
                let mut p = parse_mail(&repo, &pdata, keep_cr, message_id)?;
                p.name = None;
                p
            } else {
                parse_plain(&pdata)
            };
            let default_name = Path::new(fname)
                .file_name()
                .map(|s| s.to_string_lossy().into_owned())
                .unwrap_or_else(|| fname.to_string());
            stack = import_one(&ctx, stack, patch, &default_name, None)?;
        }
        return Ok(());
    }

    if matches.get_flag("mbox") {
        let data = read_source(source.map(|p| p.as_path()))?;
        let tmp = tempfile::tempdir()?;
        let out = repo.git_output_with_input(
            [
                "mailsplit",
                &format!("-o{}", tmp.path().display()),
            ],
            &data,
        )?;
        if !out.success() {
            return Err(crate::git::repo_git_error("git mailsplit", &out));
        }
        let mut entries: Vec<PathBuf> = std::fs::read_dir(tmp.path())?
            .filter_map(|e| e.ok().map(|e| e.path()))
            .collect();
        entries.sort();
        let mut stack = stack;
        for entry in entries {
            let pdata = std::fs::read(&entry)?;
            let patch = parse_mail(&repo, &pdata, keep_cr, message_id)?;
            stack = import_one(&ctx, stack, patch, "patch", None)?;
        }
        return Ok(());
    }

    let data = read_source(source.map(|p| p.as_path()))?;
    let default_name = source
        .and_then(|p| p.file_name().map(|s| s.to_string_lossy().into_owned()))
        .unwrap_or_else(|| "patch".to_string());
    let patch = if matches.get_flag("mail") {
        parse_mail(&repo, &data, keep_cr, message_id)?
    } else if is_mail_like(&data) {
        let mut p = parse_mail(&repo, &data, keep_cr, message_id)?;
        p.name = None;
        p
    } else {
        parse_plain(&data)
    };
    import_one(&ctx, stack, patch, &default_name, name_override)?;
    Ok(())
}
