struct Source {
    commit: Rc<Commit>,
    patchname: Option<PatchName>,
}

fn resolve_sources(repo: &Repository, ref_stack: &Stack, args: &[String]) -> Result<Vec<Source>> {
    let mut sources = Vec::new();
    for arg in args {
        // Patch range in the reference stack?
        if let Ok(range) = arg.parse::<PatchRange>() {
            if range.is_range() {
                let patches = parse_patch_ranges(&[range], ref_stack, RangeConstraint::All)?;
                for pn in patches {
                    sources.push(Source {
                        commit: ref_stack.get_patch_commit(&pn).clone(),
                        patchname: Some(pn),
                    });
                }
                continue;
            }
            if let Ok(pn) = arg.parse::<PatchName>() {
                if ref_stack.has_patch(&pn) {
                    sources.push(Source {
                        commit: ref_stack.get_patch_commit(&pn).clone(),
                        patchname: Some(pn),
                    });
                    continue;
                }
            }
        }
        match repo.rev_parse_commit(arg)? {
            Some(oid) => sources.push(Source {
                commit: repo.find_commit(oid)?,
                patchname: None,
            }),
            None => return Err(ref_stack.patch_not_found_error(arg)),
        }
    }
    Ok(sources)
}

fn run(matches: &ArgMatches, color: ColorChoice) -> Result<()> {
    let repo = Repository::open()?;
    let stack = Stack::from_branch(&repo, None, InitializationPolicy::AutoInitialize)?;
    let ref_branch = matches.get_one::<String>("ref-branch").map(|s| s.as_str());
    let args: Vec<String> = matches
        .get_many::<String>("source")
        .unwrap()
        .cloned()
        .collect();
    let opt_name = matches.get_one::<PatchName>("name").cloned();
    let opt_revert = matches.get_flag("revert");
    let opt_expose = matches.get_flag("expose");
    let opt_noapply = matches.get_flag("noapply");
    let opt_fold = matches.get_flag("fold");
    let opt_update = matches.get_flag("update");
    let cdiad = matches.get_flag("committer-date-is-author-date");
    let files: Vec<PathBuf> = matches
        .get_many::<PathBuf>("file")
        .map(|v| v.cloned().collect())
        .unwrap_or_default();

    if opt_name.is_some() && args.len() > 1 {
        return Err(anyhow!("--name can only be specified with one patch"));
    }

    stack.check_head_top_mismatch()?;
    crate::util::check_repository_state(&stack)?;
    crate::util::check_no_conflicts(&stack)?;
    crate::util::check_index_and_worktree_clean(&stack)?;

    let sources = if let Some(b) = ref_branch {
        let ref_stack = Stack::from_branch(&repo, Some(b), InitializationPolicy::AllowUninitialized)?;
        resolve_sources(&repo, &ref_stack, &args)?
    } else {
        resolve_sources(&repo, &stack, &args)?
    };

