        return fold_sources(&repo, &stack, &sources, opt_update, &files, opt_revert);
    }

    let len_limit = repo
        .config
        .get_i64("stgit.namelength")
        .map(|n| n.max(0) as usize)
        .unwrap_or(30);
    let expose_format = repo
        .config
        .get("stgit.pick.expose-format")
        .unwrap_or("format:%B%n(imported from commit %H)")
        .to_string();

