            let msg_str = commit.message_str().into_owned();
            let (summary, rest) = match msg_str.find('\n') {
                Some(pos) => (&msg_str[..pos], &msg_str[pos + 1..]),
                None => (msg_str.as_str(), ""),
            };
            let message = format!(
                "Revert \"{summary}\"\n\nThis reverts commit {}.\n\n{rest}",
                commit.id
            );
            (BString::from(message), parent_tree, commit.id)
        } else {
            let parent_id = commit
                .parent_ids
                .first()
                .copied()
                .ok_or_else(|| anyhow!("commit `{}` does not have a parent", commit.id))?;
            let message = if opt_expose {
                let out = repo.git_output([
                    "show",
                    "-s",
                    &format!("--pretty={expose_format}"),
                    &commit.id.to_hex(),
                ])?;
                if !out.success() {
                    return Err(crate::git::repo_git_error("git show", &out));
                }
                BString::from(out.stdout)
            } else {
                commit.message.clone()
            };
            (message, commit.tree_id, parent_id)
        };
        let parent_id = parent_override.unwrap_or(parent_id);
        let new_commit = if !opt_revert && !opt_expose && parent_override.is_none() {
            commit.clone()
        } else {
            let committer = crate::signature::Signature::default_committer(&repo.config)?;
            let committer = if cdiad {
                committer.with_time(commit.author.time)
            } else {
                committer
            };
            let oid = repo.write_commit(tree_id, &[parent_id], &commit.author, &committer, message.as_bstr())?;
            repo.find_commit(oid)?
        };
        new_patches.push((name, new_commit));
    }

    TransactionBuilder::new(stack, color)
        .use_index_and_worktree(true)
        .committer_date_is_author_date(cdiad)
        .transact(|trans| {
            trans.set_reflog_msg("pick");
            let mut names = Vec::new();
            for (i, (name, commit)) in new_patches.iter().enumerate() {
                trans.new_unapplied(name, commit.clone(), i)?;
                names.push(name.clone());
            }
            if opt_noapply {
                Ok(())
            } else {
                trans.push_patches(&names, false)
            }
        })?;
    Ok(())
}

fn fold_sources(
    repo: &Repository,
    stack: &Stack,
    sources: &[Source],
    update: bool,
    files: &[PathBuf],
    revert: bool,
) -> Result<()> {
    if stack.applied().is_empty() {
        return Err(anyhow!("no patches applied"));
    }
    let stupid = repo.stupid();
    for source in sources {
        let commit = &source.commit;
        let parent_id = commit
            .parent_ids
            .first()
            .copied()
            .ok_or_else(|| anyhow!("commit `{}` does not have a parent", commit.id))?;
        let parent_tree = repo.find_commit(parent_id)?.tree_id;
        let (tree1, tree2) = if revert {
            (commit.tree_id, parent_tree)
        } else {
            (parent_tree, commit.tree_id)
        };
        let pathspecs: Vec<String> = if update {
            let top = stack.top();
            let top_parent = repo.find_commit(top.parent_ids[0])?.tree_id;
            stupid
                .diff_tree_files(top_parent, top.tree_id)?
                .iter()
                .map(|f| f.to_string())
                .collect()
        } else {
            files.iter().map(|p| p.to_string_lossy().into_owned()).collect()
        };
        let diff = stupid.diff_tree_patch(
            tree1,
            tree2,
            if pathspecs.is_empty() { None } else { Some(pathspecs.iter()) },
            true,
            &[],
        )?;
        if diff.is_empty() {
            continue;
        }
        let out = repo.git_output_with_input(["apply", "--index", "--3way"], &diff)?;
        if !out.success() {
            return Err(anyhow!(
                "`git apply --index`: {}",
                out.stderr_str().trim_end()
            ));
        }
    }
    Ok(())
}
