fn resolve_sources(repo: &Repository, ref_stack: &Stack, args: &[String]) -> Result<Vec<Source>> {
    let mut sources = Vec::new();
    for arg in args {
        // Patch range in the reference stack?
        if let Ok(range) = arg.parse::<PatchRange>() {
            if range.is_range() {
                let patches = parse_patch_ranges(&[range], ref_stack, RangeConstraint::All)?;
                for pn in patches {
                    sources.push(Source {
                        commit: ref_stack.get_patch_commit(&pn).clone(),
                        patchname: Some(pn),
                    });
                }
                continue;
            }
            if let Ok(pn) = arg.parse::<PatchName>() {
                if ref_stack.has_patch(&pn) {
                    sources.push(Source {
                        commit: ref_stack.get_patch_commit(&pn).clone(),
                        patchname: Some(pn),
                    });
                    continue;
                }
            }
        }
        match repo.rev_parse_commit(arg)? {
            Some(oid) => sources.push(Source {
                commit: repo.find_commit(oid)?,
                patchname: None,
            }),
            None => return Err(ref_stack.patch_not_found_error(arg)),
        }
    }
    Ok(sources)
