/// Names of local branches pointing at the given commit, sorted.
fn branch_names_at(repo: &Repository, oid: Oid) -> Result<Vec<String>> {
    let mut names: Vec<String> = repo
        .list_refs("refs/heads/")?
        .into_iter()
        .filter(|(_, o)| *o == oid)
        .filter_map(|(r, _)| r.strip_prefix("refs/heads/").map(|s| s.to_string()))
        .collect();
    names.sort();
    Ok(names)
}

pub fn describe_commit(repo: &Repository, oid: Oid) -> Result<String> {
    let names = branch_names_at(repo, oid)?;
    if names.is_empty() {
        Ok(format!("`{oid}`"))
    } else {
        Ok(format!("`{oid}` ({})", names.join(" ")))
    }
}

fn run(matches: &ArgMatches, color: ColorChoice) -> Result<()> {
    let repo = Repository::open()?;
    let stack = Stack::from_branch(&repo, None, InitializationPolicy::RequireInitialized)?;
    let nopush = matches.get_flag("nopush");
    let merged = matches.get_flag("merged");
    let autostash = matches.get_flag("autostash");
    let cdiad = matches.get_flag("committer-date-is-author-date");
    let allow_conflicts = super::push::allow_push_conflicts(&repo, matches);
    let exec_cmds: Vec<String> = matches
        .get_many::<String>("exec")
        .map(|v| v.cloned().collect())
        .unwrap_or_default();
    if matches.get_flag("interactive") {
        return Err(anyhow!("interactive rebase is not supported"));
    }

    let target: Oid = match matches.get_one::<StGitRevision>("committish") {
        Some(spec) => {
            let (_, rev) = parse_stgit_revision(&repo, Some(spec), None, InitializationPolicy::AllowUninitialized)?;
            match repo.object_kind(rev.oid)?.as_deref() {
                Some("commit") => rev.oid,
                _ => return Err(anyhow!("`{}` is not a commit", spec.raw)),
            }
        }
        None => {
            let branch = &stack.branch_name;
            let remote = repo.config.get(&format!("branch.{branch}.remote"));
            let merge_ref = repo.config.get(&format!("branch.{branch}.merge"));
            match (remote, merge_ref) {
                (Some(remote), Some(merge_ref)) => {
                    let short = merge_ref.strip_prefix("refs/heads/").unwrap_or(merge_ref);
                    let upstream = if remote == "." {
                        short.to_string()
                    } else {
                        format!("{remote}/{short}")
                    };
                    repo.rev_parse_commit(&upstream)?
                        .ok_or_else(|| anyhow!("invalid upstream `{upstream}`"))?
                }
                _ => {
                    print_info(
                        &format!(
                            "if you wish to set tracking information for this branch you can do so with:\n\n    git branch --set-upstream-to=<remote>/<branch> {branch}\n"
                        ),
                        color,
                    );
                    return Err(anyhow!(
                        "there is no tracking information for the current branch"
                    ));
                }
            }
        }
    };

    if target == stack.base.id {
        print_info(
            &format!("Already based on {}", describe_commit(&repo, target)?),
            color,
        );
        return Ok(());
    }

    stack.check_protected()?;
    stack.check_head_top_mismatch()?;
    crate::util::check_repository_state(&stack)?;
    crate::util::check_no_conflicts(&stack)?;
    if !autostash {
        crate::util::check_index_and_worktree_clean(&stack)?;
    } else {
        let status = repo.stupid().run_git_passthrough(["stash"])?;
        if !status.success() {
            return Err(anyhow!("`git stash` failed"));
        }
    }

    let applied: Vec<PatchName> = stack.applied().to_vec();

    // Transaction 1: pop all applied patches.
    let stack = if applied.is_empty() {
        stack
    } else {
        TransactionBuilder::new(stack, color)
            .use_index_and_worktree(true)
            .transact(|trans| {
                trans.set_reflog_msg("rebase (pop)");
                trans.pop_patches(|_| true)?;
                Ok(())
            })?
    };

    // Move the base.
    print_info(
        &format!("Rebasing to {}", describe_commit(&repo, target)?),
        color,
    );
    let status = repo
        .stupid()
        .run_git_passthrough(["reset", "--hard", &target.to_hex()])?;
    if !status.success() {
        return Err(anyhow!("`git reset --hard` failed"));
    }
    let target_commit = repo.find_commit(target)?;
    let mut stack = stack;
    stack.branch_head = target_commit.clone();
    let stack = TransactionBuilder::new(stack, color)
        .use_index_and_worktree(false)
        .allow_bad_head(true)
        .transact(|trans| {
            trans.set_reflog_msg("rebase");
            trans.set_head_commit(target_commit.clone());
            trans.update_base(target_commit.clone());
            Ok(())
        })?;

    // Transaction 3: push back.
    let result = if !nopush && !applied.is_empty() {
        TransactionBuilder::new(stack, color)
            .use_index_and_worktree(true)
            .committer_date_is_author_date(cdiad)
            .allow_push_conflicts(allow_conflicts)
            .transact(|trans| {
                trans.set_reflog_msg("rebase (reapply)");
                if exec_cmds.is_empty() {
                    trans.push_patches(&applied, merged)
                } else {
                    for pn in &applied {
                        trans.push_patch(pn, false, false)?;
                        trans.checkout_now()?;
                        for cmd in &exec_cmds {
                            trans.print_message(&format!("Executing: {cmd}"))?;
                            let status = std::process::Command::new("sh")
                                .arg("-c")
                                .arg(cmd)
                                .current_dir(trans.repo().workdir().unwrap())
                                .status()?;
                            if !status.success() {
                                return Err(anyhow!("command `{cmd}` failed"));
                            }
                        }
                    }
                    Ok(())
                }
            })
            .map(|_| ())
    } else {
        Ok(())
    };

    if autostash {
        let _ = repo.stupid().run_git_passthrough(["stash", "pop"])?;
    }
    result
}
