                .help("Synchronize all applied patches")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("ref-branch")
                .long("ref-branch")
                .short('B')
                .help("Synchronize patches with <branch>")
                .value_name("branch")
                .required_unless_present("series")
                .conflicts_with("series"),
        )
        .arg(
            Arg::new("series")
                .long("series")
                .short('S')
                .help("Synchronize patches with <series>")
                .value_name("series")
                .value_hint(ValueHint::FilePath)
                .value_parser(clap::value_parser!(PathBuf)),
        )
        .arg(crate::argset::committer_date_is_author_date_arg())
        .arg(crate::argset::color_arg())
}

/// Source of the reference patches: trees (base, top) keyed by patch name.
struct RefPatch {
    base_tree: Oid,
    top_tree: Oid,
}

fn run(matches: &ArgMatches, color: ColorChoice) -> Result<()> {
    let repo = Repository::open()?;
    let stack = Stack::from_branch(&repo, None, InitializationPolicy::AllowUninitialized)?;
    let cdiad = matches.get_flag("committer-date-is-author-date");

    // Determine reference patches.
    let ref_lookup: Box<dyn Fn(&PatchName) -> Result<Option<RefPatch>>> =
        if let Some(branch) = matches.get_one::<String>("ref-branch") {
            let ref_stack = Stack::from_branch(&repo, Some(branch), InitializationPolicy::AllowUninitialized)?;
            if ref_stack.branch_name == stack.branch_name {
                return Err(anyhow!("cannot synchronize with the current branch"));
            }
            let repo2 = &repo;
            let patches: Vec<(PatchName, Oid, Oid)> = ref_stack
                .all_patches()
                .map(|pn| {
                    let c = ref_stack.get_patch_commit(pn);
                    let parent_tree = repo2
                        .find_commit(c.parent_ids[0])
                        .map(|p| p.tree_id)
                        .unwrap_or(c.tree_id);
                    (pn.clone(), parent_tree, c.tree_id)
                })
                .collect();
            Box::new(move |pn: &PatchName| {
                Ok(patches.iter().find(|(n, _, _)| n == pn).map(|(_, b, t)| RefPatch {
                    base_tree: *b,
                    top_tree: *t,
                }))
            })
        } else {
            let series_path = matches.get_one::<PathBuf>("series").unwrap().clone();
            let names = super::float::read_series_file(&series_path)?;
            let dir = series_path.parent().map(|d| d.to_path_buf()).unwrap_or_default();
            let repo2 = &repo;
            let stack_base = stack.base.tree_id;
            let _ = stack_base;
            // For series, the patch diff is applied onto our patch's parent tree.
            let files: Vec<(String, PathBuf)> = names
                .iter()
                .map(|n| (n.clone(), dir.join(n)))
                .collect();
            let stack_ref: Vec<(PatchName, Oid)> = stack
                .all_patches()
                .map(|pn| {
                    let c = stack.get_patch_commit(pn);
                    let parent_tree = repo2
                        .find_commit(c.parent_ids[0])
                        .map(|p| p.tree_id)
                        .unwrap_or(c.tree_id);
                    (pn.clone(), parent_tree)
                })
                .collect();
            Box::new(move |pn: &PatchName| {
                let Some((_, path)) = files.iter().find(|(n, _)| n == pn.as_str()) else {
                    return Ok(None);
                };
                let data = std::fs::read(path).map_err(|e| anyhow!("{e}"))?;
                let base_tree = stack_ref
                    .iter()
                    .find(|(n, _)| n == pn)
                    .map(|(_, t)| *t)
                    .ok_or_else(|| anyhow!("patch `{pn}` does not exist"))?;
                let stupid = repo2.stupid();
                let top_tree = stupid.with_temp_index(|temp| {
                    temp.read_tree(base_tree)?;
                    // Extract diff portion
                    let diff = extract_diff(&data);
                    if !diff.is_empty() {
                        let out = temp.apply_to_index_output(&diff)?;
                        if !out.success() {
                            return Err(anyhow!("`git apply`: {}", out.stderr_str().trim_end()));
                        }
                    }
                    temp.write_tree()
                })?;
                Ok(Some(RefPatch { base_tree, top_tree }))
            })
        };

    let ranges = get_ranges(matches, "patchranges");
    let candidates: Vec<PatchName> = if !ranges.is_empty() {
        let patches = parse_patch_ranges(&ranges, &stack, RangeConstraint::Visible)?;
        for pn in &patches {
            if !stack.is_applied(pn) {
                return Err(anyhow!("patch `{pn}` is not applied"));
            }
        }
        patches
    } else if matches.get_flag("all") {
        stack.applied().to_vec()
    } else {
        match stack.applied().last() {
            Some(pn) => vec![pn.clone()],
            None => return Err(anyhow!("no patches applied")),
        }
    };
    let mut to_sync: Vec<PatchName> = Vec::new();
    for pn in &candidates {
        if ref_lookup(pn)?.is_some() {
            to_sync.push(pn.clone());
        }
    }
    if to_sync.is_empty() {
        return Err(anyhow!("no common patches to synchronize"));
    }

    stack.check_head_top_mismatch()?;
    crate::util::check_repository_state(&stack)?;
    crate::util::check_no_conflicts(&stack)?;
    crate::util::check_index_and_worktree_clean(&stack)?;

    // Pop patches above the lowest patch to sync.
    let applied = stack.applied().to_vec();
    let lowest = applied
        .iter()
        .position(|pn| to_sync.contains(pn))
        .unwrap();
    let to_repush: Vec<PatchName> = applied[lowest..].to_vec();
    let above: Vec<PatchName> = applied[lowest + 1..].to_vec();
    let stack = TransactionBuilder::new(stack, color)
        .use_index_and_worktree(true)
        .transact(|trans| {
            trans.set_reflog_msg("sync (pop)");
            if !above.is_empty() {
                trans.pop_patches(|pn| above.contains(pn))?;
            }
            Ok(())
        })?;

    let repo_ref = &repo;
    TransactionBuilder::new(stack, color)
        .use_index_and_worktree(true)
        .committer_date_is_author_date(cdiad)
        .transact(|trans| {
            trans.set_reflog_msg("sync");
            let n = to_repush.len();
            for (i, pn) in to_repush.iter().enumerate() {
                if !trans.is_applied(pn) {
                    trans.push_patch(pn, false, i + 1 == n)?;
                }
                if !to_sync.contains(pn) {
                    continue;
                }
                let Some(rp) = ref_lookup(pn)? else { continue };
                let commit = trans.get_patch_commit(pn);
                let our_tree = commit.tree_id;
                if rp.top_tree == our_tree {
                    continue;
                }
                let stupid = repo_ref.stupid();
                // Try an in-memory merge first.
                let merged = stupid.with_temp_index(|temp| {
                    temp.read_tree(our_tree)?;
                    if temp.apply_treediff_to_index(rp.base_tree, rp.top_tree, false)? {
                        Ok(Some(temp.write_tree()?))
                    } else {
                        Ok(None)
                    }
                })?;
                let new_tree = match merged {
                    Some(t) => t,
                    None => {
                        trans.checkout_now()?;
                        if stupid.merge_recursive(rp.base_tree, our_tree, rp.top_tree)? {
                            stupid.write_tree()?
                        } else {
                            return Err(crate::error::Error::CausedConflicts(format!(
                                "merge conflicts syncing `{pn}`"
                            ))
                            .into());
                        }
                    }
                };
                if new_tree != our_tree {
                    let parent_id = commit.parent_ids[0];
                    let new_commit = trans.commit_patch(
                        &commit.author,
                        &commit.message,
                        new_tree,
                        &[parent_id],
                    )?;
                    trans.update_patch_print(pn, new_commit)?;
                }
            }
            Ok(())
        })?;
    Ok(())
}

fn extract_diff(data: &[u8]) -> Vec<u8> {
    use bstr::ByteSlice;
    let mut pos = 0;
    for line in data.lines_with_terminator() {
        if line.starts_with(b"diff -") || line.starts_with(b"Index: ") {
            return data[pos..].to_vec();
        }
        pos += line.len();
    }
    Vec::new()
}
