use anyhow::{anyhow, Result};
use clap::{Arg, ArgAction, ArgMatches};

use super::{CommandCategory, StGitCommand};
use crate::color::ColorChoice;
use crate::git::Repository;
use crate::patch::PatchName;
use crate::stack::{InitializationPolicy, Stack, TransactionBuilder};
use crate::util::print_info;

pub const STGIT_COMMAND: StGitCommand = StGitCommand {
    name: "pull",
    about: "Pull changes from a remote repository",
    category: CommandCategory::StackManipulation,
    make,
    run,
};

fn make() -> clap::Command {
    clap::Command::new("pull")
        .about("Pull changes from a remote repository")
        .long_about(
            "Pull the latest changes from a remote repository.\n\
             \n\
             The remote repository may be specified on the command line, but defaults to \
             branch.<name>.remote from the git configuration, or \"origin\" if not \
             configured.\n\
             \n\
             This command works by popping all currently applied patches from the stack, \
             pulling the changes from the remote repository, updating the stack base to the new \
             remote HEAD, and finally pushing all formerly applied patches back onto the stack. \
             Merge conflicts may occur during the final push step. Those conflicts need to be \
             resolved manually.\n\
             \n\
             See git-fetch(1) for the format of remote repository argument.",
        )
        .arg(Arg::new("repository").help("Repository to pull from"))
        .arg(
            Arg::new("nopush")
                .long("nopush")
                .short('n')
                .help("Do not push back patches after pulling")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("merged")
                .long("merged")
                .short('m')
                .help("Check for patches merged upstream")
                .long_help(
                    "Check for patches that may have been merged upstream.\n\
                     \n\
                     When pushing-back patches, each patch is checked to see if its changes \
                     already exist in the just-pulled upstream changes. If a patch's changes \
                     have already been merged upstream, the patch will still exist in the stack, \
                     but become empty after the pull operation.",
                )
                .action(ArgAction::SetTrue),
        )
        .arg(crate::argset::push_conflicts_arg())
        .arg(crate::argset::color_arg())
}

fn run(matches: &ArgMatches, color: ColorChoice) -> Result<()> {
    let repo = Repository::open()?;
    let stack = Stack::from_branch(&repo, None, InitializationPolicy::RequireInitialized)?;
    let nopush = matches.get_flag("nopush");
    let merged = matches.get_flag("merged");
    let allow_conflicts = super::push::allow_push_conflicts(&repo, matches);
    let branch = stack.branch_name.clone();

    if stack.is_protected() {
        return Err(anyhow!("this branch is protected; pulls are not permitted"));
    }

    let policy = repo
        .config
        .get(&format!("branch.{branch}.stgit.pull-policy"))
        .or_else(|| repo.config.get("stgit.pull-policy"))
        .unwrap_or("pull")
        .to_string();
    if !["pull", "fetch-rebase", "rebase"].contains(&policy.as_str()) {
        return Err(anyhow!("unsupported pull-policy `{policy}`"));
    }

    let remote: Option<String> = match matches.get_one::<String>("repository") {
        Some(r) => Some(r.clone()),
        None => repo
            .config
            .get(&format!("branch.{branch}.remote"))
            .map(|s| s.to_string()),
    };
    if policy != "rebase" && remote.is_none() {
        return Err(anyhow!(
            "no tracking information for the current branch;\nplease specify the remote repository to pull from."
        ));
    }

