            let parent = repo
                .config
                .get(&format!("branch.{branch}.stgit.parentbranch"))
                .map(|s| s.to_string())
                .ok_or_else(|| anyhow!("cannot find a parent branch for `{branch}`"))?;
            let target = repo
                .rev_parse_commit(&parent)?
                .ok_or_else(|| anyhow!("invalid parent branch `{parent}`"))?;
            print_info(
                &format!("Rebasing to {}", super::rebase::describe_commit(&repo, target)?),
                color,
            );
            let status = stupid.run_git_passthrough(["reset", "--hard", &target.to_hex()])?;
            if !status.success() {
                return Err(anyhow!("`git reset --hard` failed"));
            }
        }
    }

    // Update stack head to the new HEAD.
    let new_head_id = repo.head_oid()?.ok_or_else(|| anyhow!("HEAD is unborn"))?;
    let new_head = repo.find_commit(new_head_id)?;
    let mut stack = stack;
    stack.branch_head = new_head.clone();
    let stack = if new_head.id != stack.state.head.id {
        TransactionBuilder::new(stack, color)
            .use_index_and_worktree(false)
            .allow_bad_head(true)
            .transact(|trans| {
                trans.set_reflog_msg("pull");
                trans.set_head_commit(new_head.clone());
                trans.update_base(new_head.clone());
                Ok(())
            })?
    } else {
        stack
    };

    if !nopush {
        TransactionBuilder::new(stack, color)
            .use_index_and_worktree(true)
            .allow_push_conflicts(allow_conflicts)
            .transact(|trans| {
                trans.set_reflog_msg("pull (reapply)");
                trans.push_patches(&applied, merged)
            })?;
    }
    Ok(())
}
