use std::io::Write;
use std::path::PathBuf;

use anyhow::Result;
use clap::{Arg, ArgMatches, ValueHint};

use super::{CommandCategory, StGitCommand, CATEGORIES, STGIT_COMMANDS};
use crate::color::ColorChoice;

pub const STGIT_COMMAND: StGitCommand = StGitCommand {
    name: "completion",
    about: "Support for shell completions",
    category: CommandCategory::Administration,
    make,
    run,
};

fn output_arg(help: &'static str) -> Arg {
    Arg::new("output")
        .long("output")
        .short('o')
        .help(help)
        .value_name("path")
        .value_hint(ValueHint::FilePath)
        .value_parser(clap::value_parser!(PathBuf))
}

fn style_arg() -> Arg {
    Arg::new("style")
        .long("style")
        .help("Choose output format style")
        .value_name("style")
        .value_parser(["name-only", "asciidoc", "fish", "zsh"])
        .default_value("name-only")
}

fn make() -> clap::Command {
    clap::Command::new("completion")
        .about("Support for shell completions")
        .long_about(
            "Support completions for bash, fish, and zsh. Also provides 'stg completion list' \
             command for dynamically introspecting StGit's commands and aliases.",
        )
        .subcommand_required(true)
        .arg_required_else_help(true)
        .subcommand(
            clap::Command::new("bash")
                .about("Generate bash completion script")
                .arg(output_arg("Output completion script to <path>"))
                .arg(crate::argset::color_arg()),
        )
        .subcommand(
            clap::Command::new("fish")
                .about("Generate fish shell completion script")
                .arg(output_arg("Output completion script to <path>"))
                .arg(crate::argset::color_arg()),
        )
        .subcommand(
            clap::Command::new("zsh")
                .about("Generate zsh completion script")
                .arg(output_arg("Output completion script to <path>"))
                .arg(crate::argset::color_arg()),
        )
        .subcommand(
            clap::Command::new("list")
                .about("List StGit command information")
                .subcommand_required(true)
                .arg_required_else_help(true)
                .subcommand(
                    clap::Command::new("aliases")
                        .about("List aliases")
                        .arg(style_arg())
                        .arg(output_arg("Output to <path>"))
                        .arg(crate::argset::color_arg()),
                )
                .subcommand(
                    clap::Command::new("commands")
                        .about("List StGit commands")
                        .arg(style_arg())
                        .arg(output_arg("Output to <path>"))
                        .arg(crate::argset::color_arg()),
                )
                .subcommand(
                    clap::Command::new("commands-and-aliases")
                        .about("List StGit commands and aliases")
                        .arg(style_arg())
                        .arg(output_arg("Output to <path>"))
                        .arg(crate::argset::color_arg()),
                )
                .arg(style_arg())
                .arg(output_arg("Output to <path>"))
                .arg(crate::argset::color_arg()),
        )
        .subcommand(
            clap::Command::new("man")
                .about("Generate asciidoc man pages")
                .long_about(
                    "Generate man pages in asciidoc format. The generated asciidoc files may be \
                     further processed by asciidoc or asciidoctor to produce roff, html, or other \
                     output formats.\n\
                     \n\
                     One file is generated for each `stg` command. The output directory defaults \
                     to the current directory, but may be specified with '--output'. The output \
                     files are named `stg-<command>.txt`.",
                )
                .arg(
                    Arg::new("output")
                        .long("output")
                        .short('o')
                        .help("Output man pages to <dir>")
                        .value_name("dir")
                        .value_hint(ValueHint::DirPath)
                        .value_parser(clap::value_parser!(PathBuf)),
                )
                .arg(crate::argset::color_arg()),
        )
        .arg(output_arg("Output to <path>"))
        .arg(crate::argset::color_arg())
}

fn get_output(matches: &ArgMatches, parent: &ArgMatches) -> Result<Box<dyn Write>> {
    let path = matches
        .get_one::<PathBuf>("output")
        .or_else(|| parent.get_one::<PathBuf>("output"));
    match path {
        Some(p) => Ok(Box::new(std::fs::File::create(p)?)),
        None => Ok(Box::new(std::io::stdout())),
    }
}

fn category_title(cat: CommandCategory) -> &'static str {
    match cat {
        CommandCategory::PatchInspection => "Patch Inspection",
        CommandCategory::PatchManipulation => "Patch Manipulation",
        CommandCategory::StackInspection => "Stack Inspection",
        CommandCategory::StackManipulation => "Stack Manipulation",
        CommandCategory::Administration => "Administration",
    }
}

const HELP_ABOUT: &str = "Print this message or the help of the given subcommand(s)";

fn run(matches: &ArgMatches, color: ColorChoice) -> Result<()> {
    match matches.subcommand() {
        Some(("list", list_m)) => run_list(list_m, matches, color),
        Some(("bash", m)) => {
            let mut out = get_output(m, matches)?;
            write_bash(&mut out)?;
            Ok(())
        }
        Some(("fish", m)) => {
            let mut out = get_output(m, matches)?;
            write_fish(&mut out)?;
            Ok(())
        }
        Some(("zsh", m)) => {
            let mut out = get_output(m, matches)?;
            write_zsh(&mut out)?;
            Ok(())
        }
        Some(("man", m)) => run_man(m),
        _ => Ok(()),
    }
}

fn run_list(matches: &ArgMatches, parent: &ArgMatches, _color: ColorChoice) -> Result<()> {
    let (what, sub) = match matches.subcommand() {
        Some((name, sub)) => (name, sub),
        None => return Ok(()),
    };
    let style = sub
        .get_one::<String>("style")
        .or_else(|| matches.get_one::<String>("style"))
        .map(|s| s.as_str())
        .unwrap_or("name-only")
        .to_string();
    let mut out = get_output(sub, if matches.get_one::<PathBuf>("output").is_some() { matches } else { parent })?;
    let config = crate::config::Config::load(None).unwrap_or_default();
    let aliases = crate::alias::get_aliases(Some(&config), |n| super::find_command(n).is_some());
    let show_commands = what == "commands" || what == "commands-and-aliases";
    let show_aliases = what == "aliases" || what == "commands-and-aliases";

    if style == "asciidoc" {
        if show_commands {
            for cat in CATEGORIES {
                let title = category_title(*cat);
                writeln!(out, "{title}")?;
                writeln!(out, "{}", "~".repeat(title.len()))?;
                writeln!(out)?;
                let mut entries: Vec<(&str, &str)> = STGIT_COMMANDS
                    .iter()
                    .filter(|c| c.category == *cat)
                    .map(|c| (c.name, c.about))
                    .collect();
                if *cat == CommandCategory::Administration {
                    entries.push(("help", HELP_ABOUT));
                }
                entries.sort();
                for (name, about) in entries {
                    writeln!(out, "linkstg:{name}[]::")?;
                    writeln!(out, "    {about}")?;
                }
                writeln!(out)?;
            }
        }
        if show_aliases {
            writeln!(out, "Aliases")?;
            writeln!(out, "~~~~~~~")?;
            writeln!(out)?;
            for alias in aliases.values() {
                writeln!(out, "{}::", alias.name)?;
                writeln!(out, "    {}", alias.about())?;
            }
        }
        return Ok(());
    }

    let mut entries: Vec<(String, String)> = Vec::new();
    if show_commands {
        for c in STGIT_COMMANDS {
            entries.push((c.name.to_string(), c.about.to_string()));
        }
        entries.push(("help".to_string(), HELP_ABOUT.to_string()));
    }
    if show_aliases {
        for alias in aliases.values() {
            entries.push((alias.name.clone(), alias.about()));
        }
    }
    for (name, about) in entries {
        match style.as_str() {
            "fish" => writeln!(out, "{name}\t{about}")?,
            "zsh" => writeln!(out, "{name}:{about}")?,
            _ => writeln!(out, "{name}")?,
        }
    }
    Ok(())
}

fn all_commands() -> Vec<clap::Command> {
    let mut v: Vec<clap::Command> = STGIT_COMMANDS.iter().map(|c| (c.make)()).collect();
    v.sort_by(|a, b| a.get_name().cmp(b.get_name()));
    v
}

fn write_bash(out: &mut dyn Write) -> Result<()> {
    writeln!(
        out,
        "# -*- shell-script -*-\n#\n# SPDX-License-Identifier: GPL-2.0-only\n#\n# bash completion script for StGit (automatically generated)\n#\n# To use these routines:\n#\n#    1. Copy this file to somewhere (e.g. ~/.stgit-completion.bash).\n#\n#    2. Add the following line to your .bashrc:\n#         . ~/.stgit-completion.bash\n"
    )?;
    writeln!(out, "__stg_commands=\"{}\"", STGIT_COMMANDS.iter().map(|c| c.name).collect::<Vec<_>>().join(" "))?;
    writeln!(out)?;
    for cmd in all_commands() {
        let opts: Vec<String> = cmd
            .get_arguments()
            .filter_map(|a| a.get_long().map(|l| format!("--{l}")))
            .collect();
        writeln!(
            out,
            "__stg_opts_{}=\"{}\"",
            cmd.get_name().replace('-', "_"),
            opts.join(" ")
        )?;
    }
    writeln!(
        out,
        r#"
_stg ()
{{
    local cur prev cmd i
    COMPREPLY=()
    cur="${{COMP_WORDS[COMP_CWORD]}}"
    for ((i = 1; i < COMP_CWORD; i++)); do
        case "${{COMP_WORDS[i]}}" in
            -*) ;;
            *) cmd="${{COMP_WORDS[i]}}"; break ;;
        esac
    done
    if [ -z "$cmd" ]; then
        COMPREPLY=($(compgen -W "$__stg_commands help $(stg completion list aliases 2>/dev/null)" -- "$cur"))
        return
    fi
    local var="__stg_opts_${{cmd//-/_}}"
    case "$cur" in
        -*) COMPREPLY=($(compgen -W "${{!var}}" -- "$cur")) ;;
        *) COMPREPLY=($(compgen -W "$(stg series --no-prefix -a 2>/dev/null)" -- "$cur")) ;;
    esac
}}

complete -o default -F _stg stg"#
    )?;
    Ok(())
}

fn write_fish(out: &mut dyn Write) -> Result<()> {
    writeln!(out, "# fish completion script for StGit (automatically generated)")?;
    writeln!(out, "# SPDX-License-Identifier: GPL-2.0-only\n")?;
    writeln!(
        out,
        "complete -c stg -n '__fish_use_subcommand' -a '(stg completion list commands-and-aliases --style=fish)'"
    )?;
    for cmd in all_commands() {
        let name = cmd.get_name().to_string();
        for arg in cmd.get_arguments() {
            if arg.get_id().as_str() == "help" {
                continue;
            }
            let mut line = format!("complete -c stg -n '__fish_seen_subcommand_from {name}'");
            if let Some(s) = arg.get_short() {
                line.push_str(&format!(" -s {s}"));
            }
            if let Some(l) = arg.get_long() {
                line.push_str(&format!(" -l {l}"));
            }
            if let Some(h) = arg.get_help() {
                let h = h.to_string().replace('\'', "\\'");
                line.push_str(&format!(" -d '{h}'"));
            }
            if arg.get_long().is_some() || arg.get_short().is_some() {
                writeln!(out, "{line}")?;
            }
        }
    }
    Ok(())
}

fn write_zsh(out: &mut dyn Write) -> Result<()> {
    writeln!(out, "#compdef stg")?;
    writeln!(out, "# zsh completion script for StGit (automatically generated)")?;
    writeln!(out, "# SPDX-License-Identifier: GPL-2.0-only\n")?;
    writeln!(out, "_stg() {{")?;
    writeln!(out, "  local -a commands")?;
    writeln!(out, "  commands=(")?;
    for c in STGIT_COMMANDS {
        writeln!(out, "    '{}:{}'", c.name, c.about.replace('\'', "'\\''"))?;
    }
    writeln!(out, "  )")?;
    writeln!(out, "  if (( CURRENT == 2 )); then")?;
    writeln!(out, "    _describe -t commands 'stg command' commands")?;
    writeln!(out, "    return")?;
    writeln!(out, "  fi")?;
    writeln!(out, "  case \"${{words[2]}}\" in")?;
    for cmd in all_commands() {
        let mut specs: Vec<String> = Vec::new();
        for arg in cmd.get_arguments() {
            let help = arg
                .get_help()
                .map(|h| h.to_string().replace('[', "\\[").replace(']', "\\]").replace('\'', "'\\''"))
                .unwrap_or_default();
            if let Some(l) = arg.get_long() {
                specs.push(format!("'--{l}[{help}]'"));
            }
            if let Some(s) = arg.get_short() {
                specs.push(format!("'-{s}[{help}]'"));
            }
        }
        writeln!(out, "    {})", cmd.get_name())?;
        writeln!(out, "      _arguments {} '*:patch:($(stg series --no-prefix -a 2>/dev/null))'", specs.join(" "))?;
        writeln!(out, "      ;;")?;
    }
    writeln!(out, "  esac")?;
    writeln!(out, "}}")?;
    writeln!(out, "\n_stg \"$@\"")?;
    Ok(())
}

fn run_man(matches: &ArgMatches) -> Result<()> {
    let dir = matches
        .get_one::<PathBuf>("output")
        .cloned()
        .unwrap_or_else(|| PathBuf::from("."));
    std::fs::create_dir_all(&dir)?;
    for stgcmd in STGIT_COMMANDS {
        let mut cmd = (stgcmd.make)();
        let name = stgcmd.name;
        let mut text = String::new();
        text.push_str(&format!("stg-{name}(1)\n{}\n\n", "=".repeat(name.len() + 7)));
        text.push_str("NAME\n----\n");
        text.push_str(&format!("stg-{name} - {}\n\n", stgcmd.about));
        text.push_str("SYNOPSIS\n--------\n[verse]\n");
        let usage = cmd.render_usage().to_string();
        for line in usage.lines() {
            let line = line.trim_start_matches("Usage: ").trim();
            text.push_str(&format!("'{line}'\n"));
        }
        text.push('\n');
        text.push_str("DESCRIPTION\n-----------\n\n");
        let about = cmd
            .get_long_about()
            .or_else(|| cmd.get_about())
            .map(|s| s.to_string())
            .unwrap_or_default();
        text.push_str(&about);
        text.push_str("\n\nOPTIONS\n-------\n\n");
        for arg in cmd.get_arguments() {
            if arg.get_id().as_str() == "help" || arg.is_positional() {
                continue;
            }
            let mut names: Vec<String> = Vec::new();
            if let Some(s) = arg.get_short() {
                names.push(format!("-{s}"));
            }
            if let Some(l) = arg.get_long() {
                names.push(format!("--{l}"));
            }
            let value = if arg.get_action().takes_values() {
                format!(" <{}>", arg.get_value_names().map(|v| v[0].to_string()).unwrap_or_else(|| arg.get_id().to_string()))
            } else {
                String::new()
            };
            text.push_str(&format!("{}{value}::\n", names.join(", ")));
            let help = arg
                .get_long_help()
                .or_else(|| arg.get_help())
                .map(|h| h.to_string())
                .unwrap_or_default();
            for line in help.lines() {
                text.push_str(&format!("    {line}\n"));
            }
            text.push('\n');
        }
        text.push_str("StGit\n-----\nPart of the StGit suite - see linkman:stg[1]\n");
        std::fs::write(dir.join(format!("stg-{name}.txt")), text)?;
    }
    Ok(())
}
