fn get_output(matches: &ArgMatches, parent: &ArgMatches) -> Result<Box<dyn Write>> {
    let path = matches
        .get_one::<PathBuf>("output")
        .or_else(|| parent.get_one::<PathBuf>("output"));
    match path {
        Some(p) => Ok(Box::new(std::fs::File::create(p)?)),
        None => Ok(Box::new(std::io::stdout())),
    }
}

fn category_title(cat: CommandCategory) -> &'static str {
    match cat {
        CommandCategory::PatchInspection => "Patch Inspection",
        CommandCategory::PatchManipulation => "Patch Manipulation",
        CommandCategory::StackInspection => "Stack Inspection",
        CommandCategory::StackManipulation => "Stack Manipulation",
        CommandCategory::Administration => "Administration",
    }
}

const HELP_ABOUT: &str = "Print this message or the help of the given subcommand(s)";

fn run(matches: &ArgMatches, color: ColorChoice) -> Result<()> {
    match matches.subcommand() {
        Some(("list", list_m)) => run_list(list_m, matches, color),
        Some(("bash", m)) => {
            let mut out = get_output(m, matches)?;
            write_bash(&mut out)?;
            Ok(())
        }
        Some(("fish", m)) => {
            let mut out = get_output(m, matches)?;
            write_fish(&mut out)?;
            Ok(())
        }
        Some(("zsh", m)) => {
            let mut out = get_output(m, matches)?;
            write_zsh(&mut out)?;
            Ok(())
        }
        Some(("man", m)) => run_man(m),
        _ => Ok(()),
    }
}

fn run_list(matches: &ArgMatches, parent: &ArgMatches, _color: ColorChoice) -> Result<()> {
    let (what, sub) = match matches.subcommand() {
        Some((name, sub)) => (name, sub),
        None => return Ok(()),
    };
    let style = sub
        .get_one::<String>("style")
        .or_else(|| matches.get_one::<String>("style"))
        .map(|s| s.as_str())
        .unwrap_or("name-only")
        .to_string();
    let mut out = get_output(sub, if matches.get_one::<PathBuf>("output").is_some() { matches } else { parent })?;
    let config = crate::config::Config::load(None).unwrap_or_default();
    let aliases = crate::alias::get_aliases(Some(&config), |n| super::find_command(n).is_some());
    let show_commands = what == "commands" || what == "commands-and-aliases";
    let show_aliases = what == "aliases" || what == "commands-and-aliases";

    if style == "asciidoc" {
        if show_commands {
            for cat in CATEGORIES {
                let title = category_title(*cat);
                writeln!(out, "{title}")?;
                writeln!(out, "{}", "~".repeat(title.len()))?;
                writeln!(out)?;
                let mut entries: Vec<(&str, &str)> = STGIT_COMMANDS
                    .iter()
                    .filter(|c| c.category == *cat)
                    .map(|c| (c.name, c.about))
                    .collect();
                if *cat == CommandCategory::Administration {
                    entries.push(("help", HELP_ABOUT));
                }
                entries.sort();
                for (name, about) in entries {
                    writeln!(out, "linkstg:{name}[]::")?;
                    writeln!(out, "    {about}")?;
                }
                writeln!(out)?;
            }
        }
        if show_aliases {
            writeln!(out, "Aliases")?;
            writeln!(out, "~~~~~~~")?;
            writeln!(out)?;
            for alias in aliases.values() {
                writeln!(out, "{}::", alias.name)?;
                writeln!(out, "    {}", alias.about())?;
            }
        }
        return Ok(());
    }

    let mut entries: Vec<(String, String)> = Vec::new();
    if show_commands {
        for c in STGIT_COMMANDS {
            entries.push((c.name.to_string(), c.about.to_string()));
        }
        entries.push(("help".to_string(), HELP_ABOUT.to_string()));
    }
    if show_aliases {
        for alias in aliases.values() {
            entries.push((alias.name.clone(), alias.about()));
        }
    }
    for (name, about) in entries {
        match style.as_str() {
            "fish" => writeln!(out, "{name}\t{about}")?,
            "zsh" => writeln!(out, "{name}:{about}")?,
            _ => writeln!(out, "{name}")?,
        }
    }
    Ok(())
}

fn all_commands() -> Vec<clap::Command> {
    let mut v: Vec<clap::Command> = STGIT_COMMANDS.iter().map(|c| (c.make)()).collect();
    v.sort_by(|a, b| a.get_name().cmp(b.get_name()));
    v
}

