fn parse_undo_redo(msg: &str) -> Option<(bool, isize)> {
    let msg = msg.trim();
    if let Some(n) = msg.strip_prefix("undo ") {
        n.trim().parse::<isize>().ok().map(|n| (true, n))
    } else if let Some(n) = msg.strip_prefix("redo ") {
        n.trim().parse::<isize>().ok().map(|n| (false, n))
    } else {
        None
    }
}

/// Find the state `steps` undo steps back.
pub fn find_undo_state(repo: &Repository, stack: &mut Stack, steps: isize) -> Result<(Oid, StackState)> {
    let mut log_id = stack.ensure_log_id()?;
    let mut state = stack.state.clone();
    let mut steps = steps;
    loop {
        let commit = repo.find_commit(log_id)?;
        match parse_undo_redo(&commit.summary_str()) {
            Some((true, n)) => steps += n,
            Some((false, n)) => steps -= n,
            None => steps -= 1,
        }
        let prev = match state.prev {
            Some(prev) => prev,
            None => return Err(anyhow!("not enough undo information available")),
        };
