/// override usage string, recursively for all subcommands.
pub(crate) fn style_usages(command: Command, depth: usize) -> Command {
    use clap::builder::styling::Style;
    let literal = Style::new().bold();
    let mut command = command;
    if let Some(usage) = command.get_override_usage() {
        let plain = usage.to_string();
        let mut out = String::new();
        for (i, line) in plain.lines().enumerate() {
            if i > 0 {
                out.push('\\n');
            }
            let trimmed = line.trim_start();
            let indent = &line[..line.len() - trimmed.len()];
            // Bold the first `depth + 1` words (bin name plus command path).
            let mut words = trimmed.splitn(depth + 2, ' ');
            let mut prefix_parts: Vec<&str> = Vec::new();
            for _ in 0..=depth {
                if let Some(w) = words.next() {
                    prefix_parts.push(w);
                }
            }
            let rest = words.next();
            out.push_str(indent);
            out.push_str(&format!("{literal}{}{literal:#}", prefix_parts.join(" ")));
            if let Some(rest) = rest {
                out.push(' ');
                out.push_str(rest);
            }
        }
        command = command.override_usage(clap::builder::StyledStr::from(out));
    }
    let subs: Vec<Command> = command.get_subcommands().cloned().collect();
    if !subs.is_empty() {
        let mut names: Vec<String> = Vec::new();
        for sub in &subs {
            names.push(sub.get_name().to_string());
        }
        for sub in subs {
            let styled = style_usages(sub, depth + 1);
            command = command.mut_subcommand(styled.get_name().to_string(), |_| styled.clone());
        }
    }
    command
}

pub(crate) fn make_command(stgcmd: &cmd::StGitCommand) -> Command {
    style_usages((stgcmd.make)(), 1)
}

